/* ============================================================
   FOOTSOCCER — app.js (consolidado)
   Este archivo reúne:
     - app.js (núcleo del juego)
     - ligaAustria.js, copaAustria.js, copaBelgica.js
     - zonaClubView.js, zonaClubCards.js, instalacionesView.js, estadioView.js
   matchEngine.js se mantiene como archivo separado.
   ============================================================ */

/* ============================================================
 * ligaAustria.js — Modulo de configuracion y ayudantes de la
 * Bundesliga de Austria (liga 3 fases + playoff europeo).
 *
 * Fase 1: Temporada Regular  J1-J22  (12 equipos, ida+vuelta)
 * Halving: al acabar J22 los puntos se dividen entre 2 (abajo),
 *          el equipo con puntos impares marca redondeadoAbajo.
 * Fase 2: Grupos J23-J32        (Meistergruppe 1-6 / Qualifikationsgruppe 7-12)
 * Playoff Europeo (Conference): al acabar J32
 *     SF  = 7º vs 8º global (1º vs 2º de la Qualifikationsgruppe)
 *     Final = 5º de la Meistergruppe vs ganador de la SF
 *     El ganador obtiene plaza de Fase Previa de la Conference League.
 * ============================================================ */
(function () {
  'use strict';

  var CONFIG = {
    id: 'bl1',
    countryId: 'austria',
    name: 'Bundesliga de Austria',
    shortName: 'Admiral Bundesliga',
    totalTeams: 12,

    regularSeason: {
      matchdays: 22,
    },

    halving: {
      enabled: true,
      atMatchday: 22,
      divisor: 2,
      redondear: 'abajo',
    },

    secondPhase: {
      startsAtMatchday: 23,
      totalMatchdays: 32,
      groupSize: 6,
      championship: {
        name: 'Meistergruppe',
        matchdays: 10,
      },
      relegation: {
        name: 'Qualifikationsgruppe',
        matchdays: 10,
      },
    },

    playoffEuropeo: {
      name: 'Playoff Europeo (Conference League)',
      startsAfterMatchday: 32,
      semis: {
        name: 'Semifinal',
        /* 7º global (1º Qualifikationsgruppe) vs 8º global (2º Qualifikationsgruppe) */
        match: '7vs8',
      },
      final: {
        name: 'Final',
        /* 5º de la Meistergruppe (5º global) vs ganador de la semifinal */
        match: '5vsSF',
      },
      prize: 'Fase Previa de la Conference League',
    },
  };

  /* Convierte el numero de jornada en la fase actual.
   *   regular      : 1-22
   *   grupos       : 23-32
   *   playoffEuropeo: >32 (tras acabar la temporada)
   */
  function getAustriaPhase(matchday) {
    if (!matchday) matchday = 0
    if (matchday <= 0) return 'regular'
    if (matchday < CONFIG.secondPhase.startsAtMatchday) return 'regular'
    if (matchday <= CONFIG.secondPhase.totalMatchdays) return 'grupos'
    return 'playoffEuropeo'
  }

  /* Dada la clasificacion completa (ya ordenada y con el halving aplicado)
   * devuelve los ids de los equipos de la Meistergruppe (puestos 1-6). */
  function getCampeonatoTeams(standings) {
    return (standings || []).slice(0, 6).map(function (s) { return s.teamId })
  }

  /* Devuelve los ids de los equipos de la Qualifikationsgruppe (puestos 7-12). */
  function getDescensoTeams(standings) {
    return (standings || []).slice(6, 12).map(function (s) { return s.teamId })
  }

  /* Genera las 10 jornadas (23-32) de un grupo de 6 equipos jugando
   * ida y vuelta entre si. Reutiliza la logica de round-robin: parametro
   * matchdayBase = 22 (J23 = 22+1 ... J32 = 22+10). */
  function buildGrupoFixtures(teamIds, matchdayBase) {
    matchdayBase = matchdayBase || 22
    var n = teamIds.length
    if (n !== 6) return []
    var rounds = n - 1 /* 5 idas */
    var fixtures = []
    var ids = teamIds.slice()
    for (var r = 0; r < rounds; r++) {
      for (var i = 0; i < n / 2; i++) {
        var home = (r % 2 === 0) ? ids[i] : ids[n - 1 - i]
        var away = (r % 2 === 0) ? ids[n - 1 - i] : ids[i]
        fixtures.push({ matchday: matchdayBase + r + 1, home: home, away: away, homeScore: null, awayScore: null, played: false, grupo: true })
      }
      ids.splice(1, 0, ids.pop())
    }
    var half = rounds
    for (var r2 = 0; r2 < half; r2++) {
      for (var i2 = 0; i2 < n / 2; i2++) {
        var f = fixtures[r2 * (n / 2) + i2]
        fixtures.push({ matchday: matchdayBase + r2 + 1 + half, home: f.away, away: f.home, homeScore: null, awayScore: null, played: false, grupo: true })
      }
    }
    return fixtures
  }

  /* Construye los fixtures de la Fase 2 (J23-J32) para los DOS grupos.
   * `championship` y `relegation` son arrays de teamIds.
   * Devuelve un unico array combinado (ambos grupos). */
  function buildSecondPhaseFixtures(championship, relegation) {
    return buildGrupoFixtures(championship, 22).concat(buildGrupoFixtures(relegation, 22))
  }

  /* Construye el arbol del Playoff Europeo de la Conference.
   * `g7` id del puesto 7 global, `g8` puesto 8 global, `g5` puesto 5 global.
   * Devuelve un objeto state.playoffs con esConferenceAustria=true.
   */
  function buildConferencePlayoff(g5, g7, g8) {
    return {
      round: 'SF',
      esConferenceAustria: true,
      fixtures: [
        { round: 'SF', home: g7, away: g8, homeScore: null, awayScore: null, played: false },
      ],
      fifth: g5,
      winner: null,
    }
  }

  window.AustriaLiga = {
    config: CONFIG,
    getAustriaPhase: getAustriaPhase,
    getCampeonatoTeams: getCampeonatoTeams,
    getDescensoTeams: getDescensoTeams,
    buildGrupoFixtures: buildGrupoFixtures,
    buildSecondPhaseFixtures: buildSecondPhaseFixtures,
    buildConferencePlayoff: buildConferencePlayoff,
  }
})()

;
/* ============================================================
 * copaAustria.js — Configuracion y ayudantes de la Copa de Austria
 * (ÖFB-Cup).
 *
 * Formato: eliminatoria a partido unico con 64 participantes en la 1ª ronda:
 *   12 Bundesliga (bl1) + 16 2. Bundesliga (bl2) + 36 modesto regionales.
 *   6 rondas: 1/32, 1/16, Octavos, Cuartos, Semifinal, Final.
 *   - Empate a los 90': prorroga (2x15'); si sigue empatado, penaltis.
 *   - Banquillo: maximo 7 suplentes convocados.
 *   - Cambios: maximo 5 en 3 ventanas durante el tiempo regular;
 *     durante la prorroga cada equipo recibe 1 cambio adicional
 *     (+1 sustitucion, total 6) y 1 ventana de sustitucion extra.
 * ============================================================ */
(function () {
  'use strict'

  /* Nombre y logo de la competicion. */
  var CONFIG = {
    id: 'copa_austria',
    countryId: 'austria',
    name: 'Copa de Austria',
    shortName: 'ÖFB-Cup',
    logo: 'https://cdn.resfu.com/media/img/league_logos/copa-austria.png?size=120x&lossy=1',
    trofeo: 'https://cdn.resfu.com/media/img/trophy_pic/cup_nofoto.png?size=120x&lossy=1',
    startTeams: 64,
  }

  /* 6 rondas eliminatorias (64 -> 1 campeon, partido unico).
     Nomenclatura: 1/32 (64), 1/16 (32), Octavos (16), Cuartos (8),
     Semifinal (4), Final (2). Semanas dentro de la temporada austriaca
     (32 jornadas). */
  var SCHEDULE = [
    { week: 3, label: '1/32' },
    { week: 6, label: '1/16' },
    { week: 10, label: 'Octavos' },
    { week: 15, label: 'Cuartos' },
    { week: 21, label: 'Semifinal' },
    { week: 28, label: 'Final' },
  ]

  /* Normas de convocatoria y sustituciones. */
  var SUB_RULES = {
    bench: 7,
    substitution: {
      maxTotal: 5,
      maxWindows: 3,
      extraTime: {
        extraSubs: 1,
        extraWindows: 1,
      },
    },
  }

  /* Devuelve las normas de sustitucion/banquillo para un partido.
   *   { isCup, isExtraTime } ->
   *   { bench, maxSubs, maxWindows }
   * En partidos de copa con prorroga se permite el 6º cambio y la 4ª
   * ventana; en el resto se mantienen 5 cambios en 3 ventanas. */
  function getSubRules(opts) {
    opts = opts || {}
    if (opts.isCup) {
      if (opts.isExtraTime) {
        return {
          bench: SUB_RULES.bench,
          maxSubs: SUB_RULES.substitution.maxTotal + SUB_RULES.substitution.extraTime.extraSubs,
          maxWindows: SUB_RULES.substitution.maxWindows + SUB_RULES.substitution.extraTime.extraWindows,
        }
      }
      return {
        bench: SUB_RULES.bench,
        maxSubs: SUB_RULES.substitution.maxTotal,
        maxWindows: SUB_RULES.substitution.maxWindows,
      }
    }
    return {
      bench: 9,
      maxSubs: SUB_RULES.substitution.maxTotal,
      maxWindows: SUB_RULES.substitution.maxWindows,
    }
  }

  /* Banda de ventana de sustitucion segun el minuto del partido:
   *   0-45   -> 1
   *   45-90  -> 2
   *   90-105 -> 3 (prorroga)
   *   105+   -> 4 (prorroga) */
  function getSubWindow(minute) {
    minute = minute || 0
    if (minute <= 45) return 1
    if (minute <= 90) return 2
    if (minute <= 105) return 3
    return 4
  }

  /* Equipos modesto REGIONALES austriacos (36 clubes) que, junto con la
   * Bundesliga (12) y la 2. Bundesliga (16), completan los 64 participantes
   * de la primera ronda. */
  var REGIONAL_NAMES = [
    'SV Grödig', 'SC Lustenau', 'SV Mattersburg', 'ASK Köflach',
    'USV Allerheiligen', 'SK Austria Klagenfurt Amateure', 'SV Oberwart', 'TSV Hartberg II',
    'SC Wiener Neustadt', 'DSV Leoben', 'SV Spittal/Drau', 'FC Dornbirn 1913',
    'SV Lafnitz', 'SC Rheindorf Altach II', 'SV Horn', 'SC Traiskirchen',
    'FC Blau-Weiß Linz II', 'SK Vorwärts Steyr', 'FC Kitzbühel', 'SV Gols',
    'SCR Altach Amateure', 'SV Seekirchen', 'UFC Fehring', 'SC Bruck/Mur',
    'SV St. Jakob/Rosental', 'ATSV Stadl-Paura', 'SV Wallern', 'SC Schwanenstadt',
    'SV Vöcklamarkt', 'USK Anif', 'SC Weiz', 'SV Allerheiligen II',
    'SK Treibach', 'SV Gloggnitz', 'ASK Voitsberg II', 'SV Leobendorf',
  ]

  /* Inicializa (una sola vez) el mapa global de equipos modesto regionales
   * austriacos para que el resto del juego (nombres, logos, valoraciones)
   * pueda resolver sus ids. */
  function initAustriaModestoMap() {
    if (window._MODESTO_AUSTRIA_MAP) return window._MODESTO_AUSTRIA_MAP
    var map = {}
    var count = Math.min(REGIONAL_NAMES.length, 36)
    for (var i = 0; i < count; i++) {
      var id = 'atr-' + (i + 1)
      map[id] = {
        id: id,
        name: REGIONAL_NAMES[i],
        nombre: REGIONAL_NAMES[i],
        rating: 40 + (i % 9),
        logo: 'https://cdn.resfu.com/media/img/trophy_pic/cup_nofoto.png?size=120x&lossy=1',
      }
    }
    window._MODESTO_AUSTRIA_MAP = map
    return map
  }

  /* Devuelve los ids de los equipos modesto regionales. */
  function getRegionalTeams(count) {
    var map = initAustriaModestoMap()
    var keys = Object.keys(map)
    var n = count == null ? keys.length : Math.min(count, keys.length)
    return keys.slice(0, n)
  }

  window.AustriaCopa = {
    config: CONFIG,
    schedule: SCHEDULE,
    subRules: SUB_RULES,
    getSubRules: getSubRules,
    getSubWindow: getSubWindow,
    initAustriaModestoMap: initAustriaModestoMap,
    getRegionalTeams: getRegionalTeams,
  }

  /* Inicializar el mapa de equipos regionales al cargar el modulo para que
     nombres/logos/valoraciones esten disponibles de inmediato. */
  initAustriaModestoMap()
})()
;
/* ============================================================
 * copaBelgica.js — Configuracion y ayudantes de la Copa de Bélgica
 * (Croky Cup).
 *
 * Formato: cuadro eliminatorio flexible. El numero de rondas se
 * adapta al total de clubes presentes en el pais en los datos
 * (hoy solo la Jupiler Pro League, l1b). El limite maximo del
 * cuadro belga es 1/1024: si en el futuro hay mas ligas/clubes,
 * el cuadro se ensancha automaticamente hasta ese tope; las
 * casillas vacias (rounds sin equipos suficientes) no se juegan
 * (byes automaticos directos a la siguiente ronda).
 *
 *   - Empate a los 90': prorroga (2x15'); si sigue empatado, penaltis.
 *   - Convocatoria: 21 jugadores (11 titulares + 10 suplentes).
 *   - Cambios: maximo 5 en 3 ventanas en tiempo regular; en prorroga
 *     (desde 1/16 de final) cada equipo recibe 1 cambio adicional
 *     (total 6) y 1 ventana de sustitucion extra.
 * ============================================================ */
(function () {
  'use strict'

  /* Nombre y logo de la competicion. */
  var CONFIG = {
    id: 'copa_belgica',
    countryId: 'belgium',
    name: 'Copa de Bélgica',
    shortName: 'Croky Cup',
    logo: 'https://cdn.resfu.com/media/img/league_logos/copa-belgica.png?size=120x&lossy=1',
    trofeo: 'https://cdn.resfu.com/img_data/competiciones/copa/651.png?size=120x&lossy=1',
    maxRoundDenominator: 1024,
  }

  /* Semanas fijas para las rondas "limite" del cuadro (tope 1/1024).
     Se reutilizan secuencialmente hacia atras segun cuantas rondas
     hagan falta. */
  var WEEK_MAP = [
    { den: 1024, week: 2 },
    { den: 512, week: 3 },
    { den: 256, week: 4 },
    { den: 128, week: 5 },
    { den: 64, week: 6 },
    { den: 32, week: 7 },
    { den: 16, week: 10 },
    { den: 8, week: 15 },
    { den: 4, week: 20 },
    { den: 2, week: 25 },
    { den: 1, week: 35 },
  ]

  function roundLabel(den) {
    if (den === 8) return 'Octavos'
    if (den === 4) return 'Cuartos'
    if (den === 2) return 'Semifinal'
    if (den === 1) return 'Final'
    return '1/' + den
  }

  /* Calcula el esquema del cuadro segun el numero de clubes presentes.
   *   nTeams = total de equipos inscritos (todas las ligas belgas).
   *   Devuelve [ { week, label, teams }, ... ] empezando en la ronda
   *   minima necesaria para albergar a todos (potencia de 2 >= nTeams),
   *   con tope 1/1024. */
  function getCupBlueprint(nTeams) {
    if (!nTeams || nTeams < 2) nTeams = 18
    var firstDen = 1
    while (firstDen < nTeams) firstDen = firstDen * 2
    firstDen = Math.min(firstDen, CONFIG.maxRoundDenominator)
    var sched = []
    var den = firstDen
    while (den >= 1) {
      var w = WEEK_MAP.find(function(x) { return x.den === den })
      sched.push({ week: w ? w.week : 35, label: roundLabel(den), teams: den })
      if (den === 1) break
      den = den / 2
    }
    return sched
  }

  /* Cuenta los equipos belgas inscritos en los datos (todas las ligas). */
  function getBelgiumTeamCount() {
    if (typeof getLeagueTeams === 'function') {
      var l1b = getLeagueTeams('l1b') || []
      return l1b.length
    }
    return 18
  }

  /* Devuelve el schedule dinamico de la Croky Cup basado en el
     numero real de clubes presentes. */
  function getSchedule() {
    return getCupBlueprint(getBelgiumTeamCount())
  }

  /* La prorroga (y por tanto el 6º cambio + 4ª ventana) solo se aplica
     a partir de los 1/16 de final. Recibe el indice de ronda actual y
     devuelve true si esa ronda admite prorroga (teams <= 16). */
  function hasExtraTime(roundIdx) {
    var sched = getSchedule()
    var entry = sched[roundIdx]
    if (!entry) return false
    return entry.teams <= 16
  }

  /* Normas de convocatoria y sustituciones.
   *   { isCup, isExtraTime } ->
   *   { bench, maxSubs, maxWindows }
   * En copa con prorroga (desde 1/16) se permite el 6º cambio y la 4ª
   * ventana; en el resto se mantienen 5 cambios en 3 ventanas. */
  function getSubRules(opts) {
    opts = opts || {}
    if (opts.isCup) {
      if (opts.isExtraTime) {
        return { bench: 10, maxSubs: 6, maxWindows: 4 }
      }
      return { bench: 10, maxSubs: 5, maxWindows: 3 }
    }
    return { bench: 10, maxSubs: 5, maxWindows: 3 }
  }

  /* Banda de ventana de sustitucion segun el minuto del partido:
   *   0-45   -> 1
   *   45-90  -> 2
   *   90-105 -> 3 (prorroga)
   *   105+   -> 4 (prorroga) */
  function getSubWindow(minute) {
    minute = minute || 0
    if (minute <= 45) return 1
    if (minute <= 90) return 2
    if (minute <= 105) return 3
    return 4
  }

  /* Sanciones independientes de la Copa (solo Croky Cup).
   * El sistema de tarjetas de la Copa es limpio e independiente de la
   * Liga: acumular 2 amarillas en eliminatorias distintas suspende al
   * jugador para el siguiente partido de Copa. Las rojas directas se
   * procesan aparte (procesarSuspensiones) y pueden afectar a la Liga.
   *
   * Se llama al terminar un partido de Copa belga:
   *   1) "Sirve" la sancion pendiente (la exclusion ya ocurrio al armar
   *      el once en el partido anterior) y limpia el contador.
   *   2) Registra las amarillas recibidas en este partido; al llegar a
   *      2 amarrillas acumuladas marca _cupSuspended para la siguiente
   *      eliminatoria. */
  function processCupYellowCards(players) {
    ;(players || []).forEach(function(p) { p._cupSuspended = false })
    ;(players || []).forEach(function(p) {
      if (!p || !p._yellowThisMatch) return
      p._cupYellowCards = (p._cupYellowCards || 0) + 1
      if (p._cupYellowCards >= 2) {
        p._cupSuspended = true
        p._cupYellowCards = 0
      }
    })
  }

  /* Indica si un jugador esta suspendido por acumulacion de amarillas
   * de la Copa (actua solo como filtro en los partidos de Copa). */
  function isCupSuspended(p) {
    return !!(p && p._cupSuspended)
  }

  window.BelgiumCopa = {
    config: CONFIG,
    getCupBlueprint: getCupBlueprint,
    getBelgiumTeamCount: getBelgiumTeamCount,
    getSchedule: getSchedule,
    hasExtraTime: hasExtraTime,
    getSubRules: getSubRules,
    getSubWindow: getSubWindow,
    processCupYellowCards: processCupYellowCards,
    isCupSuspended: isCupSuspended,
  }
})()
;
/* ============================================================
 * copaHolanda.js — Configuracion y ayudantes de la Copa de los
 * Países Bajos (KNVB Beker).
 *
 * Formato: cuadro eliminatorio a partido unico que comienza en los
 * 1/32 de final, cuando entran los 18 equipos de la Eredivisie junto
 * a los conjuntos de Segunda División (representados por equipos
 * modesto regionales). La localía se sortea: si un equipo de Primera
 * visita el estadio de uno de categoría inferior, el de Segunda es
 * el local.
 *
 *   - Empate a los 90': prórroga (2x15'); si sigue empatado, penaltis.
 *   - Convocatoria: 21 jugadores (11 titulares + 10 suplentes).
 *   - Cambios: máximo 5 en 3 ventanas en tiempo regular; en prórroga
 *     cada equipo recibe 1 cambio adicional (total 6) y 1 ventana de
 *     sustitución extra.
 *   - Premio mayor: el campeón se clasifica directo a la Europa League
 *     (Fase de liga), sin importar su posición en la liga.
 * ============================================================ */
(function () {
  'use strict'

  /* Nombre, logo y trofeo de la competición. */
  var CONFIG = {
    id: 'copa_holanda',
    countryId: 'netherlands',
    name: 'Copa de los Países Bajos',
    shortName: 'KNVB Beker',
    logo: 'https://cdn.resfu.com/media/img/league_logos/beker.png?size=120x&lossy=1',
    trofeo: 'https://cdn.resfu.com/img_data/competiciones/copa/524.png?size=120x&lossy=1',
  }

  /* Seis rondas eliminatorias (32 → 1 campeón, partido único). */
  var SCHEDULE = [
    { week: 4, label: '1/32' },
    { week: 9, label: '1/16' },
    { week: 15, label: 'Octavos' },
    { week: 21, label: 'Cuartos' },
    { week: 27, label: 'Semifinal' },
    { week: 34, label: 'Final' },
  ]

  /* La prórroga (y por tanto el 6º cambio + 4ª ventana) se aplica en
     todas las rondas de la KNVB Beker, salvo la primera (1/32). */
  function hasExtraTime(roundIdx) {
    return roundIdx > 0
  }

  /* Normas de convocatoria y sustituciones.
   *   { isCup, isExtraTime } ->
   *   { bench, maxSubs, maxWindows }
   * En partido con prórroga se permite el 6º cambio y la 4ª ventana. */
  function getSubRules(opts) {
    opts = opts || {}
    if (opts.isCup) {
      if (opts.isExtraTime) {
        return { bench: 10, maxSubs: 6, maxWindows: 4 }
      }
      return { bench: 10, maxSubs: 5, maxWindows: 3 }
    }
    return { bench: 10, maxSubs: 5, maxWindows: 3 }
  }

  /* Banda de ventana de sustitución según el minuto del partido:
   *   0-45   -> 1
   *   45-90  -> 2
   *   90-105 -> 3 (prórroga)
   *   105+   -> 4 (prórroga) */
  function getSubWindow(minute) {
    minute = minute || 0
    if (minute <= 45) return 1
    if (minute <= 90) return 2
    if (minute <= 105) return 3
    return 4
  }

  /* Equipos modesto regionales holandeses que, junto con los 18 equipos
     de la Eredivisie, completan el cuadro de 32 de la primera ronda.
     Se les trata como conjuntos de categoría inferior (Segunda), por lo
     que ejercen de local cuando se cruzan con un club de Primera. */
  var REGIONAL_NAMES = [
    'FC Volendam', 'De Graafschap', 'Roda JC Kerkrade', 'MVV Maastricht',
    'VVV-Venlo', 'FC Dordrecht', 'FC Den Bosch', 'FC Eindhoven',
    'TOP Oss', 'Helmond Sport', 'SC Emmen', 'Vitesse',
    'NAC Breda', 'Almere City', 'RKC Waalwijk', 'VV Katwijk',
    'SV Spakenburg', 'FC Lisse', 'Quick Boys', 'De Treffers',
    'SC Telstar II', 'Jong Heerenveen',
  ]

  /* Inicializa (una sola vez) el mapa global de equipos modesto
     regionales holandeses para que el resto del juego (nombres, logos,
     valoraciones) pueda resolver sus ids. */
  function initModestoMap() {
    if (window._MODESTO_HOLANDA_MAP) return window._MODESTO_HOLANDA_MAP
    var map = {}
    for (var i = 0; i < REGIONAL_NAMES.length; i++) {
      var id = 'nlr-' + (i + 1)
      map[id] = {
        id: id,
        name: REGIONAL_NAMES[i],
        nombre: REGIONAL_NAMES[i],
        rating: 38 + (i % 10),
        logo: 'https://cdn.resfu.com/media/img/trophy_pic/cup_nofoto.png?size=120x&lossy=1',
      }
    }
    window._MODESTO_HOLANDA_MAP = map
    return map
  }

  function getRegionalTeams(count) {
    var map = initModestoMap()
    var keys = Object.keys(map)
    var n = count == null ? keys.length : Math.min(count, keys.length)
    return keys.slice(0, n)
  }

  window.KnvbCopa = {
    config: CONFIG,
    schedule: SCHEDULE,
    hasExtraTime: hasExtraTime,
    getSubRules: getSubRules,
    getSubWindow: getSubWindow,
    initModestoMap: initModestoMap,
    getRegionalTeams: getRegionalTeams,
  }
})()
;
