var GROUPED_LEAGUES = {
  lpl4g: { name: '4\u00aa Divisi\u00f3n Polaca', groups: ['lpl4g1','lpl4g2','lpl4g3','lpl4g4'], groupNames: ['Grupo 1','Grupo 2','Grupo 3','Grupo 4'] },
  l3sg:  { name: 'Primera Federaci\u00f3n', groups: ['l3sg1','l3sg2'], groupNames: ['Grupo 1','Grupo 2'] },
}

function isGroupedLeague(lid) { return lid && (lid.startsWith('lpl4g') || lid.startsWith('l3sg')) }

function getGroupedConfig(lid) {
  if (!lid) return null
  for (var key in GROUPED_LEAGUES) { if (lid.startsWith(key)) return GROUPED_LEAGUES[key] }
  return null
}

function getCanonicalLeagueName(leagueId, fallback) {
  var map = { l2s: 'Segunda Divisi\u00f3n' }
  if (leagueId && isGroupedLeague(leagueId)) {
    var cfg = getGroupedConfig(leagueId)
    if (cfg) return cfg.name
  }
  return map[leagueId] || fallback
}

function getLeagueDisplayName(leagueId) {
  if (!leagueId) return ''
  for (var ci in window.DB) {
    var d = window.DB[ci]
    if (!d || !d.country || !d.country.leagues) continue
    for (var li = 0; li < d.country.leagues.length; li++) {
      if (d.country.leagues[li].id === leagueId) {
        var n = d.country.leagues[li].name
        if (n) return n
      }
    }
  }
  return getCanonicalLeagueName(leagueId, leagueId)
}

function getVisibleLeagueCount(countryId) {
  var data = window.DB[countryId]
  if (!data || !data.country.leagues) return 0
  var count = 0
  var seen = {}
  for (var i = 0; i < data.country.leagues.length; i++) {
    var lid = data.country.leagues[i].id
    if (lid && isGroupedLeague(lid)) {
      var cfg = getGroupedConfig(lid)
      if (cfg && !seen[cfg.name]) { seen[cfg.name] = true; count++ }
    } else {
      count++
    }
  }
  return count
}

function getBTeamParent(bTeamId) { return B_TEAM_MAP[bTeamId] || null }
function getFilialId(teamId) { return FILIAL_MAP[teamId] || null }
function getParentTeamId(filialId) { return Object.keys(FILIAL_MAP).find(k => FILIAL_MAP[k] === filialId) || null }
function findBTeamOf(parentId) { return Object.keys(B_TEAM_MAP).find(k => B_TEAM_MAP[k] === parentId) || null }

function areTeamsFiliales(idA, idB) {
  if (!idA || !idB) return false
  var a = typeof idA === 'string' ? idA : (idA.id || idA.teamId)
  var b = typeof idB === 'string' ? idB : (idB.id || idB.teamId)
  if (!a || !b) return false
  if (a === b) return true

  /* Direct map lookup */
  if (FILIAL_MAP[a] === b || FILIAL_MAP[b] === a) return true
  if (B_TEAM_MAP[a] === b || B_TEAM_MAP[b] === a) return true

  /* Family check transitivo: sube por los mapas hasta la raiz y comprueba
     si los conjuntos de ancestros se cruzan (padre → filial → filial del
     filial, p. ej. Austria Wien → Austria Wien II → Austria Wien U18). */
  function familyAncestors(id) {
    var seen = {}, current = id
    for (var guard = 0; guard < 20 && current; guard++) {
      var next = FILIAL_MAP[current] || B_TEAM_MAP[current]
      if (!next || next === current || seen[next]) break
      seen[next] = true
      current = next
    }
    return seen
  }
  var ancA = familyAncestors(a)
  var ancB = familyAncestors(b)
  for (var key in ancA) { if (ancB[key]) return true }
  for (var key2 in ancB) { if (ancA[key2]) return true }

  /* Name fallback check */
  var nameA = getTeamName(a) || (typeof idA === 'object' && idA.name) || ''
  var nameB = getTeamName(b) || (typeof idB === 'object' && idB.name) || ''
  if (nameA && nameB) {
    var cA = nameA.toLowerCase().trim()
    var cB = nameB.toLowerCase().trim()
    if (cA === cB) return true
    var baseA = cA.replace(/ ii$| b$| b team$| fortunas?$| fabril$| castilla$| atlètic$| atletico$| atl\.$| madrileño$/i, '').trim()
    var baseB = cB.replace(/ ii$| b$| b team$| fortunas?$| fabril$| castilla$| atlètic$| atletico$| atl\.$| madrileño$/i, '').trim()
    if (baseA.length >= 4 && baseB.length >= 4 && baseA === baseB) return true
  }

  return false
}

function pairTeamsWithoutFiliales(teamList) {
  var items = (teamList || []).slice().sort(function() { return Math.random() - 0.5 })
  
  function getId(item) {
    if (!item) return null
    if (typeof item === 'string') return item
    return item.id || item.teamId || null
  }

  for (var attempt = 0; attempt < 100; attempt++) {
    var pairs = []
    var conflict = false
    var available = items.slice()

    while (available.length >= 2) {
      var teamA = available.shift()
      var idA = getId(teamA)
      
      var validOpponentIdx = -1
      for (var j = 0; j < available.length; j++) {
        var idB = getId(available[j])
        if (!areTeamsFiliales(idA, idB)) {
          validOpponentIdx = j
          break
        }
      }

      if (validOpponentIdx >= 0) {
        var teamB = available.splice(validOpponentIdx, 1)[0]
        pairs.push([teamA, teamB])
      } else {
        conflict = true
        break
      }
    }

    if (!conflict) {
      return { pairs: pairs, bye: available.length === 1 ? available[0] : null }
    }

    items.sort(function() { return Math.random() - 0.5 })
  }

  var pairs = []
  var available = items.slice()
  while (available.length >= 2) {
    pairs.push([available.shift(), available.shift()])
  }
  return { pairs: pairs, bye: available.length === 1 ? available[0] : null }
}

function isPlayerFromMyFilial(player) {
  var fid = getFilialId(state.teamId)
  if (!fid) return false
  if (state.filialSquad && state.filialSquad.some(function(p) { return p.id === player.id })) return true
  return player.teamId === fid || false
}

function isPlayerFromMyU18(player) {
  if (!state.filial2Squad) return false
  return state.filial2Squad.some(function(p) { return p.id === player.id })
}

/* ============ TEAM CATEGORY & AGE VALIDATION ============ */
var TEAM_CATEGORY = { PRIMER_EQUIPO: 'PRIMER_EQUIPO', EQUIPO_B: 'EQUIPO_B', SUB_18: 'SUB_18' }

function getCategoryMaxAge(cat) {
  if (cat === TEAM_CATEGORY.SUB_18) return 18
  if (cat === TEAM_CATEGORY.EQUIPO_B) return 23
  return null
}

function getTeamCategory(teamId) {
  if (!teamId) return TEAM_CATEGORY.PRIMER_EQUIPO
  if (B_TEAM_MAP[teamId]) {
    var parent = B_TEAM_MAP[teamId]
    if (B_TEAM_MAP[parent]) return TEAM_CATEGORY.SUB_18
    return TEAM_CATEGORY.EQUIPO_B
  }
  return TEAM_CATEGORY.PRIMER_EQUIPO
}

function getManagedTeamCategory() {
  return getTeamCategory(state.teamId)
}

function getPlayerCategory(player) {
  if (state.filial2Squad && state.filial2Squad.some(function(p) { return p.id === player.id })) return TEAM_CATEGORY.SUB_18
  if (state.filialSquad && state.filialSquad.some(function(p) { return p.id === player.id })) return TEAM_CATEGORY.EQUIPO_B
  return TEAM_CATEGORY.PRIMER_EQUIPO
}

function isPlayerOverCategoryAge(player) {
  var cat = getPlayerCategory(player)
  var max = getCategoryMaxAge(cat)
  return max != null && player.age > max
}

function getOveragePlayers() {
  var list = []
  ;(state.filialSquad || []).forEach(function(p) { if (p.age > 23) { p._overage = true; list.push({ player: p, category: TEAM_CATEGORY.EQUIPO_B }) } })
  ;(state.filial2Squad || []).forEach(function(p) { if (p.age > 18) { p._overage = true; list.push({ player: p, category: TEAM_CATEGORY.SUB_18 }) } })
  return list
}

function recomendarSalida(player, offerAmount) {
  var cat = getPlayerCategory(player)
  var maxAge = getCategoryMaxAge(cat)
  var isOverage = maxAge != null && player.age > maxAge
  if (isOverage) return '\ud83d\udca1 Excede la edad m\u00e1xima de ' + cat + ' (' + player.age + '/' + maxAge + '). V\u00e9ndelo o promuevelo.'
  var ratio = player.value > 0 ? (offerAmount / player.value) : 0
  if (ratio > 1.2) return '\ud83d\udca1 Buena venta: ' + Math.round(ratio * 100) + '% sobre valor de mercado. Recomendado vender.'
  if (ratio > 0.9) return '\u2696\ufe0f Oferta justa (' + Math.round(ratio * 100) + '% del valor).'
  return '\ud83c\udfaf Oferta por debajo del valor. Puedes rechazar o contraofertar.'
}

function findPlayerInPools(playerId) {
  var pools = [
    { pool: state.players, name: TEAM_CATEGORY.PRIMER_EQUIPO, accessor: 'players' },
    { pool: state.filialSquad, name: TEAM_CATEGORY.EQUIPO_B, accessor: 'filialSquad' },
    { pool: state.filial2Squad, name: TEAM_CATEGORY.SUB_18, accessor: 'filial2Squad' }
  ]
  for (var i = 0; i < pools.length; i++) {
    if (pools[i].pool) {
      var idx = pools[i].pool.findIndex(function(p) { return p.id === playerId })
      if (idx >= 0) return { pool: pools[i].pool, poolName: pools[i].name, accessor: pools[i].accessor, idx: idx }
    }
  }
  return null
}

function isPlayerFromMyParent(player) {
  var pid = getBTeamParent(state.teamId)
  if (!pid) return false
  if (player.teamId === pid) return true
  /* Also check CPU team squads */
  for (var i = 0; i < state.leagueTeams.length; i++) {
    var t = state.leagueTeams[i]
    if (t.teamId === pid && t.players.some(function(p) { return p.id === player.id })) return true
  }
  return false
}

