/* Aplica la regla del "halving": divide los puntos entre 2 hacia abajo.
 * Si el equipo tenía puntos impares queda redondeadoAbajo = true,
 * primer criterio de desempate. */
function dividirPuntosFase2(tablaEquipos) {
  return (tablaEquipos || [])
    .map(function (equipo) {
      var pts = equipo.pts != null ? equipo.pts : (equipo.ptos != null ? equipo.ptos : 0)
      var nuevos = Math.floor(pts / 2)
      return Object.assign({}, equipo, {
        pts: nuevos,
        ptos: nuevos,
        redondeadoAbajo: (pts % 2) === 1,
      })
    })
    .sort(function (a, b) {
      if (b.pts !== a.pts) return b.pts - a.pts
      if (a.redondeadoAbajo && !b.redondeadoAbajo) return -1
      if (!a.redondeadoAbajo && b.redondeadoAbajo) return 1
      return 0
    })
}

function isAustriaBundesliga(lid) {
  return austriaBundesligaConfig.id === lid
}

function computeStandings(fixtures, leagueId) {
  const teamIds = new Set()
  for (const f of fixtures) { teamIds.add(f.home); teamIds.add(f.away) }
  const s = {}
  for (const id of teamIds) {
    const t = getLeagueTeams(leagueId).find(x => x.id === id) || {}
    s[id] = { teamId: id, name: t.name || id, logo: t.logo || '', played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0, pts: 0 }
  }
  for (const f of fixtures) {
    if (!f.played) continue
    const h = s[f.home]; const a = s[f.away]
    if (!h || !a) continue
    h.played++; a.played++
    h.gf += f.homeScore; h.ga += f.awayScore
    a.gf += f.awayScore; a.ga += f.homeScore
    if (f.homeScore > f.awayScore) { h.won++; a.lost++; h.pts += 3 }
    else if (f.homeScore < f.awayScore) { a.won++; h.lost++; a.pts += 3 }
    else { h.drawn++; a.drawn++; h.pts++; a.pts++ }
  }
  var list = Object.values(s)
  if (isAustriaBundesliga(leagueId) && state.halvingApplied && state.halvingAppliedLeague) {
    applyHalvingToStandings(list, state.halvingAppliedLeague)
  }
  return sortStandings(list, fixtures)
}

/* Ordena la clasificación según los criterios de desempate oficiales:
 * 1º redondeadoAbajo (solo Austria), 2º enfrentamiento directo,
 * 3º diferencia de goles general, 4º goles a favor totales. */
function sortStandings(list, fixtures) {
  return list.slice().sort(function (a, b) {
    if (b.pts !== a.pts) return b.pts - a.pts
    if (a.redondeadoAbajo && !b.redondeadoAbajo) return -1
    if (!a.redondeadoAbajo && b.redondeadoAbajo) return 1
    var h2h = headToHeadCompare(a, b, fixtures)
    if (h2h !== 0) return h2h
    if ((b.gf - b.ga) !== (a.gf - a.ga)) return (b.gf - b.ga) - (a.gf - a.ga)
    return (b.gf) - (a.gf)
  })
}

/* Enfrentamiento directo: solo cuenta si ya jugaron sus dos partidos. */
function headToHeadCompare(ta, tb, fixtures) {
  var pa = 0, pb = 0
  var t = (fixtures || []).filter(function (f) {
    return f.played && ((f.home === ta.teamId && f.away === tb.teamId) || (f.home === tb.teamId && f.away === ta.teamId))
  })
  if (t.length < 2) return 0
  t.forEach(function (f) {
    if (f.home === ta.teamId) {
      if (f.homeScore > f.awayScore) pa += 3
      else if (f.homeScore < f.awayScore) pb += 3
      else { pa += 1; pb += 1 }
    } else {
      if (f.awayScore > f.homeScore) pa += 3
      else if (f.awayScore < f.homeScore) pb += 3
      else { pa += 1; pb += 1 }
    }
  })
  if (pb !== pa) return pb - pa
  return 0
}

/* Copia la bandera de redondeo y los puntos ya divididos al listado dado. */
function applyHalvingToStandings(list, halvingMap) {
  list.forEach(function (st) {
    var rec = halvingMap[st.teamId]
    if (!rec) return
    if (rec.pts != null) st.pts = rec.pts
    st.redondeadoAbajo = !!rec.redondeadoAbajo
  })
}

function updateLeagueStandings() {
  const standings = {}
  const allIds = [state.teamId, ...state.leagueTeams.map(t => t.teamId)]
  for (const id of allIds) {
    standings[id] = { teamId: id, played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0, pts: 0 }
  }
  for (const f of state.fixtures) {
    if (!f.played) continue
    const h = standings[f.home]
    const a = standings[f.away]
    if (!h || !a) continue
    h.played++; a.played++
    h.gf += f.homeScore; h.ga += f.awayScore
    a.gf += f.awayScore; a.ga += f.homeScore
    if (f.homeScore > f.awayScore) { h.won++; a.lost++; h.pts += 3 }
    else if (f.homeScore < f.awayScore) { a.won++; h.lost++; a.pts += 3 }
    else { h.drawn++; a.drawn++; h.pts++; a.pts++ }
  }

  /* Halving de la Bundesliga austriaca: al llegar a la jornada 22 los
     puntos se dividen entre 2 (redondeando hacia abajo) UNA sola vez. */
  if (isAustriaBundesliga(state.leagueId)) {
    var halvingAt = austriaBundesligaConfig.halving.atMatchday
    if (state.currentMatchday >= halvingAt && !state.halvingApplied) {
      var rows = Object.values(standings)
      var halved = dividirPuntosFase2(rows)
      var map = {}
      halved.forEach(function (r) {
        map[r.teamId] = { pts: r.pts, redondeadoAbajo: !!r.redondeadoAbajo }
        if (standings[r.teamId]) standings[r.teamId].pts = r.pts
      })
      state.halvingApplied = true
      state.halvingAppliedLeague = map
    }
    if (state.halvingApplied && state.halvingAppliedLeague) {
      applyHalvingToStandings(Object.values(standings), state.halvingAppliedLeague)
    }
  }

  const userStanding = standings[state.teamId]
  if (userStanding) {
    state.stats.wins = userStanding.won
    state.stats.draws = userStanding.drawn
    state.stats.losses = userStanding.lost
    state.stats.goalsFor = userStanding.gf
    state.stats.goalsAgainst = userStanding.ga
  }
  return sortStandings(Object.values(standings), state.fixtures)
}

/* ============== BUNDESLIGA DE AUSTRIA: FASE 2 (GRUPOS) ============== */
/* Al terminar la jornada 22 se dividen los 12 equipos en dos grupos de 6
 * (Meistergruppe = puestos 1-6, Qualifikationsgruppe = puestos 7-12) y se
 * generan las jornadas 23 a 32 (ida+vuelta dentro de cada grupo). */
function crearFase2Austria() {
  if (!window.AustriaLiga) return false
  if (state.fase2Built) return true

  var tabla = updateLeagueStandings()
  if (!tabla || tabla.length < 12) return false

  var campeonato = window.AustriaLiga.getCampeonatoTeams(tabla)
  var descenso = window.AustriaLiga.getDescensoTeams(tabla)

  var grupoFixtures = window.AustriaLiga.buildSecondPhaseFixtures(campeonato, descenso)

  /* Mezcla los fixtures existentes (J1-22) con los de la fase 2 (J23-32),
     manteniendo el orden cronologico por jornada. */
  var phaseFixtures = state.fixtures.filter(function(f) { return !f.grupo })
  state.fixtures = phaseFixtures.concat(grupoFixtures)

  state.fase2Built = true
  state.totalMatchdays = window.AustriaLiga.config.secondPhase.totalMatchdays
  state.austriaPhaseData = {
    campeonato: campeonato,
    descenso: descenso,
    matchdayBase: 22,
  }
  state.leaguePhase = campeonato.indexOf(state.teamId) >= 0 ? 'campeonato' : 'descenso'

  addNotification('general', '⚽ ¡Comienza la 2ª Fase!', 'Se han formado la Meistergruppe y la Qualifikationsgruppe')
  return true
}

/* ============== BUNDESLIGA DE AUSTRIA: PLAYOFF EUROPEO (CONFERENCE) ============== */
/* Al acabar la jornada 32 se juega el Playoff Europeo por una plaza en la
 * Fase Previa de la Conference League:
 *   SF    = 7º global vs 8º global (1º vs 2º de la Qualifikationsgruppe)
 *   Final = 5º de la Meistergruppe (5º global) vs ganador de la SF */
function iniciarPlayoffConferenceAustria() {
  if (!window.AustriaLiga) return false
  if (state.playoffs) return false
  if (!state.fase2Built) return false

  var tabla = updateLeagueStandings()
  if (!tabla || tabla.length < 6) return false

  var g5 = tabla[4] ? tabla[4].teamId : null
  var g7 = tabla[6] ? tabla[6].teamId : null
  var g8 = tabla[7] ? tabla[7].teamId : g7
  if (!g5 || !g7) return false

  state.playoffs = window.AustriaLiga.buildConferencePlayoff(g5, g7, g8)
  addNotification('general', '🌍 Playoff Europeo (Conference League)', 'Se disputa la plaza de Fase Previa de la Conference League')
  return true
}

/* Si el usuario NO participa en el Playoff Europeo de Austria, lo resolvemos
 * integramente por CPU (SF y Final) y asignamos la plaza de Conference. */
function resolverPlayoffConferenceCPU() {
  if (!state.playoffs || !state.playoffs.esConferenceAustria) return false
  var pf = state.playoffs
  var userIn = pf.fixtures.some(function(f) { return f.home === state.teamId || f.away === state.teamId }) ||
               pf.fifth === state.teamId
  if (userIn) return false

  var sf = pf.fixtures[0]
  var r1 = autoSimulateOtherMatch(sf.home, sf.away, 'europa')
  var sfWinner = r1.homeScore >= r1.awayScore ? sf.home : sf.away
  var r2 = autoSimulateOtherMatch(pf.fifth, sfWinner, 'europa')
  var finalWinner = r2.homeScore >= r2.awayScore ? pf.fifth : sfWinner

  state.conferencePlayoffWinner = finalWinner
  state.playoffs = null
  var slot = (window.AustriaLiga && window.AustriaLiga.config.playoffEuropeo.prize) || 'Fase Previa de la Conference League'
  addNotification('general', '\ud83c\udf0d ' + getTeamName(finalWinner) + ' jugar\u00e1 la Fase Previa de la Conference League', 'Playoff Europeo de Austria')
  return true
}

/* ============== EREDIVISIE (PAÍSES BAJOS): PLAYOFF CONFERENCE 5º-8º ============== */
/* Tras la última jornada, los puestos 5º, 6º, 7º y 8º juegan un cuadro a
 * partido único: SF (5v8 y 6v7) y Final. El ganador obtiene la plaza de
 * Fase Previa de la Conference League. */
function isEredivisie(lid) { return lid === 'eredivisie' }

function iniciarPlayoffConferenceEredivisie() {
  if (state.playoffs) return false
  if (!isEredivisie(state.leagueId)) return false
  if (state.currentMatchday < state.totalMatchdays) return false
  if (state.conferencePlayoffWinner !== null) return false

  var tabla = updateLeagueStandings()
  if (!tabla || tabla.length < 8) return false
  var ids = tabla.slice(4, 8).map(function(s) { return s.teamId })
  if (ids.length !== 4) return false

  state.playoffs = {
    round: 'SF',
    esConferenceNed: true,
    fixtures: [
      { round: 'SF', home: ids[0], away: ids[3], homeScore: null, awayScore: null, played: false },
      { round: 'SF', home: ids[1], away: ids[2], homeScore: null, awayScore: null, played: false },
    ],
  }
  addNotification('general', '\ud83c\udf0d Playoff Europeo (Conference League)', '5º-8º de la Eredivisie se disputan la plaza de Fase Previa de la Conference League')
  return true
}

/* Si el usuario NO participa en el Playoff Conference de la Eredivisie
 * (acabó 9º o peor), lo resolvemos íntegramente por CPU. */
function resolverPlayoffConferenceEredivisieCPU() {
  if (!state.playoffs || !state.playoffs.esConferenceNed) return false
  var pf = state.playoffs
  var userIn = pf.fixtures.some(function(f) { return f.home === state.teamId || f.away === state.teamId })
  if (userIn) return false

  var sfWinners = []
  pf.fixtures.forEach(function(f) {
    var r = simularPartidoPorRating(f.home, f.away, 'europa')
    sfWinners.push(r.homeScore >= r.awayScore ? f.home : f.away)
  })
  var fr = simularPartidoPorRating(sfWinners[0], sfWinners[1], 'europa')
  var finalWinner = fr.homeScore >= fr.awayScore ? sfWinners[0] : sfWinners[1]

  state.conferencePlayoffWinner = finalWinner
  state.playoffs = null
  addNotification('general', '\ud83c\udf0d ' + getTeamName(finalWinner) + ' jugar\u00e1 la Fase Previa de la Conference League', 'Playoff Europeo de la Eredivisie')
  return true
}

/* Punto de entrada único tras la última jornada de la Eredivisie. */
function tratarFinTemporadaEredivisie() {
  if (!isEredivisie(state.leagueId)) return false
  if (state.currentMatchday < state.totalMatchdays) return false
  if (state.playoffs || state.conferencePlayoffWinner !== null) return false
  if (!iniciarPlayoffConferenceEredivisie()) return false

  if (resolverPlayoffConferenceEredivisieCPU()) {
    saveGame()
    procesarFinTemporada()
    return true
  }
  var cpuLoop = 0
  while (state.playoffs && cpuLoop < 3) {
    var hasUserP = state.playoffs.fixtures.some(function(f) { return !f.played && (f.home === state.teamId || f.away === state.teamId) })
    if (hasUserP) break
    avanzarRondaPlayoff()
    cpuLoop++
  }
  if (!state.playoffs) {
    saveGame()
    procesarFinTemporada()
    return true
  }
  renderTab('home')
  return true
}

function simularPartidoPorRating(homeId, awayId, comp) {
  comp = comp || 'league'
  /* Use persistent teams from allLeagueData when available, else team objects */
  var home = null, away = null
  for (const [lid, d] of Object.entries(state.allLeagueData || {})) {
    if (!home && d.teams) home = d.teams.find(function(t) { return t.teamId === homeId })
    if (!away && d.teams) away = d.teams.find(function(t) { return t.teamId === awayId })
  }
  if (!home) home = getTeamObj(homeId)
  if (!away) away = getTeamObj(awayId)
  if (!home || !away || !home.players || !away.players) return { homeScore: 0, awayScore: 0 }
  let res = runMatchEngine(home, away, {
    effectiveSkillFn: calcularMediaEnPosicion,
    scoringWeightFn: getGoalWeight,
    gamePlans: GAME_PLANS,
    comp: comp
  })
  if (!res) {
    var hR = getTop11Average(home.players || []) || (getBaseDato(homeId) || {}).rating || 70
    var aR = getTop11Average(away.players || []) || (getBaseDato(awayId) || {}).rating || 70
    res = simularPorRatingBasico(hR, aR)
  }
  const homeScore = res.homeScore
  const awayScore = res.awayScore
  if (home && home.players) {
    home.players.forEach(function(p) { p._preGoals = p.goals || 0; p._preAssists = p.assists || 0; p._preYC = p.yellowCards || 0; p._preRC = p.redCards || 0 })
  }
  if (away && away.players) {
    away.players.forEach(function(p) { p._preGoals = p.goals || 0; p._preAssists = p.assists || 0; p._preYC = p.yellowCards || 0; p._preRC = p.redCards || 0 })
  }
  /* Register real goalscorers from the engine, then track matches/experience/cards */
  var resEngineGoals = !!(res.goalsHome || res.goalsAway)
  if (resEngineGoals) aplicarGolesCPU(res, home, away)
  if (home && home.players) {
    assignAIStats(home.players, resEngineGoals ? 0 : homeScore, null, null)
    syncTeamStatsForTeam(home.players, homeId)
  }
  if (away && away.players) {
    assignAIStats(away.players, resEngineGoals ? 0 : awayScore, null, null)
    syncTeamStatsForTeam(away.players, awayId)
  }
  /* Match ratings and fatigue */
  ;[home, away].forEach(function(team, idx) {
    if (!team || !team.players) return
    var teamScore = idx === 0 ? homeScore : awayScore
    var rivalScore = idx === 0 ? awayScore : homeScore
    var rivalName = idx === 0 ? getTeamName(awayId) : getTeamName(homeId)
    var gkPool = team.players.filter(function(p) { return (p.position === 'POR' || p.position === 'portero') && !p.injury && !p._suspended && !(p.onLoan && p.loanTo) })
    var fieldPlayers = team.players.filter(function(p) { return p.position !== 'POR' && p.position !== 'portero' && !p.injury && !p._suspended && !(p.onLoan && p.loanTo) })
    gkPool.sort(function(a, b) {
      var aEff = (a.skill || 0) * Math.min(1, (a.energy != null ? a.energy : 80) / 100)
      var bEff = (b.skill || 0) * Math.min(1, (b.energy != null ? b.energy : 80) / 100)
      return bEff - aEff
    })
    fieldPlayers.sort(function(a, b) {
      var aEff = (a.skill || 0) * Math.min(1, (a.energy != null ? a.energy : 80) / 100)
      var bEff = (b.skill || 0) * Math.min(1, (b.energy != null ? b.energy : 80) / 100)
      return bEff - aEff
    })
    var starters = gkPool.slice(0, 1).concat(fieldPlayers.slice(0, 10))
    /* Asegurar que los goleadores reales del motor queden en el matchHistory
       aunque no estén en el top-10 por skill (misma XI que usó el motor) */
    var sideScorers = (idx === 0 ? (res.goalsHome || []) : (res.goalsAway || []))
    sideScorers.forEach(function(g) {
      if (g.scorer && !starters.some(function(s) { return s.id === g.scorer.id })) starters.push(g.scorer)
    })
    starters.forEach(function(p) {
      var matchGoals = (p.goals || 0) - (p._preGoals || 0)
      var matchYC = (p.yellowCards || 0) - (p._preYC || 0)
      var matchRC = (p.redCards || 0) - (p._preRC || 0)
      var winBonus = teamScore > rivalScore ? 0.5 : teamScore === rivalScore ? 0.2 : 0
      var goalBonus = (matchGoals || 0) * 1.2
      var yellowPen = matchYC > 0 ? -0.5 : 0
      var redPen = matchRC > 0 ? -2.0 : 0
      var cleanBonus = (matchYC === 0 && matchRC === 0) ? 0.2 : 0
      var csBonus = 0
      if (rivalScore === 0 && (p.position === 'POR' || p.position === 'defensa_central' || p.position === 'lateral_der' || p.position === 'lateral_izq')) csBonus = 0.5
      var randomFactor = (Math.random() - 0.5) * 0.6
      var rating = Math.min(10, Math.max(1, 6.2 + winBonus + goalBonus + yellowPen + redPen + cleanBonus + csBonus + randomFactor))
      if (!p.matchHistory) p.matchHistory = []
      var matchAssistsSimp = (p.assists || 0) - (p._preAssists || 0)
      p.matchHistory.push({ matchday: state.currentMatchday, rival: rivalName, minutes: 90, rating: rating, goals: matchGoals, assists: matchAssistsSimp, yellow: matchYC > 0, red: matchRC > 0, comp: comp })
      if (p.matchHistory.length > 30) p.matchHistory = p.matchHistory.slice(-30)
    })
  })
  /* Fatiga + recuperación para equipos CPU */
  aplicarFatigaEquipo(home, home.gamePlan)
  aplicarFatigaEquipo(away, away.gamePlan)
  if (home && home.players) home.players.forEach(function(p) { delete p._preGoals; delete p._preAssists; delete p._preYC; delete p._preRC })
  if (away && away.players) away.players.forEach(function(p) { delete p._preGoals; delete p._preAssists; delete p._preYC; delete p._preRC })
  /* Cup tiebreak: if drawn, apply extra time / penalties */
  var finalHome = homeScore, finalAway = awayScore
  if (comp && comp !== 'league' && homeScore === awayScore) {
    var tieSys = getMatchSystem(comp, state.countryId)
    var tb = simularEmpateCopa(homeId, awayId, homeScore, awayScore, tieSys)
    finalHome = tb.homeScore; finalAway = tb.awayScore
  }
  return { homeScore: finalHome, awayScore: finalAway }
}

function computeStandings(fixtures, teamIds) {
  const s = {}
  for (const id of teamIds) {
    s[id] = { teamId: id, played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0, pts: 0 }
  }
  for (const f of fixtures) {
    if (!f.played) continue
    const h = s[f.home]
    const a = s[f.away]
    if (!h || !a) continue
    h.played++; a.played++
    h.gf += f.homeScore; h.ga += f.awayScore
    a.gf += f.awayScore; a.ga += f.homeScore
    if (f.homeScore > f.awayScore) { h.won++; a.lost++; h.pts += 3 }
    else if (f.homeScore < f.awayScore) { a.won++; h.lost++; a.pts += 3 }
    else { h.drawn++; a.drawn++; h.pts++; a.pts++ }
  }
  return Object.values(s).sort((a, b) => b.pts - a.pts || (b.gf - b.ga) - (a.gf - a.ga))
}

function simularJornadaEnTodasLasLigas(matchday) {
  if (!state.allLeagueData) return
  for (const [lid, data] of Object.entries(state.allLeagueData)) {
    if (lid === state.leagueId) continue
    if (!data || !data.fixtures) continue
    try {
      const dayFixtures = data.fixtures.filter(f => f.matchday === matchday && !f.played)
      for (const f of dayFixtures) {
        const r = simularPartidoPorRating(f.home, f.away)
        f.homeScore = r.homeScore; f.awayScore = r.awayScore; f.played = true
      }
      data.currentMatchday = matchday
    } catch (e) { console.warn('[SIM] Error simulating', lid, 'matchday', matchday, e) }
  }
  simularCpuCopa(matchday)
}

function simularCpuCopa(matchday) {
  /* === Copa del Rey === */
  if (state.cup && state.cup.roundIdx >= 0) {
    var sched = state.cup.schedule[state.cup.roundIdx]
    if (sched && sched.week === matchday) {
      var userInRound = state.cup.allFixtures.some(function(f) {
        return !f.played && (f.home === state.teamId || f.away === state.teamId) && f.week === sched.week
      })
      if (!userInRound) {
        var cpuFixtures = state.cup.allFixtures.filter(function(f) {
          return !f.played && f.week === sched.week && f.home !== state.teamId && f.away !== state.teamId
        })
        if (cpuFixtures.length > 0) {
          cpuFixtures.forEach(function(f) {
            var r = simularPartidoPorRating(f.home, f.away, 'cup')
            f.homeScore = r.homeScore; f.awayScore = r.awayScore; f.played = true
          })
          var allPlayed = state.cup.allFixtures.filter(function(f) {
            return f.week === sched.week
          }).every(function(f) { return f.played })
          if (allPlayed) avanzarRondaCopa()
        }
      }
    }
  }

  /* === Supercopa === */
  if (state.supercopa) {
    if (state.supercopa.week && state.supercopa.week === matchday && !state.supercopa.final) {
      var userInSc = state.supercopa.fixtures.some(function(f) {
        return !f.played && (f.home === state.teamId || f.away === state.teamId)
      })
      if (!userInSc) {
        var cpuSc = state.supercopa.fixtures.filter(function(f) { return !f.played })
        if (cpuSc.length > 0) {
          cpuSc.forEach(function(f) {
            var r = simularPartidoPorRating(f.home, f.away, 'supercopa')
            f.homeScore = r.homeScore; f.awayScore = r.awayScore; f.played = true
          })
          avanzarSupercopa()
        }
      }
    }
    if (state.supercopa.final && !state.supercopa.final.played && state.supercopa.final.week === matchday) {
      var f = state.supercopa.final
      if (f.home !== state.teamId && f.away !== state.teamId) {
        var r = simularPartidoPorRating(f.home, f.away, 'supercopa')
        f.homeScore = r.homeScore; f.awayScore = r.awayScore; f.played = true
        state.supercopa.winner = r.homeScore > r.awayScore ? f.home : f.away
      }
    }
  }

  /* === Taca da Liga === */
  if (state.tacaDaLiga && state.tacaDaLiga.roundIdx >= 0) {
    var sched = state.tacaDaLiga.schedule[state.tacaDaLiga.roundIdx]
    if (sched && sched.week === matchday) {
      var userInTaca = state.tacaDaLiga.allFixtures.some(function(f) {
        return !f.played && (f.home === state.teamId || f.away === state.teamId) && f.week === sched.week
      })
      if (!userInTaca) {
        var cpuTaca = state.tacaDaLiga.allFixtures.filter(function(f) {
          return !f.played && f.week === sched.week && f.home !== state.teamId && f.away !== state.teamId
        })
        if (cpuTaca.length > 0) {
          cpuTaca.forEach(function(f) {
            var r = simularPartidoPorRating(f.home, f.away, 'taca_da_liga')
            f.homeScore = r.homeScore; f.awayScore = r.awayScore; f.played = true
          })
          var allPlayed = state.tacaDaLiga.allFixtures.filter(function(f) {
            return f.week === sched.week
          }).every(function(f) { return f.played })
          if (allPlayed) avanzarRondaTacaDaLiga()
        }
      }
    }
  }
  /* === EFL Cup === */
  if (state.eflCup && state.eflCup.roundIdx >= 0) {
    var eflSched = state.eflCup.schedule[state.eflCup.roundIdx]
    if (eflSched && eflSched.week === matchday) {
      var userInEfl = state.eflCup.allFixtures.some(function(f) {
        return !f.played && (f.home === state.teamId || f.away === state.teamId) && f.week === eflSched.week
      })
      if (!userInEfl) {
        var cpuEfl = state.eflCup.allFixtures.filter(function(f) {
          return !f.played && f.week === eflSched.week && f.home !== state.teamId && f.away !== state.teamId
        })
        if (cpuEfl.length > 0) {
          cpuEfl.forEach(function(f) {
            var r = simularPartidoPorRating(f.home, f.away, 'efl_cup')
            f.homeScore = r.homeScore; f.awayScore = r.awayScore; f.played = true
          })
          var allEflPlayed = state.eflCup.allFixtures.filter(function(f) {
            return f.week === eflSched.week
          }).every(function(f) { return f.played })
          if (allEflPlayed) avanzarRondaEflCup()
        }
      }
    }
  }
}

function initAllLeagueData() {
  if (!state.allLeagueData) state.allLeagueData = {}
  for (const cid in window.DB) {
    const data = window.DB[cid]
    if (!data) continue
    for (const l of data.country.leagues || []) {
      if (!state.allLeagueData[l.id]) {
        const teamIds = l.teams.map(t => t.id)
        if (teamIds.length < 2) continue
        try {
          state.allLeagueData[l.id] = buildLeagueData(l)
        } catch (e) { console.warn('[INIT] Error generating data for', l.id, e) }
        continue
      }
      /* La liga ya existe: si algún equipo tiene plantilla real pero sus
         jugadores actuales son CPU (sin imágenes reales), los regeneramos. */
      try {
        var teams = state.allLeagueData[l.id].teams || []
        var rebuilt = false
        teams.forEach(function(t, ti) {
          if (!getRealSquad(t.teamId)) return
          var isCpu = t.players.length > 0 && t.players.every(function(p) { return /cpu/.test(String(p.id || '')) })
          if (isCpu) {
            state.allLeagueData[l.id].teams[ti] = buildTeamEntry(l, t.teamId, t.name, t.formation, t.gamePlan, t.logo, t.palmares)
            rebuilt = true
          }
        })
        if (rebuilt) console.log('[INIT] Regenerados jugadores reales en', l.id)
      } catch (e) { console.warn('[INIT] rebuild error', l.id, e) }
    }
  }
}

function buildTeamEntry(l, teamId, name, formation, gamePlan, logo, palmares) {
  var squad = getRealSquad(teamId)
  var _cid = l.country ? l.country.id : 'es'
  var players
  if (squad) {
    players = squad.map(function(p) { return { ...p } })
  } else {
    var rating = (function() { var t = l.teams.find(function(x) { return x.id === teamId }); return t && t.rating ? t.rating : (getBaseDato(teamId) ? getBaseDato(teamId).rating : null) || 70 })()
    players = generateCpuSquad(teamId, _cid, rating)
  }
  return { teamId: teamId, name: name, players: players, formation: formation, gamePlan: gamePlan, logo: logo, palmares: palmares }
}

function buildLeagueData(l) {
  var teamIds = l.teams.map(function(t) { return t.id })
  var leagueTeams = l.teams.map(function(t) {
    return buildTeamEntry(l, t.id, t.name, t.formation, t.gamePlan, t.logo, t.palmares)
  })
  var fx = generateFixtures(teamIds)
  return { fixtures: fx, currentMatchday: 0, totalMatchdays: Math.max(...fx.map(function(f) { return f.matchday })), teams: leagueTeams }
}

/* ============ CLUB VIEW ============ */
function renderSquad(players) {
  const container = document.getElementById('club-squad-content')
  if (!container) return
  if (!state.squadView) state.squadView = 'info'
  let html = `<div class="sq-toggle">
    <button class="sq-tab${state.squadView === 'info' ? ' active' : ''}" data-sq="info">Info</button>
    <button class="sq-tab${state.squadView === 'performance' ? ' active' : ''}" data-sq="performance">Rendimiento</button>
  </div>`
  container.innerHTML = html
  if (state.squadView === 'info') renderSquadInfo(players)
  else renderPerformance(players)
  container.querySelectorAll('.sq-tab').forEach(btn => {
    btn.onclick = () => {
      state.squadView = btn.dataset.sq
      renderSquad(state.players)
    }
  })
}

