/* ============ COUNTRY / COMPETITION SELECTOR ============ */
function initLeagueViewScope() {
  if (state.leagueViewContinental === undefined) state.leagueViewContinental = false
}

function renderCountrySelectorButton() {
  var btn = document.getElementById('league-country-selector')
  if (!btn) return
  var flagEl = document.getElementById('lcs-flag')
  var nameEl = document.getElementById('lcs-name')
  if (state.leagueViewContinental) {
    flagEl.textContent = '\ud83c\udf10'
    nameEl.textContent = 'Continentales'
  } else {
    var ac = state.leagueViewCountry || state.countryId
    var c = COUNTRIES.find(function(x) { return x.id === ac })
    flagEl.textContent = c ? c.flag : '\ud83c\udf0d'
    nameEl.textContent = c ? c.name : (ac || '\u2014')
  }
}

function renderCountrySelectorList(filter) {
  var list = document.getElementById('country-selector-list')
  if (!list) return
  var q = (filter || '').toLowerCase().trim()
  var ac = state.leagueViewCountry || state.countryId
  var isContinental = !!state.leagueViewContinental
  var html = ''
  var continentalActive = isContinental
  if (!q || 'continentales'.indexOf(q) !== -1) {
    html += '<button class="cs-item cs-continental' + (continentalActive ? ' cs-active' : '') + '" data-scope="continental">' +
      '<span class="cs-flag">\ud83c\udf10</span>' +
      '<span class="cs-label">Continentales</span>' +
      '<span class="cs-check">\u2713</span></button>'
  }
  var countries = COUNTRIES.slice().sort(function(a, b) { return a.name.localeCompare(b.name, 'es') })
  countries.forEach(function(c) {
    if (q && c.name.toLowerCase().indexOf(q) === -1) return
    var active = !isContinental && c.id === ac
    html += '<button class="cs-item' + (active ? ' cs-active' : '') + '" data-scope="pais" data-cid="' + c.id + '">' +
      '<span class="cs-flag">' + c.flag + '</span>' +
      '<span class="cs-label">' + c.name + '</span>' +
      '<span class="cs-check">\u2713</span></button>'
  })
  list.innerHTML = html
  list.querySelectorAll('.cs-item').forEach(function(el) {
    el.onclick = function() { selectLeagueViewScope(el) }
  })
}

function showCountrySelectorModal() {
  var modal = document.getElementById('country-selector-modal')
  if (!modal) return
  renderCountrySelectorList('')
  modal.classList.remove('hidden')
  requestAnimationFrame(function() { modal.classList.add('open') })
  setTimeout(function() { document.getElementById('country-selector-search').focus() }, 150)
}

function closeCountrySelectorModal() {
  var modal = document.getElementById('country-selector-modal')
  if (!modal) return
  modal.classList.remove('open')
  setTimeout(function() { modal.classList.add('hidden') }, 250)
}

function selectLeagueViewScope(el) {
  var scope = el.getAttribute('data-scope')
  var cid = el.getAttribute('data-cid')
  if (scope === 'continental') {
    state.leagueViewContinental = true
    state.leagueViewCountry = state.leagueViewCountry || state.countryId
  } else {
    state.leagueViewContinental = false
    state.leagueViewCountry = cid
    if (!window.DB[cid]) {
      loadCountryData(cid, function() {
        ensureCountryLeagues(cid)
        state.leagueViewCountry = cid
        closeCountrySelectorModal()
        renderLeague()
      })
      return
    }
    ensureCountryLeagues(cid)
  }
  closeCountrySelectorModal()
  renderLeague()
}

document.addEventListener('DOMContentLoaded', function() {
  var selBtn = document.getElementById('league-country-selector')
  if (selBtn) selBtn.onclick = function() { showCountrySelectorModal() }
  var csClose = document.getElementById('country-selector-close')
  if (csClose) csClose.onclick = function() { closeCountrySelectorModal() }
  var csSearch = document.getElementById('country-selector-search')
  if (csSearch) csSearch.oninput = function() { renderCountrySelectorList(this.value) }
})

/* ============ MATCH ============ */
const matchData = { homeScore: 0, awayScore: 0, homeFouls: 0, awayFouls: 0, rivalName: '' }





/* ============ TACTICS MODAL ============ */
function abrirTacticasModal() {
  console.log('[TACTICS] modal opening')

  const modal = document.getElementById('tactics-modal')
  const formContainer = document.getElementById('tm-formation')
  const gpSelect = document.getElementById('tm-gameplan')
  const gpDesc = document.getElementById('tm-gameplan-desc')
  const pitch = document.getElementById('tm-pitch')
  const bench = document.getElementById('tm-bench')
  const reserves = document.getElementById('tm-reserves')
  const tactic = state.tactic

  /* Formation buttons */
  formContainer.innerHTML = Object.keys(FORMATIONS).map(k =>
    `<button class="tactics-btn ${tactic.formation === k ? 'active' : ''}" data-formation="${k}">${k}</button>`
  ).join('')
  formContainer.querySelectorAll('.tactics-btn').forEach(btn => {
    btn.onclick = () => {
      tactic.formation = btn.dataset.formation
      reorderSquadToFormation()
      abrirTacticasModal()
    }
  })

  /* Game plan */
  gpSelect.innerHTML = Object.entries(GAME_PLANS).map(([k, v]) =>
    `<option value="${k}" ${tactic.gamePlan === k ? 'selected' : ''}>${v.label}</option>`
  ).join('')
  gpSelect.onchange = () => {
    tactic.gamePlan = gpSelect.value
    gpDesc.textContent = (GAME_PLANS[tactic.gamePlan] || {}).desc || ''
  }
  gpDesc.textContent = (GAME_PLANS[tactic.gamePlan] || {}).desc || ''

  /* Pitch grid — same as Club renderTactics() */
  const roles = SLOT_ROLES[tactic.formation] || SLOT_ROLES['4-3-3']
  if (!state.tacticsSlots || state.tacticsSlots.length !== roles.length) {
    state.tacticsSlots = roles.map(() => null)
  }

  const swapId = window._tacticsSwap || null

  let html = `<div class="pitch-grid-11" id="pitch-grid-modal">`

  for (let i = 0; i < roles.length; i++) {
    const role = roles[i]
    const pid = state.tacticsSlots[i] || null
    const player = pid ? state.players.find(p => p.id === pid) : null
    const pos = POSITIONS[role]
    const isSelected = pid && pid === swapId

    if (player) {
      const isRed = player._redThisMatch
      html += `<div class="p11-slot-wrap">` + buildPlayerNode(player, role, { mode: 'tactics', captainId: state.captainId, cls: 'pp-slot' + (isSelected ? ' selected' : '') + (isRed ? ' pp-sentoff' : ''), roleColor: role, dataAttr: `data-slot="${i}"`, labelOverride: isRed ? '\ud83d\udfe5' : (POS_ABBR[role] || role) }) + `</div>`
    } else {
      html += `<div class="p11-slot-wrap"><div class="pitch-player-node pp-tactics pp-slot pp-empty${swapId ? ' swap-target' : ''}" data-slot="${i}"><span class="pp-empty-plus">+</span><span class="pp-empty-role">${pos.label}</span></div></div>`
    }
  }
  html += '</div>'
  pitch.innerHTML = html

  /* Click on filled slot → select/swap */
  pitch.querySelectorAll(".pp-slot[data-slot]:not(.pp-empty)").forEach(el => {
    el.onclick = () => {
      const slotIdx = parseInt(el.dataset.slot)
      const pid = state.tacticsSlots[slotIdx]
      const player = pid ? state.players.find(p => p.id === pid) : null
      if (!player) return
      if (player._redThisMatch) {
        /* Expelled slot: clear it or swap */
        if (swapId) {
          const swapPlayer = state.players.find(p => p.id === swapId)
          if (!swapPlayer) return
          const swapSlot = state.tacticsSlots.indexOf(swapId)
          if (swapSlot >= 0) {
            /* Swap expelled ↔ selected pitch player */
            state.tacticsSlots[swapSlot] = pid
            state.tacticsSlots[slotIdx] = swapId
            swapPlayer.enPista = true
          } else {
            /* Selected is from bench → put in expelled slot */
            state.tacticsSlots[slotIdx] = swapId
            swapPlayer.enPista = true
          }
          window._tacticsSwap = null
        } else {
          /* No swap active → just clear expelled slot so you can fill it */
          state.tacticsSlots[slotIdx] = null
        }
        renderPlayerRatings()
        abrirTacticasModal()
        return
      }
      if (swapId) {
        /* Swap with selected player */
        const swapPlayer = state.players.find(p => p.id === swapId)
        const swapSlot = state.tacticsSlots.indexOf(swapId)
        if (swapSlot >= 0) {
          state.tacticsSlots[swapSlot] = pid
          state.tacticsSlots[slotIdx] = swapId
        } else {
          /* swapId is from bench → put on pitch, current to bench */
          const oldSlot = state.tacticsSlots.indexOf(pid)
          state.tacticsSlots[oldSlot] = swapId
          player.enPista = false
          swapPlayer.enPista = true
        }
        window._tacticsSwap = null
      } else {
        /* Select this player */
        window._tacticsSwap = pid
      }
      renderPlayerRatings()
      abrirTacticasModal()
    }
  })

  /* Click on empty slot → assign player or clear selection */
  pitch.querySelectorAll(".pp-empty[data-slot]").forEach(el => {
    el.onclick = () => {
      const slotIdx = parseInt(el.dataset.slot)
      if (swapId) {
        /* Put selected player in this empty slot */
        const swapPlayer = state.players.find(p => p.id === swapId)
        const swapSlot = state.tacticsSlots.indexOf(swapId)
        if (swapSlot >= 0) {
          state.tacticsSlots[swapSlot] = null
          const oldPlayer = state.players.find(p => p.id === state.tacticsSlots[swapSlot])
        }
        state.tacticsSlots[slotIdx] = swapId
        swapPlayer.enPista = true
        window._tacticsSwap = null
      } else {
        /* Assign best available bench player */
        const role = roles[slotIdx]
        const candidates = state.players.filter(p => !p.enPista && !p.injury && !p._redThisMatch && !state.tacticsSlots.includes(p.id))
        const best = candidates.sort((a, b) => {
          const mA = getPositionMultiplier(a.position, role)
          const mB = getPositionMultiplier(b.position, role)
          return mB !== mA ? mB - mA : b.skill - a.skill
        })[0]
        if (best) {
          state.tacticsSlots[slotIdx] = best.id
          best.enPista = true
        }
      }
      renderPlayerRatings()
      abrirTacticasModal()
    }
  })

  /* Filter available players */
  const available = state.players.filter(p => !p.enPista && !p.injury && !p._redThisMatch && !state.tacticsSlots.includes(p.id) && !(p.onLoan && p.loanTo))

  /* Hide reserves section */
  document.getElementById('tm-reserves-label').style.display = 'none'
  document.getElementById('tm-reserves').style.display = 'none'

  /* Bench (dynamic limit) */
  const maxBench = getEffectiveMaxBench()
  const benchPlayers = available.slice(0, maxBench)
  document.getElementById('tm-bench-label').textContent = 'BANQUILLO (' + benchPlayers.length + ')'

  if (benchPlayers.length === 0) {
    bench.innerHTML = '<div style="text-align:center;padding:12px;color:var(--text-muted);width:100%">Sin suplentes</div>'
  } else {
    bench.innerHTML = benchPlayers.map(p => {
      const isSelected = p.id === swapId
      const bKey = SIGLA_TO_POS[p.position] || p.position
      return `<div class="bench-slot-wrap">` + buildPlayerNode(p, p.position, { mode: 'tactics', captainId: state.captainId, cls: 'pp-slot' + (isSelected ? ' selected' : ''), dataAttr: `data-pid="${p.id}"`, labelOverride: POS_ABBR[bKey] }) + `</div>`
    }).join('')
    bench.querySelectorAll('.pp-slot[data-pid]').forEach(el => {
      el.onclick = () => handleBenchClick(el.dataset.pid, roles)
    })
  }



  function handleBenchClick(pid, slotRoles) {
    if (swapId) {
      /* Swap: bench player ↔ selected player on pitch or on bench */
      const swapPlayer = state.players.find(p => p.id === swapId)
      const clickPlayer = state.players.find(p => p.id === pid)
      if (!swapPlayer || !clickPlayer) return
      const swapSlot = state.tacticsSlots.indexOf(swapId)
      if (swapSlot >= 0) {
        /* Swap is on pitch → swap pitch slot with bench player */
        state.tacticsSlots[swapSlot] = clickPlayer.id
        clickPlayer.enPista = true
        swapPlayer.enPista = false
      } else {
        /* Both are bench/reserve → just swap selection */
        window._tacticsSwap = pid
        renderPlayerRatings()
        abrirTacticasModal()
        return
      }
      window._tacticsSwap = null
    } else {
      /* No swap active → assign to best empty slot */
      const player = state.players.find(p => p.id === pid)
      if (!player) return
      const emptySlots = state.tacticsSlots.map((s, i) => s === null ? i : -1).filter(i => i >= 0)
      const expelledSlotIdx = state.tacticsSlots.findIndex((s, i) => {
        if (!s) return false
        const p = state.players.find(x => x.id === s)
        return p && p._redThisMatch
      })
      if (emptySlots.length > 0) {
        const bestSlot = emptySlots.sort((a, b) => {
          const mA = getPositionMultiplier(player.position, slotRoles[a])
          const mB = getPositionMultiplier(player.position, slotRoles[b])
          return mB !== mA ? mB - mA : 0
        })[0]
        state.tacticsSlots[bestSlot] = player.id
        player.enPista = true
      } else if (expelledSlotIdx >= 0) {
        /* Put player directly into expelled player's slot */
        state.tacticsSlots[expelledSlotIdx] = player.id
        player.enPista = true
      } else {
        /* No empty slots → select this player to swap */
        window._tacticsSwap = pid
      }
    }
    renderPlayerRatings()
    abrirTacticasModal()
  }

  /* Apply button */
  document.getElementById('tm-apply').onclick = () => {
    addFeedEvent({ text: `Cambio táctico`, type: 'sub' })
    window._tacticsSwap = null
    modal.classList.remove('open')
  }

  /* Close button */
  document.getElementById('tm-close').onclick = () => {
    window._tacticsSwap = null
    modal.classList.remove('open')
  }

  modal.classList.add('open')
}

function finishMatch(isHome, fixture, rival) {
  var userScore = fixture.homeScore
  var rivalScore = fixture.awayScore
  if (userScore == null) userScore = 0
  if (rivalScore == null) rivalScore = 0
  if (!isHome) { var tmp = userScore; userScore = rivalScore; rivalScore = tmp }
  fixture.played = true

  /* Playoff match handling */
  const isPlayoff = state.playoffs && state.playoffs.fixtures && state.playoffs.fixtures.some(f => f === fixture)
  if (isPlayoff) {
    /* Auto-simulate other playoff fixtures in this round */
    for (const f of state.playoffs.fixtures) {
      if (f === fixture || f.played) continue
      const result = autoSimulateOtherMatch(f.home, f.away)
      f.homeScore = result.homeScore
      f.awayScore = result.awayScore
      f.played = true
    }
    /* Update rewards */
    if (userScore > rivalScore) { reward = 1500; state.stats.wins++ }
    else if (userScore === rivalScore) { reward = 500; state.stats.draws++ }
    else { reward = 0; state.stats.losses++ }
    state.finances.balance += reward
    state.finances.history.push({ reason: `${state.playoffs.round === 'F' ? 'Final' : state.playoffs.round === 'SF' ? 'Semifinal' : 'Cuartos'} playoff vs ${rival.name}`, amount: reward })
    avanzarRondaPlayoff()
    updateLeagueStandings()
    const sh = document.getElementById('score-home'); const sa = document.getElementById('score-away')
    if (sh) sh.textContent = '0'; if (sa) sa.textContent = '0'
    showMatchdayResults(userScore, rivalScore, rival.name)
    autoSave()
    return
  }

  /* Result stats */
  if (userScore > rivalScore) { state.stats.wins++ }
  else if (userScore === rivalScore) { state.stats.draws++ }
  else { state.stats.losses++ }

  /* Ingresos del partido: solo taquilla en casa (según asistencia y precio) */
  var matchIncome = 0
  if (isHome && state.presupuestoInicial > 0) {
    var taquillaLocal = getTaquillaEstadio()
    state.finances.balance += taquillaLocal
    state.finances.history.push({ reason: 'Ingresos por d\u00eda de partido (local)', amount: taquillaLocal })
    matchIncome = taquillaLocal
  }

  /* Inbox notification */
  const resultLabel = userScore > rivalScore ? 'Victoria' : userScore === rivalScore ? 'Empate' : 'Derrota'
  addNotification('match', `${resultLabel} ${userScore}-${rivalScore} vs ${rival.name}`, `Jornada ${state.currentMatchday} · +${matchIncome} €`)

  /* Reset de boletos y minutos tras el partido */
  state.players.forEach(p => {
    p.enPista = false
    p.minutosEnPista = 0
    p.convocado = false
    p.titular = false
  })
  state.convocatoriaValidada = false

  /* Match history per player */
  state.players.filter(p => p.minutosEnPista > 0).forEach(p => {
    if (!p.matchHistory) p.matchHistory = []
    var baseRating = 6.0
    var winBonus = (us > them) ? 0.8 : (us === them) ? 0.2 : -0.3
    var yellowPenalty = p._yellowThisMatch ? -0.5 : 0
    var redPenalty = p._redThisMatch ? -2 : 0
    var goalBonus = (p._goalsInMatch || 0) * 0.8
    var assistBonus = (p._assistThisMatch || 0) * 0.4
    var randomFactor = (Math.random() - 0.5) * 1.0
    var csBonus = 0
    if (them === 0 && (p.position === 'POR' || p.position === 'defensa_central' || p.position === 'lateral_der' || p.position === 'lateral_izq')) csBonus = 0.5
    var rating = Math.min(10, Math.max(1, baseRating + winBonus + yellowPenalty + redPenalty + goalBonus + assistBonus + randomFactor + csBonus))
    p.matchHistory.push({
      matchday: state.currentMatchday,
      rival: rival.name,
      minutes: p.minutosEnPista || 0,
      rating: Math.min(10, Math.max(1, rating)),
      goals: p._goalsInMatch || 0,
      assists: p._assistThisMatch || 0,
      yellow: !!p._yellowThisMatch,
      red: !!p._redThisMatch,
      comp: 'league',
    })
    p.matches = (p.matches || 0) + 1
    p.goals = (p.goals || 0) + (p._goalsInMatch || 0)
    /* Track stats per team */
    if (!p.teamStats) p.teamStats = {}
    var curTeamId = state.teamId
    if (!p.teamStats[curTeamId]) p.teamStats[curTeamId] = { matches: 0, goals: 0, assists: 0, yellowCards: 0, redCards: 0 }
    p.teamStats[curTeamId].matches++
    p.teamStats[curTeamId].goals += (p._goalsInMatch || 0)
    if (p._assistThisMatch) p.teamStats[curTeamId].assists++
    if (p._yellowThisMatch) p.teamStats[curTeamId].yellowCards++
    if (p._redThisMatch) p.teamStats[curTeamId].redCards++
    delete p._yellowsInThisMatch; delete p._redThisMatch; delete p._goalsInMatch; delete p._assistThisMatch
  })

  /* Auto-simulate other matches */
  const otherFixtures = state.fixtures.filter(f => f.matchday === state.currentMatchday && f.played === false)
  for (const f of otherFixtures) {
    const result = autoSimulateOtherMatch(f.home, f.away)
    f.homeScore = result.homeScore
    f.awayScore = result.awayScore
    f.played = true
  }

  /* Simulate all other leagues for this matchday */
  simularJornadaEnTodasLasLigas(state.currentMatchday)

  updateLeagueStandings()
  const sh = document.getElementById('score-home'); const sa = document.getElementById('score-away')
  if (sh) sh.textContent = '0'; if (sa) sa.textContent = '0'
  showMatchdayResults(userScore, rivalScore, rival.name)
  autoSave()
}

function resetSeason() {
  procesarRetornoCesiones()
  state.currentMatchday = 1
  state.stats = { wins: 0, draws: 0, losses: 0, goalsFor: 0, goalsAgainst: 0 }

  /* Reset league standings */
  state.fixtures.forEach(f => { f.played = false; f.homeScore = null; f.awayScore = null })

  /* Austria: al reiniciar la temporada, reconstruimos la fase regular y
     descartamos cualquier fixture de la fase 2 (grupos) ya generado. */
  if (isAustriaBundesliga(state.leagueId)) {
    state.fixtures = state.fixtures.filter(function(f) { return !f.grupo })
    state.totalMatchdays = austriaBundesligaConfig.regularSeason.matchdays
    state.fase2Built = false
    state.leaguePhase = 'regular'
    state.halvingApplied = false
    state.halvingAppliedLeague = null
    state.playoffs = null
    state.conferencePlayoffWinner = null
    state.austriaPhaseData = null
  }

  /* Reset players */
  state.players.forEach(p => { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0; p._suspended = null; p._redType = null; p.yellowCards = 0; p.redCards = 0 })

  /* Reset CPU teams */
  state.leagueTeams.forEach(t => {
    t.players.forEach(p => { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0 })
  })

  normalizarPlantillas()
  rebuildGlobalPlayerPool()

  /* Process forced filial relegation (parent relegated to same division as B team) */
  if (state._filialRelegue) {
    var frId = state._filialRelegue
    var frTeam = state.leagueTeams.find(function(t) { return t.teamId === frId })
    if (frTeam) {
      var frIdx = state.leagueTeams.indexOf(frTeam)
      if (frIdx >= 0) state.leagueTeams.splice(frIdx, 1)
      addNotification('general', '\u2B07 Filial relegado: ' + frTeam.name, 'Relegado autom\u00e1ticamente al descender el primer equipo')
    }
    state._filialRelegue = null
  }

  /* Reset tactics */
  state.tacticsSlots = []
  state.benchIds = []
  state.reserveIds = []
  state.convocatoriaValidada = false
  state.selectedPlayerId = null

  /* Season prize based on division */
  const seasonPrize = Math.round(getDivisionBaseBudget(state.leagueId) * 0.1)
  state.finances.balance += seasonPrize
  state.finances.history.push({ reason: '🏆 Premio temporada', amount: seasonPrize })

  autoSaveTactics()
  actualizarIndicadorTemporada()
  saveGame()
  renderLeague()
}

/* ============ FIN DE TEMPORADA ============ */
function getLeagueFromId(leagueId) {
  for (const cid in window.DB) {
    const data = window.DB[cid]
    if (!data) continue
    const league = data.country.leagues.find(l => l.id === leagueId)
    if (league) return league
  }
  return null
}

function getLeagueRules(leagueId) {
  const rules = {
    'l1s': { directPromotion: 0, playoffSpots: 0, playoffPromotions: 0, relegation: 3, relegatesTo: 'l2s' },
    'l2s': { directPromotion: 2, playoffSpots: 4, playoffPromotions: 1, relegation: 4, promotesTo: 'l1s', relegatesTo: ['l3sg1', 'l3sg2'] },
    'l3sg1': { directPromotion: 1, playoffSpots: 4, playoffPromotions: 1, relegation: 4, promotesTo: 'l2s' },
    'l3sg2': { directPromotion: 1, playoffSpots: 4, playoffPromotions: 1, relegation: 4, promotesTo: 'l2s' },
    'l1p': { directPromotion: 0, playoffSpots: 0, playoffPromotions: 0, relegation: 2, crossPlayoff: { pos: 16, opponent: 'l2p', opponentPos: 3 }, relegatesTo: 'l2p' },
    'l2p': { directPromotion: 2, playoffSpots: 0, playoffPromotions: 0, relegation: 0, promotesTo: 'l1p' },
    'l1fr': { directPromotion: 0, playoffSpots: 0, playoffPromotions: 0, relegation: 2, crossPlayoff: { pos: 16, opponent: 'l2fr', opponentPos: 3 }, relegatesTo: 'l2fr' },
    'l2fr': { directPromotion: 2, playoffSpots: 0, playoffPromotions: 0, relegation: 0, promotesTo: 'l1fr' },
    'sa': { directPromotion: 0, playoffSpots: 0, playoffPromotions: 0, relegation: 3, relegatesTo: 'sb' },
    'sb': { directPromotion: 2, playoffSpots: 6, playoffPromotions: 1, relegation: 5, relegationPlayoff: [16, 17], promotesTo: 'sa' },
    'bl2': { directPromotion: 2, playoffSpots: 1, playoffPromotions: 1, relegation: 2, relegationPlayoff: [16], relegatesTo: 'bl3', promotesTo: 'bl' },
    'bl': { directPromotion: 0, playoffSpots: 0, playoffPromotions: 0, relegation: 2, relegationPlayoff: [16], relegatesTo: 'bl2' },
    'lpl': { directPromotion: 0, playoffSpots: 0, playoffPromotions: 0, relegation: 3, relegatesTo: 'lpl2' },
    'lpl2': { directPromotion: 2, playoffSpots: 4, playoffPromotions: 1, relegation: 3, promotesTo: 'lpl', relegatesTo: 'lpl3' },
    'lpl3': { directPromotion: 2, playoffSpots: 4, playoffPromotions: 1, relegation: 6, relegationPlayoff: [15, 16], promotesTo: 'lpl2', relegatesTo: ['lpl4g1','lpl4g2','lpl4g3','lpl4g4'] },
    'lpl4g1': { directPromotion: 1, runnerUpPlayoff: true, promotesTo: 'lpl3' },
    'lpl4g2': { directPromotion: 1, runnerUpPlayoff: true, promotesTo: 'lpl3' },
    'lpl4g3': { directPromotion: 1, runnerUpPlayoff: true, promotesTo: 'lpl3' },
    'lpl4g4': { directPromotion: 1, runnerUpPlayoff: true, promotesTo: 'lpl3' },
  }
  return rules[leagueId] || null
}

function computeSeasonMovements(countryId) {
  const countryData = window.DB[countryId]
  if (!countryData) return null
  const leagues = countryData.country.leagues
  if (!leagues || leagues.length === 0) return null

  /* Fast-forward remaining matchdays for all leagues in this country */
  for (const league of leagues) {
    const data = state.allLeagueData[league.id]
    if (!data || !data.fixtures) continue
    if (data.currentMatchday >= data.totalMatchdays) continue
    for (let md = data.currentMatchday + 1; md <= data.totalMatchdays; md++) {
      const dayFixtures = data.fixtures.filter(function(f) { return f.matchday === md && !f.played })
      for (const f of dayFixtures) {
        try {
          const r = simularPartidoPorRating(f.home, f.away)
          f.homeScore = r.homeScore; f.awayScore = r.awayScore; f.played = true
        } catch (e) { console.warn('[MOVEMENTS] Error simulating', league.id, 'md', md, e) }
      }
    }
    data.currentMatchday = data.totalMatchdays
  }

  const allStandings = {}
  const divisions = []
  for (const league of leagues) {
    const data = state.allLeagueData[league.id]
    if (!data || !data.fixtures) continue
    const teamIds = league.teams.map(function(t) { return t.id })
    const standings = computeStandings(data.fixtures, teamIds)
    if (!standings || standings.length === 0) continue
    allStandings[league.id] = standings
    const rules = getLeagueRules(league.id)
    if (!rules) continue

    const div = { id: league.id, name: league.name, promoted: [], relegated: [], playoff: [] }

    /* Direct promotion */
    for (let i = 0; i < rules.directPromotion; i++) {
      if (standings[i]) div.promoted.push({ teamId: standings[i].teamId, name: getTeamName(standings[i].teamId), via: 'direct' })
    }

    /* Playoff spots */
    const pStart = rules.directPromotion
    const pEnd = pStart + rules.playoffSpots
    for (let i = pStart; i < pEnd; i++) {
      if (standings[i]) div.playoff.push({ teamId: standings[i].teamId, name: getTeamName(standings[i].teamId), pos: i + 1 })
    }

    /* Determine playoff winner (higher seed) */
    if (rules.playoffPromotions > 0 && div.playoff.length >= 2) {
      const winner = standings[pStart]
      if (winner) div.promoted.push({ teamId: winner.teamId, name: getTeamName(winner.teamId), via: 'playoff' })
    }

    /* Relegation (with optional relegationPlayoff for non-contiguous positions) */
    const total = standings.length
    if (rules.relegationPlayoff && rules.relegationPlayoff.length > 0) {
      for (let i = total - rules.relegation; i < total; i++) {
        if (standings[i]) {
          var pos = i + 1
          if (rules.relegationPlayoff.indexOf(pos) >= 0) {
            if (!div.relegationPlayoff) div.relegationPlayoff = []
            div.relegationPlayoff.push({ teamId: standings[i].teamId, name: getTeamName(standings[i].teamId), pos: pos })
          } else {
            div.relegated.push({ teamId: standings[i].teamId, name: getTeamName(standings[i].teamId) })
          }
        }
      }
    } else {
      for (let i = total - rules.relegation; i < total; i++) {
        if (standings[i]) div.relegated.push({ teamId: standings[i].teamId, name: getTeamName(standings[i].teamId) })
      }
    }

    divisions.push(div)
  }

  /* Cross-playoff handling (Portugal: 16º l1p vs 3º l2p — single match) */
  const processedCross = new Set()
  for (const div of divisions) {
    const rules = getLeagueRules(div.id)
    if (!rules || !rules.crossPlayoff) continue
    const pairKey = [div.id, rules.crossPlayoff.opponent].sort().join('_')
    if (processedCross.has(pairKey)) continue
    processedCross.add(pairKey)

    const oppDiv = divisions.find(function(d) { return d.id === rules.crossPlayoff.opponent })
    if (!oppDiv) continue

    const standing = allStandings[div.id]
    const oppStanding = allStandings[rules.crossPlayoff.opponent]
    if (!standing || !oppStanding) continue

    const teamId = standing[rules.crossPlayoff.pos - 1] ? standing[rules.crossPlayoff.pos - 1].teamId : null
    const oppTeamId = oppStanding[rules.crossPlayoff.opponentPos - 1] ? oppStanding[rules.crossPlayoff.opponentPos - 1].teamId : null
    if (!teamId || !oppTeamId) continue

    const r = simularPartidoPorRating(teamId, oppTeamId)
    const tWon = r.homeScore > r.awayScore

    div.crossPlayoff = {
      teamId: teamId, opponentId: oppTeamId, opponentName: getTeamName(oppTeamId), opponentLeagueName: oppDiv.name,
      scoreTeam: r.homeScore, scoreOpponent: r.awayScore,
      verdict: tWon ? 'saved' : 'relegated'
    }
    oppDiv.crossPlayoff = {
      teamId: oppTeamId, opponentId: teamId, opponentName: getTeamName(teamId), opponentLeagueName: div.name,
      scoreTeam: r.awayScore, scoreOpponent: r.homeScore,
      verdict: tWon ? 'not_promoted' : 'promoted'
    }
  }

  /* === POLAND: 4ª Runners-Up Intergroup Playoff + Cross Finals vs 3ª === */
  const lpl3Div = divisions.find(function(d) { return d.id === 'lpl3' })
  const lpl4gDivs = divisions.filter(function(d) { return d.id && d.id.indexOf('lpl4g') === 0 })
  if (lpl3Div && lpl3Div.relegationPlayoff && lpl3Div.relegationPlayoff.length === 2 && lpl4gDivs.length === 4) {
    /* Collect runners-up (2nd place) from each 4ª group */
    const runnersUp = []
    for (const gDiv of lpl4gDivs) {
      const gStanding = allStandings[gDiv.id]
      if (!gStanding || gStanding.length < 2) continue
      const ruTeamId = gStanding[1].teamId
      runnersUp.push({ divId: gDiv.id, teamId: ruTeamId, teamName: getTeamName(ruTeamId), rating: getTeamRating(ruTeamId) })
    }
    if (runnersUp.length === 4) {
      /* Sort by rating descending */
      runnersUp.sort(function(a, b) { return b.rating - a.rating })
      /* Semi 1: best vs worst (indices 0 vs 3) */
      const s1 = simularPartidoPorRating(runnersUp[0].teamId, runnersUp[3].teamId)
      /* Semi 2: 2nd best vs 3rd best (indices 1 vs 2) */
      const s2 = simularPartidoPorRating(runnersUp[1].teamId, runnersUp[2].teamId)
      /* Store intergroup result in each 4ª div and track winners */
      const intergroupMatches = [
        { home: runnersUp[0], away: runnersUp[3], result: s1 },
        { home: runnersUp[1], away: runnersUp[2], result: s2 }
      ]
      const ganadores = []
      for (const match of intergroupMatches) {
        const { home, away, result } = match
        const hWon = result.homeScore > result.awayScore
        const homeDiv = divisions.find(function(d) { return d.id === home.divId })
        const awayDiv = divisions.find(function(d) { return d.id === away.divId })
        if (homeDiv) {
          homeDiv.promotionPlayoff = {
            teamId: home.teamId, teamName: home.teamName,
            intergroup: { opponentId: away.teamId, opponentName: away.teamName, opponentLeague: awayDiv ? awayDiv.name : '', teamScore: result.homeScore, opponentScore: result.awayScore, won: hWon }
          }
        }
        if (awayDiv) {
          awayDiv.promotionPlayoff = {
            teamId: away.teamId, teamName: away.teamName,
            intergroup: { opponentId: home.teamId, opponentName: home.teamName, opponentLeague: homeDiv ? homeDiv.name : '', teamScore: result.awayScore, opponentScore: result.homeScore, won: !hWon }
          }
        }
        ganadores.push(hWon ? home : away)
      }
      /* Cross finals: 15º vs Ganador A, 16º vs Ganador B */
      const rp15 = lpl3Div.relegationPlayoff[0]
      const rp16 = lpl3Div.relegationPlayoff[1]
      if (rp15 && ganadores[0]) {
        const cf1 = simularPartidoPorRating(rp15.teamId, ganadores[0].teamId)
        rp15.opponentId = ganadores[0].teamId
        rp15.opponentName = ganadores[0].teamName
        rp15.opponentLeague = (divisions.find(function(d) { return d.id === ganadores[0].divId }) || {}).name || 'Cuarta Polonia'
        rp15.teamScore = cf1.homeScore
        rp15.opponentScore = cf1.awayScore
        rp15.verdict = cf1.homeScore > cf1.awayScore ? 'saved' : 'relegated'
        const gaDiv = divisions.find(function(d) { return d.id === ganadores[0].divId })
        if (gaDiv && gaDiv.promotionPlayoff) {
          gaDiv.promotionPlayoff.crossFinal = {
            opponentId: rp15.teamId, opponentName: rp15.name, opponentLeague: lpl3Div.name,
            teamScore: cf1.awayScore, opponentScore: cf1.homeScore,
            verdict: cf1.homeScore > cf1.awayScore ? 'not_promoted' : 'promoted'
          }
        }
      }
      if (rp16 && ganadores[1]) {
        const cf2 = simularPartidoPorRating(rp16.teamId, ganadores[1].teamId)
        rp16.opponentId = ganadores[1].teamId
        rp16.opponentName = ganadores[1].teamName
        rp16.opponentLeague = (divisions.find(function(d) { return d.id === ganadores[1].divId }) || {}).name || 'Cuarta Polonia'
        rp16.teamScore = cf2.homeScore
        rp16.opponentScore = cf2.awayScore
        rp16.verdict = cf2.homeScore > cf2.awayScore ? 'saved' : 'relegated'
        const gbDiv = divisions.find(function(d) { return d.id === ganadores[1].divId })
        if (gbDiv && gbDiv.promotionPlayoff) {
          gbDiv.promotionPlayoff.crossFinal = {
            opponentId: rp16.teamId, opponentName: rp16.name, opponentLeague: lpl3Div.name,
            teamScore: cf2.awayScore, opponentScore: cf2.homeScore,
            verdict: cf2.homeScore > cf2.awayScore ? 'not_promoted' : 'promoted'
          }
        }
      }
    }
  }

  return { seasonNumber: state.seasonNumber, divisions }
}

function showMovementsTab(visible) {
  /* No longer used — movements shown inside progression view */
}

/* ============ ECONOMÍA SEMANAL ============ */
function procesarEconomiaSemanal() {
  /* Recuperación diaria de energía: al avanzar de jornada, el partido ya
     jugado (currentMatchday - 1) se recupera +7%/día según los días hasta
     el siguiente. Semana normal → 100%; doble partido (≤4 días) → tope 85%. */
  try {
    var justPlayed = getFixtureForUser(state.currentMatchday - 1)
    if (justPlayed) aplicarRecuperacionDiaria(justPlayed)
  } catch (e) { console.warn('[RECOVERY] Error al recuperar energía:', e) }

  /* Gastos operativos semanales (0.8% del presupuesto inicial) */
  if (state.presupuestoInicial > 0) {
    var gastos = Math.round(state.presupuestoInicial * 0.008)
    state.finances.balance -= gastos
    state.finances.history.push({ reason: 'Gastos operativos semanales', amount: -gastos })
  }
  procesarIngresosPatrocinio()
  procesarLesiones()
  recuperarPorterosAl100()
  procesarVentasCPU()
  checkTransferWindow()
  if (state.transferWindowOpen) {
    procesarVentanaTransferencias()
    procesarIAOfertasAlUsuario()
    gestionarFilialesCPU()
    generarOfertasCanteranos()
    detectarExcedentesCantera()
  }
  /* Pop-up prioritario una vez por avance de semana (anti-spam). */
  try { mostrarPopupPrioridad() } catch (e) { console.warn('[POPUP] Error al mostrar popup prioridad:', e) }
}

function procesarLesiones() {
  /* Weekly injury chance for user's players (training/match fatigue) */
  if (!state.players) return
  var injuryProb = 0.008  /* 0.8% per field player per week */
  var gkProb = 0.005     /* 0.5% per goalkeeper per week */
  for (var i = 0; i < state.players.length; i++) {
    var p = state.players[i]
    if (p.injury) continue
    if (esPortero(p)) {
      /* Lesiones semanales específicas de porteros: leve / moderada / grave */
      if (Math.random() < gkProb) {
        var rg = Math.random()
        var weeks, desc, type
        if (rg < 0.70) { weeks = 1 + Math.floor(Math.random() * 2); desc = 'Sobrecarga'; type = 'leve' }
        else if (rg < 0.95) { weeks = 3 + Math.floor(Math.random() * 3); desc = 'Esguince de dedo'; type = 'moderada' }
        else { weeks = 10 + Math.floor(Math.random() * 7); desc = 'Lesi\u00f3n de ligamentos'; type = 'grave' }
        p.injury = { remaining: weeks, type: type, description: desc }
        addNotification('injury', '\u26A0 Lesi\u00f3n: ' + p.name, p.name + ' (' + desc + ') — ' + weeks + ' jornada' + (weeks > 1 ? 's' : ''), { logo: NOPHOTO })
      }
    } else {
      if (Math.random() < injuryProb) {
        var weeks = 1 + Math.floor(Math.random() * 3)
        if (Math.random() < 0.2) weeks += 1 + Math.floor(Math.random() * 4)
        p.injury = { remaining: weeks }
        addNotification('injury', '\u26A0 Lesi\u00f3n: ' + p.name, p.name + ' lesionado por ' + weeks + ' jornada' + (weeks > 1 ? 's' : ''), { logo: NOPHOTO })
      }
    }
  }
  /* Weekly injury chance for CPU players */
  for (var t = 0; t < state.leagueTeams.length; t++) {
    var team = state.leagueTeams[t]
    if (!team.players) continue
    for (var j = 0; j < team.players.length; j++) {
      var cp = team.players[j]
      if (cp.injury) continue
      if (Math.random() < injuryProb * 0.8) {
        cp.injury = { remaining: 1 + Math.floor(Math.random() * 3) }
      }
    }
  }
  /* Count down existing injuries (único descuento semanal) */
  var allPools = [state.players]
  state.leagueTeams.forEach(function(t) { if (t.players) allPools.push(t.players) })
  for (var pi = 0; pi < allPools.length; pi++) {
    var pool = allPools[pi]
    for (var pj = 0; pj < pool.length; pj++) {
      var pl = pool[pj]
      if (pl.injury && pl.injury.remaining) {
        pl.injury.remaining--
        if (pl.injury.remaining <= 0) {
          pl.energy = (pl.injury.recoveryEnergy != null ? pl.injury.recoveryEnergy : 100)
          pl.injury = null
          if (pool === state.players) addNotification('general', '\ud83d\udcaa Recuperado: ' + pl.name, 'Vuelve tras superar su lesi\u00f3n')
        }
      }
    }
  }
}

function procesarSuspensiones() {
  var bajas = []
  state.players.filter(function(p) { return p._redThisMatch }).forEach(function(p) {
    if (p._redType === 'directGrave') p._suspended = 2 + Math.floor(Math.random() * 2)
    else p._suspended = 1
    var motivo = p._redType === 'doubleYellow' ? 'doble amarilla' : p._redType === 'directGrave' ? 'roja grave' : 'roja leve'
    bajas.push(p.name + ' (' + motivo + ')')
  })
  state.players.filter(function(p) { return (p.yellowCards || 0) >= 5 && !p._suspended }).forEach(function(p) {
    p._suspended = 1
    p.yellowCards = 0
    bajas.push(p.name + ' (5 amarillas)')
  })
  if (bajas.length > 0) addNotification('match', '\ud83d\udfe5 Suspensiones', 'Sancionados: ' + bajas.join(', '))
}

function liberarSuspensiones() {
  state.players.forEach(function(p) {
    if (p._suspended) {
      p._suspended--
      if (p._suspended <= 0) p._suspended = null
    }
  })
}

function getSeasonLabel() {
  var sn = state.seasonNumber || 1
  var s1 = String(2026 + sn - 1).slice(-2)
  var s2 = String(2026 + sn).slice(-2)
  return s1 + '/' + s2
}

function recordAllTeamsSeasonHistory() {
  if (!state.allTeamsHistory) state.allTeamsHistory = {}
  var seasonLabel = getSeasonLabel()
  for (var ci in window.DB) {
    var cd = window.DB[ci]
    if (!cd || !cd.country || !cd.country.leagues) continue
    var leagues = cd.country.leagues
    for (var li = 0; li < leagues.length; li++) {
      var league = leagues[li]
      var data = state.allLeagueData[league.id]
      if (!data || !data.fixtures) continue
      var teamIds = league.teams.map(function(t) { return t.id })
      var standings = computeStandings(data.fixtures, teamIds)
      if (!standings || standings.length === 0) continue
      for (var si = 0; si < standings.length; si++) {
        var tid = standings[si].teamId
        if (!state.allTeamsHistory[tid]) state.allTeamsHistory[tid] = { seasons: [] }
        state.allTeamsHistory[tid].seasons.push({ season: seasonLabel, division: getCanonicalLeagueName(league.id, league.name), position: si + 1 })
      }
    }
  }
}

function hasTrophy(arr, competition, season) {
  if (!arr || arr.length === 0) return false
  var s = String(season)
  return arr.some(function(t) { return t.competition === competition && String(t.season) === s })
}

function recordSeasonTrophyWinners() {
  if (!state.allTeamsHistory) state.allTeamsHistory = {}
  var sl = getSeasonLabel()
  /* League champions - all leagues in all countries */
  for (var ci in window.DB) {
    var cd = window.DB[ci]
    if (!cd || !cd.country || !cd.country.leagues) continue
    var leagues = cd.country.leagues
    for (var li = 0; li < leagues.length; li++) {
      var league = leagues[li]
      var data = state.allLeagueData[league.id]
      if (!data || !data.fixtures) continue
      var teamIds = league.teams.map(function(t) { return t.id })
      var standings = computeStandings(data.fixtures, teamIds)
      if (!standings || standings.length === 0) continue
      var champId = standings[0].teamId
      if (!state.allTeamsHistory[champId]) state.allTeamsHistory[champId] = { seasons: [], trophies: [] }
      if (!state.allTeamsHistory[champId].trophies) state.allTeamsHistory[champId].trophies = []
      var cn = getCanonicalLeagueName(league.id, league.name)
      if (!hasTrophy(state.allTeamsHistory[champId].trophies, cn, sl)) {
        state.allTeamsHistory[champId].trophies.push({ competition: cn, season: sl })
      }
    }
  }
  /* Cup champion */
  if (state.cupChampion) {
    var cupComp = getCupCompName(state.countryId)
    if (!state.allTeamsHistory[state.cupChampion]) state.allTeamsHistory[state.cupChampion] = { seasons: [], trophies: [] }
    if (!state.allTeamsHistory[state.cupChampion].trophies) state.allTeamsHistory[state.cupChampion].trophies = []
    if (!hasTrophy(state.allTeamsHistory[state.cupChampion].trophies, cupComp, sl)) {
      state.allTeamsHistory[state.cupChampion].trophies.push({ competition: cupComp, season: sl })
    }
  }
  /* Supercopa */
  if (state.supercopa && state.supercopa.winner) {
    var scComp = getSupercopaCompName(state.countryId)
    if (!state.allTeamsHistory[state.supercopa.winner]) state.allTeamsHistory[state.supercopa.winner] = { seasons: [], trophies: [] }
    if (!state.allTeamsHistory[state.supercopa.winner].trophies) state.allTeamsHistory[state.supercopa.winner].trophies = []
    if (!hasTrophy(state.allTeamsHistory[state.supercopa.winner].trophies, scComp, sl)) {
      state.allTeamsHistory[state.supercopa.winner].trophies.push({ competition: scComp, season: sl })
    }
  }
  /* Taca da Liga */
  if (state.tacaDaLigaChampion) {
    var tacaComp = getTacaDaLigaCompName()
    if (!state.allTeamsHistory[state.tacaDaLigaChampion]) state.allTeamsHistory[state.tacaDaLigaChampion] = { seasons: [], trophies: [] }
    if (!state.allTeamsHistory[state.tacaDaLigaChampion].trophies) state.allTeamsHistory[state.tacaDaLigaChampion].trophies = []
    if (!hasTrophy(state.allTeamsHistory[state.tacaDaLigaChampion].trophies, tacaComp, sl)) {
      state.allTeamsHistory[state.tacaDaLigaChampion].trophies.push({ competition: tacaComp, season: sl })
    }
  }
  /* EFL Cup */
  if (state.eflCupChampion) {
    var eflComp = getEflCupCompName()
    if (!state.allTeamsHistory[state.eflCupChampion]) state.allTeamsHistory[state.eflCupChampion] = { seasons: [], trophies: [] }
    if (!state.allTeamsHistory[state.eflCupChampion].trophies) state.allTeamsHistory[state.eflCupChampion].trophies = []
    if (!hasTrophy(state.allTeamsHistory[state.eflCupChampion].trophies, eflComp, sl)) {
      state.allTeamsHistory[state.eflCupChampion].trophies.push({ competition: eflComp, season: sl })
    }
  }
}

function procesarVentasCPU() {
  const transferibles = state.players.filter(p => p.transferListed && p.transferPrice > 0)
  for (const p of transferibles) {
    if (Math.random() > 0.15) continue
    state.finances.balance += p.transferPrice
    state.finances.history.push({ reason: `💰 Venta: ${p.name}`, amount: p.transferPrice })
    const idx = state.players.indexOf(p)
    if (idx >= 0) state.players.splice(idx, 1)
    addNotification('transfer', `💰 Vendido: ${p.name}`, `${formatMoney(p.transferPrice)} · Traspasado a un equipo de la liga`)
  }
}

/* ============ TRANSFER WINDOW SYSTEM ============ */
function checkTransferWindow() {
  const md = state.currentMatchday
  const wasOpen = state.transferWindowOpen
  if ((md >= TRANSFER_WINDOW_SUMMER_START && md <= TRANSFER_WINDOW_SUMMER_END) ||
      (md >= TRANSFER_WINDOW_WINTER_START && md <= TRANSFER_WINDOW_WINTER_END)) {
    state.transferWindowOpen = true
  } else {
    state.transferWindowOpen = false
  }
  if (state.transferWindowOpen && !wasOpen) {
    addNotification('general', '📢 Mercado de fichajes abierto', 'Comienza el período de transferencias')
    procesarVentanaTransferencias()
  } else if (!state.transferWindowOpen && wasOpen) {
    addNotification('general', '🔒 Mercado cerrado', 'El período de transferencias ha finalizado')
  }
}

function gestionarFilialesCPU() {
  /* CPU parent teams promote their best B team player (skill >= 75) once per window */
  if (!state.transferWindowOpen) return
  for (var i = 0; i < state.leagueTeams.length; i++) {
    var team = state.leagueTeams[i]
    if (team.teamId === state.teamId) continue
    if (team.players.length >= MAX_SQUAD) continue
    var bTeamId = findBTeamOf(team.teamId)
    if (!bTeamId) continue
    /* Check if the B team is the user's filial squad */
    var isUserFilial = (bTeamId === getFilialId(state.teamId))
    var bSquad = isUserFilial ? state.filialSquad : getRealSquad(bTeamId)
    if (!bSquad || bSquad.length === 0) continue
    /* Check which positions the parent team is short on */
    var posCount = {}
    team.players.forEach(function(p) {
      var key = SIGLA_TO_POS[p.position] || p.position
      posCount[key] = (posCount[key] || 0) + 1
    })
    var candidates = bSquad.filter(function(p) {
      if (isUserFilial && state.boughtPlayerIds.indexOf(p.id) >= 0) return false
      if (!isUserFilial && state.boughtPlayerIds.indexOf(p.id) < 0) return false
      if (p.skill < 75) return false
      if (p.injury) return false
      var posKey = SIGLA_TO_POS[p.position] || p.position
      /* Bonus if parent team has < 2 players in this position */
      return (posCount[posKey] || 0) < 2
    })
    if (candidates.length === 0) {
      /* Fallback: promote any player >= 75 */
      candidates = bSquad.filter(function(p) {
        return p.skill >= 75 && !p.injury && (isUserFilial || state.boughtPlayerIds.indexOf(p.id) < 0)
      })
    }
    if (candidates.length === 0) continue
    candidates.sort(function(a, b) { return b.skill - a.skill })
    var best = candidates[0]
    var newP = { ...best, id: 'cpu-promoted-' + best.id + '-' + Date.now(), value: calcValue(best.skill, best.age, best.position), energy: 100, matches: 0, goals: 0, assists: 0, yellowCards: 0, redCards: 0, teamStats: {} }
    team.players.push(newP)
    if (!isUserFilial) state.boughtPlayerIds.push(best.id)
    if (isUserFilial) {
      /* Remove from user's filial squad */
      var fIdx = state.filialSquad.indexOf(best)
      if (fIdx >= 0) state.filialSquad.splice(fIdx, 1)
      addNotification('transfer', '\u2B06 ' + best.name + ' sube al primer equipo', team.name + ' recluta a ' + best.name + ' desde el filial')
      renderSquad(state.players)
    } else {
      addNotification('transfer', '\u2B06 ' + best.name + ' sube al primer equipo CPU', team.name + ' promociona desde el filial')
    }
  }
}

function procesarVentanaTransferencias() {
  if (!state.transferWindowOpen) return
  /* Only simulate once per matchday — prevents extra transfers on reload */
  if (state.mercadoSimuladoSemana === state.currentMatchday) return
  state.mercadoSimuladoSemana = state.currentMatchday
  /* Run legacy functions for each CPU team (listing + filial promotion) */
  for (const team of state.leagueTeams) {
    if (team.teamId === state.teamId) continue
    procesarIAListarJugadores(team)
  }
  gestionarFilialesCPU()
  procesarCesionesCPU()
  /* Run the new SimuladorMercadoIA (3-8 global operations per call) */
  var mktResult = simularMercadoIA()
  /* Generate offers to the human player */
  var userOffers = generarOfertaAlUsuario(state.players)
  if (userOffers && userOffers.length > 0) {
    for (var oi = 0; oi < userOffers.length; oi++) {
      var o = userOffers[oi]
      addNotification('transfer', 'Oferta por ' + o.playerName,
        o.teamName + ' ofrece ' + formatMoney(o.amount), o)
    }
  }
  return mktResult
}

function getReputacion(team) {
  return team ? (team.rating || 50) : 50
}

function getTeamBudget(team) {
  var r = team.rating || 50
  return Math.round(r * 150000)
}

function registrarTraspasoEnHistorial(data) {
  if (!state.historialTraspasosGlobal) state.historialTraspasosGlobal = []
  var entry = {
    id: Date.now() + '-' + Math.random().toString(36).slice(2, 6),
    jugadorNombre: data.playerName,
    jugadorMedia: data.playerSkill || 0,
    jugadorPosicion: data.playerPosition || '',
    jugadorEdad: data.playerAge || 0,
    jugadorAvatar: data.playerAvatar || '',
    equipoOrigen: data.fromTeam,
    origenId: data.fromTeamId || '',
    origenLogo: data.fromLogo || '',
    origenLigaId: data.fromLeagueId || '',
    equipoDestino: data.toTeam,
    destinoId: data.toTeamId || '',
    destinoLogo: data.toLogo || '',
    precio: data.price || 0,
    esCesion: !!data.isLoan,
    semana: state.currentMatchday || 0,
    esUsuario: !!data.isUserRelated,
    ligaId: data.leagueId || '',
    timestamp: Date.now(),
  }
  state.historialTraspasosGlobal.unshift(entry)
  if (state.historialTraspasosGlobal.length > 200) {
    state.historialTraspasosGlobal.length = 200
  }
}

/* ============================================================
   SISTEMA DE MERCADO Y FICHAJES DE LA IA (SimuladorMercadoIA)
   ============================================================
   Mejora respecto al sistema anterior:
   - Jerarquía por reputación (derivada del rating)
   - Detección inteligente de necesidades por posición
   - Sistema de cesiones priorizado
   - Ofertas al usuario basadas en rendimiento
   - Autolimitación: 3-8 operaciones por tanda
   ============================================================ */

/* ============================================================
   SIMULADOR DE MERCADO IA – VERSIÓN SIMPLIFICADA
   ============================================================
   Reglas de oro:
   1. Detectar exceso: si un equipo tiene >2 jugadores en una
      posición, pone al peor como transferible/cedible.
   2. Detectar necesidad: si una posición tiene 1 jugador o el
      titular es peor que la media del club, se busca refuerzo.
   3. Fichar: buscar en globalPlayers un jugador de esa posición
      con skill mayor que el actual y precio <= presupuesto.
   4. Si no hay presupuesto, probar cesión (joven o skill bajo).
   5. Garantía: en cada llamada se ejecutan 3-6 operaciones.
   ============================================================ */

function getAllTeams() {
  var teams = []
  var seen = {}
  for (var i = 0; i < state.leagueTeams.length; i++) {
    var t = state.leagueTeams[i]
    if (!seen[t.teamId]) { teams.push(t); seen[t.teamId] = true }
  }
  for (var lid in state.allLeagueData) {
    var d = state.allLeagueData[lid]
    if (d && d.teams) {
      for (var ti = 0; ti < d.teams.length; ti++) {
        var t2 = d.teams[ti]
        if (t2 && t2.teamId && !seen[t2.teamId] && t2.teamId !== state.teamId) {
          if (t2.players && t2.players.length > 0) { teams.push(t2); seen[t2.teamId] = true }
        }
      }
    }
  }
  return teams
}

function simularMercadoIA() {
  if (!state.transferWindowOpen) return { transfers: [], offers: [] }
  rebuildGlobalPlayerPool()
  var allTeams = getAllTeams()
  console.log('[MERCADO] Simulando mercado con ' + allTeams.length + ' equipos')
  if (allTeams.length < 2) return { transfers: [], offers: [] }
  var result = { transfers: [], offers: [] }
  var usedIds = {}
  var target = randInt(3, 6)
  var maxAttempts = target * 20
  var attempts = 0

  while (result.transfers.length < target && attempts < maxAttempts) {
    attempts++
    var buyer = allTeams[Math.floor(Math.random() * allTeams.length)]
    if (!buyer || buyer.teamId === state.teamId) continue
    if (buyer.players.length >= MAX_SQUAD) continue

    /* ---- PHASE 1: Mark excess players ---- */
    var ALL_POS = ['portero','defensa_central','lateral_der','lateral_izq','mediocentro','medio_def','medio_ofensivo','extremo_der','extremo_izq','delantero']
    for (var pi = 0; pi < ALL_POS.length; pi++) {
      var posL = ALL_POS[pi]
      var inPos = buyer.players.filter(function(x) { return x.position === posL && !x.onLoan })
      if (inPos.length > 2) {
        inPos.sort(function(a, b) { return a.skill - b.skill })
        var worst = inPos[0]
        if (!worst.transferListed) { worst.transferListed = true; worst.transferPrice = Math.round(worst.value * 0.6) }
        if (worst.age <= 23 && !worst.loanListed) worst.loanListed = true
      }
    }

    /* ---- PHASE 2: Detect need ---- */
    var bestPlayers = {}
    for (pi = 0; pi < ALL_POS.length; pi++) {
      posL = ALL_POS[pi]
      var filtered = buyer.players.filter(function(x) { return x.position === posL && !x.onLoan })
      if (filtered.length === 0) {
        if (!bestPlayers['__empty']) bestPlayers['__empty'] = []
        bestPlayers['__empty'].push(posL)
        continue
      }
      filtered.sort(function(a, b) { return b.skill - a.skill })
      bestPlayers[posL] = filtered[0]
    }
    var teamAvg = 0
    for (var pi2 = 0; pi2 < buyer.players.length; pi2++) teamAvg += buyer.players[pi2].skill
    teamAvg = Math.round(teamAvg / Math.max(1, buyer.players.length))

    var needPos = null
    if (bestPlayers['__empty'] && bestPlayers['__empty'].length > 0) {
      needPos = bestPlayers['__empty'][Math.floor(Math.random() * bestPlayers['__empty'].length)]
    } else {
      for (pi = 0; pi < ALL_POS.length; pi++) {
        posL = ALL_POS[pi]
        if (bestPlayers[posL] && (bestPlayers[posL].skill < teamAvg - 8)) {
          needPos = posL; break
        }
      }
    }
    if (!needPos) continue

    /* ---- PHASE 3: Find candidate & execute ---- */
    var budget = getTeamBudget(buyer)
    var currentStarter = bestPlayers[needPos]
    var currentSkill = currentStarter ? currentStarter.skill : 0

    /* First pass: look for transfer-listed players */
    var candidate = null
    var pool = state.globalPlayers.filter(function(p) {
      if (p.position !== needPos) return false
      if (p.teamId === state.teamId) return false
      if (p.onLoan) return false
      if (usedIds[p.id]) return false
      if (buyer.players.some(function(tp) { return tp.id === p.id })) return false
      if (p.skill <= currentSkill) return false
      if (p.value > budget) return false
      return true
    })
    if (pool.length > 0) {
      /* Prefer transfer-listed */
      var listed = pool.filter(function(p) { return p.transferListed })
      if (listed.length > 0) listed.sort(function(a, b) { return b.skill - a.skill })
      if (listed.length > 0) candidate = listed[0]
      else { pool.sort(function(a, b) { return b.skill - a.skill }); candidate = pool[0] }
    }

    if (candidate) {
      /* Find seller team in allTeams */
      var seller = null
      for (var st = 0; st < allTeams.length; st++) {
        if (allTeams[st].teamId === candidate.teamId) { seller = allTeams[st]; break }
      }
      if (seller && seller.teamId !== buyer.teamId) {
        var sellerPlayer = null
        for (var sp2 = 0; sp2 < seller.players.length; sp2++) {
          if (seller.players[sp2].id === candidate.id) { sellerPlayer = seller.players[sp2]; break }
        }
        if (sellerPlayer) {
          /* Don't strip seller of their last decent player in this position */
          var sellerInPos = seller.players.filter(function(x) { return x.position === needPos && !x.onLoan })
          if (sellerInPos.length > 1 || sellerPlayer.skill < 40) {
            var price = Math.round(candidate.value * (0.7 + Math.random() * 0.3))
            var idx = seller.players.indexOf(sellerPlayer)
            if (idx >= 0) seller.players.splice(idx, 1)
            var newP = {
              ...sellerPlayer,
              id: buyer.teamId + '-tr-' + Date.now() + '-' + Math.random().toString(36).slice(2, 4),
              transferListed: false, transferPrice: 0, loanListed: false,
              energy: randInt(70, 100), goals: 0, matches: 0, assists: 0,
              yellowCards: 0, redCards: 0, mvp: 0, matchHistory: []
            }
            buyer.players.push(newP)
            registrarTraspasoEnHistorial({
              playerName: candidate.name, playerSkill: candidate.skill,
              playerPosition: candidate.position, playerAge: candidate.age,
              playerAvatar: candidate.avatar || '',
              fromTeam: seller.name, fromTeamId: seller.teamId, fromLogo: seller.logo || '',
              toTeam: buyer.name, toTeamId: buyer.teamId, toLogo: buyer.logo || '',
              price: price, isLoan: false,
              isUserRelated: buyer.teamId === state.teamId || seller.teamId === state.teamId
            })
            if (buyer.teamId === state.teamId || seller.teamId === state.teamId) {
              addNotification('transfer', '\uD83D\uDCB0 Fichaje: ' + candidate.name,
                candidate.name + ' (' + formatMoney(price) + ') -> ' + buyer.name)
            }
            usedIds[candidate.id] = true
            result.transfers.push({ type: 'transfer', player: candidate.name, from: seller.name, to: buyer.name, price: price })
            rebuildGlobalPlayerPool()
            continue
          }
        }
      }
    }

    /* ---- PHASE 4: Loan fallback ---- */
    var loanPool = state.globalPlayers.filter(function(p) {
      if (p.position !== needPos) return false
      if (p.teamId === state.teamId) return false
      if (p.onLoan) return false
      if (usedIds[p.id]) return false
      if (buyer.players.some(function(tp) { return tp.id === p.id })) return false
      if (p.skill > 60) return false
      if (p.skill <= 20) return false
      return true
    })
    if (loanPool.length > 0) {
      /* Prefer loan-listed or young */
      var loanCandidates = loanPool.filter(function(p) { return p.loanListed || p.age <= 21 })
      if (loanCandidates.length === 0) loanCandidates = loanPool
      loanCandidates.sort(function(a, b) { return b.skill - a.skill })
      var loanPick = loanCandidates[0]
      var loanSeller = null
      for (var lt = 0; lt < allTeams.length; lt++) {
        if (allTeams[lt].teamId === loanPick.teamId) { loanSeller = allTeams[lt]; break }
      }
      if (loanSeller && loanSeller.teamId !== buyer.teamId) {
        var loanPlayer = null
        for (var lp2 = 0; lp2 < loanSeller.players.length; lp2++) {
          if (loanSeller.players[lp2].id === loanPick.id) { loanPlayer = loanSeller.players[lp2]; break }
        }
        if (loanPlayer) {
          var lidx = loanSeller.players.indexOf(loanPlayer)
          if (lidx >= 0) loanSeller.players.splice(lidx, 1)
          var sn = state.seasonNumber || 1
          var loanDur = Math.random() < 0.3 ? 0.5 : Math.random() < 0.6 ? 1 : 2
          var loaned = {
            ...loanPlayer,
            id: buyer.teamId + '-loan-' + Date.now(),
            onLoan: true, loanFrom: loanSeller.teamId,
            loanUntil: '30/06/' + (2026 + sn + Math.ceil(loanDur)),
            loanListed: false, transferListed: false, energy: randInt(70, 100)
          }
          buyer.players.push(loaned)
          registrarTraspasoEnHistorial({
            playerName: loanPick.name, playerSkill: loanPick.skill,
            playerPosition: loanPick.position, playerAge: loanPick.age,
            playerAvatar: loanPick.avatar || '',
            fromTeam: loanSeller.name, fromTeamId: loanSeller.teamId, fromLogo: loanSeller.logo || '',
            toTeam: buyer.name, toTeamId: buyer.teamId, toLogo: buyer.logo || '',
            price: 'Cedido', isLoan: true,
            isUserRelated: buyer.teamId === state.teamId || loanSeller.teamId === state.teamId
          })
          if (buyer.teamId === state.teamId || loanSeller.teamId === state.teamId) {
            addNotification('transfer', '\uD83D\uDD04 Cesión: ' + loanPick.name,
              loanPick.name + ' cedido al ' + buyer.name + ' desde ' + loanSeller.name)
          }
          usedIds[loanPick.id] = true
          result.transfers.push({ type: 'loan', player: loanPick.name, from: loanSeller.name, to: buyer.name })
          rebuildGlobalPlayerPool()
        }
      }
    }
  }
  console.log('[MERCADO] Resultado: ' + result.transfers.length + ' operaciones')
  return result
}

function generarOfertaAlUsuario(equipoUsuario) {
  if (!state.transferWindowOpen) return null
  var allTeams = getAllTeams()
  var userPlayers = (equipoUsuario || state.players).filter(function(p) { return !p.onLoan })
  var offers = []
  var shuffledTeams = allTeams.slice().sort(function() { return Math.random() - 0.5 })
  var offersCount = 0
  for (var ti = 0; ti < shuffledTeams.length && offersCount < 3; ti++) {
    var team = shuffledTeams[ti]
    if (team.teamId === state.teamId) continue
    if (team.players.length >= MAX_SQUAD) continue
    var budget = getTeamBudget(team)
    var targetSkill = (team.rating || 50) + randInt(-5, 10)
    var shuffledPlayers = userPlayers.slice().sort(function() { return Math.random() - 0.5 })
    for (var pi = 0; pi < shuffledPlayers.length && offersCount < 3; pi++) {
      var p = shuffledPlayers[pi]
      if (p.skill < targetSkill - 12) continue
      var prob = p.transferListed ? 0.6 : 0.12
      if (Math.random() > prob) continue
      var basePrice = p.transferListed && p.transferPrice ? p.transferPrice : Math.round(p.value * 0.7)
      var offer = Math.round(p.value * (0.8 + Math.random() * 0.5))
      if (offer < basePrice) offer = basePrice
      if (offer > budget * 0.4) continue
      if (getReputacion(team) < 50 && p.skill > 75) continue
      offers.push({
        playerId: p.id, teamId: team.teamId, amount: offer, teamName: team.name,
        playerName: p.name, playerValue: p.value, playerPosition: p.position,
        playerSkill: p.skill, playerAge: p.age, playerAvatar: p.avatar || '',
        teamLogo: team.logo || ''
      })
      offersCount++
    }
  }
  return offers.length > 0 ? offers : null
}

function procesarIAListarJugadores(team) {
  const players = team.players
  const posCount = {}
  for (const p of players) {
    posCount[p.position] = (posCount[p.position] || 0) + 1
  }
  for (const p of players) {
    if (p.transferListed || p.onLoan) continue
    if (p.skill < 20) {
      p.transferListed = true
      p.transferPrice = Math.round(p.value * 0.5)
      continue
    }
    if (posCount[p.position] > 4 && p.skill < 35 && Math.random() < 0.3) {
      p.transferListed = true
      p.transferPrice = Math.round(p.value * (0.7 + Math.random() * 0.3))
      continue
    }
    if (p.age > 33 && p.skill < 40 && Math.random() < 0.25) {
      p.transferListed = true
      p.transferPrice = Math.round(p.value * 0.6)
    }
    if (p.skill < 20 && Math.random() < 0.5) {
      p.transferListed = true
      p.transferPrice = Math.round(p.value * 0.4)
    }
  }
  const loanCandidates = players.filter(p => !p.onLoan && !p.loanListed && p.age <= 21 && p.skill < 50 && Math.random() < 0.3)
  for (const p of loanCandidates) {
    p.loanListed = true
  }
}

function procesarIAFichajes(team) {
  const budget = getTeamBudget(team)
  const players = team.players
  const posNeeded = []
  const posCount = {}
  for (const p of players) {
    posCount[p.position] = (posCount[p.position] || 0) + 1
  }
  const defs = ['defensa_central', 'lateral_der', 'lateral_izq']
  const mids = ['mediocentro', 'medio_def', 'medio_ofensivo', 'medio_der', 'medio_izq']
  const fwds = ['delantero', 'extremo_der', 'extremo_izq']
  if ((posCount['portero'] || 0) < 2) posNeeded.push('portero')
  for (const pos of defs) {
    if ((posCount[pos] || 0) < 2) { posNeeded.push(pos); break }
  }
  for (const pos of mids) {
    if ((posCount[pos] || 0) < 2) { posNeeded.push('mediocentro'); break }
  }
  for (const pos of fwds) {
    if ((posCount[pos] || 0) < 2) { posNeeded.push('delantero'); break }
  }
  if (players.length < MIN_SQUAD_SIZE && posNeeded.length === 0) {
    posNeeded.push(pickRandom([...defs, ...mids, ...fwds, 'portero']))
  }
  for (const neededPos of posNeeded) {
    const candidates = state.globalPlayers.filter(p => {
      if (p.teamId === state.teamId) return false
      if (p.onLoan && p.loanFrom) return false
      const alreadyInTeam = team.players.some(tp => tp.id === p.id)
      if (alreadyInTeam) return false
      const posKey = SIGLA_TO_POS[p.position] || p.position
      const match = posKey === neededPos || p.position === neededPos
      return match && p.value <= budget * 0.3 && p.skill > 20
    })
    if (candidates.length === 0) continue
    candidates.sort((a, b) => b.skill - a.skill)
    const pick = candidates[0]
    const sourceTeam = state.leagueTeams.find(t => t.teamId === pick.teamId)
    if (!sourceTeam) continue
    const price = Math.round(pick.value * (0.7 + Math.random() * 0.3))
    if (price > budget * 0.3) continue
    const sourcePlayer = sourceTeam.players.find(p => p.id === pick.id)
    if (!sourcePlayer) continue
    const ti = sourceTeam.players.indexOf(sourcePlayer)
    if (ti >= 0) sourceTeam.players.splice(ti, 1)
    const newP = { ...sourcePlayer, id: `${team.teamId}-tr-${Date.now()}-${Math.random().toString(36).slice(2, 4)}`, transferListed: false, transferPrice: 0, loanListed: false, energy: randInt(70, 100), goals: 0, matches: 0, assists: 0, yellowCards: 0, redCards: 0, mvp: 0, matchHistory: [] }
    team.players.push(newP)
    rebuildGlobalPlayerPool()
  }
}

function procesarIAOfertasAlUsuario() {
  if (!state.transferWindowOpen) return
  const userPlayers = state.players.filter(p => !p.onLoan)
  /* Higher probability for transfer-listed players */
  for (const team of state.leagueTeams) {
    if (team.players.length >= MAX_SQUAD) continue
    const budget = getTeamBudget(team)
    const targetSkill = (team.rating || 50) + randInt(-5, 10)
    var offersMade = 0
    for (const p of userPlayers) {
      if (offersMade >= 3) break
      if (p.skill < targetSkill - 10) continue
      var prob = p.transferListed ? 0.5 : 0.1
      if (Math.random() > prob) continue
      var minPrice = p.transferListed && p.transferPrice ? p.transferPrice : Math.round(p.value * 0.7)
      var offer = Math.round(p.value * (0.8 + Math.random() * 0.5))
      if (offer < minPrice) offer = minPrice
      if (offer > budget * 0.4) continue
      addNotification('transfer', 'Oferta por ' + p.name, team.name + ' ofrece ' + formatMoney(offer), {
        playerId: p.id, teamId: team.teamId, amount: offer, teamName: team.name,
        playerName: p.name, playerValue: p.value, playerPosition: p.position,
        playerSkill: p.skill, playerAge: p.age, playerAvatar: p.avatar || '',
        teamLogo: team.logo || ''
      })
      offersMade++
    }
  }
}

function procesarIAOfertasCesionAlUsuario() {
  if (!state.transferWindowOpen) return
  const loanCandidates = state.players.filter(p => p.loanListed && !p.onLoan)
  if (loanCandidates.length === 0) return
  for (const team of state.leagueTeams) {
    if (team.teamId === state.teamId) continue
    if (team.players.length >= MAX_SQUAD) continue
    var offersMade = 0
    for (const p of loanCandidates) {
      if (offersMade >= 2) break
      if (Math.random() > 0.3) continue
      var sn = state.seasonNumber || 1
      var loanDur = Math.random() < 0.3 ? 0.5 : Math.random() < 0.6 ? 1 : 2
      var loanUntil = '30/06/' + (2026 + sn + Math.ceil(loanDur))
      var duracionLabel = loanDur === 0.5 ? 'media temporada' : loanDur === 1 ? '1 temporada' : '2 temporadas'
      var playerClone = { ...p, id: team.teamId + '-loan-' + Date.now(), onLoan: true, loanFrom: state.teamId, loanUntil: loanUntil, loanListed: false, energy: randInt(70, 100), loanTo: null, loanToName: null, loanToLogo: null }
      var idx = state.players.indexOf(p)
      if (idx >= 0) state.players.splice(idx, 1)
      team.players.push(playerClone)
      if (state.finances) {
        var _posLoan = POS_ABBR[p.position] || p.position || '?'
        state.finances.history.push({ reason: 'Cesión: ' + p.name + ' (' + _posLoan + ') · ' + duracionLabel + ' · ' + team.name, amount: 0 })
      }
      registrarTraspasoEnHistorial({
        playerName: p.name, playerSkill: p.skill,
        playerPosition: p.position, playerAge: p.age,
        playerAvatar: p.avatar || '',
        fromTeam: state.team + ' (Tú)', fromTeamId: state.teamId, fromLogo: state.teamLogo || '',
        toTeam: team.name, toTeamId: team.teamId, toLogo: team.logo || '',
        price: 'Cesión', isLoan: true, isUserRelated: true
      })
      addNotification('transfer', '\uD83D\uDCC4 Cesion solicitada: ' + p.name, team.name + ' toma cedido a ' + p.name + ' por ' + duracionLabel)
      offersMade++
    }
  }
}

function generarOfertasParaJugador(player, opts) {
  opts = opts || {}
  if (!state.transferWindowOpen && !opts.forzada) return
  if (!player) return
  var cat = opts.categoriaEquipo || getPlayerCategory(player)
  var ofertas = []
  var posibles = state.leagueTeams.filter(function(t) {
    return t.players.length < MAX_SQUAD && getTeamBudget(t) > Math.round(player.value * 0.5)
  })
  posibles.sort(function() { return Math.random() - 0.5 })
  var maxOffers = opts.forzada ? Math.min(3, posibles.length) : Math.min(5, posibles.length)
  var prob = opts.forzada ? 0.8 : 0.4
  for (var oi = 0; oi < maxOffers; oi++) {
    var team = posibles[oi]
    if (!team) continue
    var targetSkill = (team.rating || 50) + randInt(-5, 10)
    if (player.skill < targetSkill - 12) continue
    if (Math.random() > prob) continue
    var basePrice = player.transferPrice || Math.round(player.value * 0.7)
    var offer = Math.max(basePrice, Math.round(player.value * (0.7 + Math.random() * 0.6)))
    if (offer > getTeamBudget(team) * 0.4) continue
    ofertas.push({ team: team, offer: offer })
  }
  if (ofertas.length === 0) return
  ofertas.forEach(function(o, idx) {
    setTimeout(function() {
      addNotification('transfer', 'Oferta por ' + player.name, o.team.name + ' ofrece ' + formatMoney(o.offer), {
        playerId: player.id, teamId: o.team.teamId, amount: o.offer, teamName: o.team.name,
        playerName: player.name, playerValue: player.value, playerPosition: player.position,
        playerSkill: player.skill, playerAge: player.age, playerAvatar: player.avatar || '',
        teamLogo: o.team.logo || '', categoriaEquipo: cat,
        recomendacion: recomendarSalida(player, o.offer)
      })
    }, idx * 600)
  })
}

/* ============ CANTErA: OFERTAS SEMANALES Y EXCEDENTES ============ */

/* Genera ofertas periódicas para promesas y excedentes de B/U18,
   todo va a la bandeja del usuario. */
function generarOfertasCanteranos() {
  if (!state.transferWindowOpen) return
  /* Excedentes de edad: generar oferta casi forzada */
  var excedentes = getOveragePlayers()
  excedentes.forEach(function(item) {
    generarOfertasParaJugador(item.player, { forzada: true, categoriaEquipo: item.category })
  })
  /* Promesas jóvenes: ofrecer a los más talentosos */
  var prospects = []
  ;(state.filialSquad || []).forEach(function(p) { if (p.skill >= 50 && p.age <= 23) prospects.push(p) })
  ;(state.filial2Squad || []).forEach(function(p) { if (p.skill >= 40 && p.age <= 18) prospects.push(p) })
  prospects.sort(function(a, b) { return b.skill - a.skill })
  var maxProspects = Math.min(5, prospects.length)
  for (var i = 0; i < maxProspects; i++) {
    if (Math.random() > 0.15) continue
    generarOfertasParaJugador(prospects[i])
  }
}

/* Detecta jugadores que superan la edad máxima de su categoría y genera
   ofertas + notificaciones. */
function detectarExcedentesCantera() {
  if (!state.transferWindowOpen) return
  var excedentes = getOveragePlayers()
  excedentes.forEach(function(item) {
    var p = item.player
    var catName = item.category === TEAM_CATEGORY.EQUIPO_B ? 'Equipo B' : 'U18'
    var maxAge = getCategoryMaxAge(item.category)
    addNotification('transfer', '\u26a0 Excedente de edad: ' + p.name,
      p.name + ' (' + p.age + ' a\u00f1os) supera la m\u00e1xima del ' + catName + ' (' + maxAge + '). Promuevelo o v\u00e9ndelo.',
      { playerId: p.id, teamId: null, amount: 0, teamName: catName,
        playerName: p.name, playerValue: p.value || 0, playerPosition: p.position,
        playerSkill: p.skill, playerAge: p.age, playerAvatar: p.avatar || '',
        teamLogo: '', categoriaEquipo: item.category,
        recomendacion: recomendarSalida(p, p.value || 0)
      })
    /* Generar ofertas automáticas para el excedente */
    generarOfertasParaJugador(p, { forzada: true, categoriaEquipo: item.category })
  })
}

/* ============ LOAN SYSTEM ============ */
function procesarCesionesCPU() {
  if (!state.transferWindowOpen) return
  for (const team of state.leagueTeams) {
    if (team.players.length < 18) {
      const loanPool = state.globalPlayers.filter(p => p.loanListed && p.skill > 20 && p.teamId !== team.teamId)
      if (loanPool.length === 0) continue
      loanPool.sort((a, b) => b.skill - a.skill)
      const pick = loanPool[0]
    const sourceTeam = getTeamObj(pick.teamId)
      if (!sourceTeam) continue
      const sourcePlayer = sourceTeam.players.find(p => p.id === pick.id)
      if (!sourcePlayer) continue
      const ti = sourceTeam.players.indexOf(sourcePlayer)
      if (ti >= 0) sourceTeam.players.splice(ti, 1)
      var sn = state.seasonNumber || 1
      var loanDur = Math.random() < 0.3 ? 0.5 : Math.random() < 0.6 ? 1 : 2
      var loanUntil = '30/06/' + (2026 + sn + Math.ceil(loanDur))
      var loaned = { ...sourcePlayer, id: `${team.teamId}-loan-${Date.now()}`, onLoan: true, loanFrom: sourceTeam.teamId, loanUntil: loanUntil, loanListed: false, transferListed: false, energy: randInt(70, 100), loanTo: null, loanToName: null, loanToLogo: null }
      team.players.push(loaned)
      if (team.teamId === state.teamId || sourceTeam.teamId === state.teamId) {
        addNotification('transfer', `🔄 Cesión: ${sourcePlayer.name}`, `${sourcePlayer.name} cedido al ${team.name} desde ${sourceTeam.name}`)
      }
      rebuildGlobalPlayerPool()
    }
  }
}

function procesarSolicitudCesion(player, team, seasons, resEl) {
  if (state.players.length >= MAX_SQUAD) { alert('Plantilla completa'); return }
  if (state.boughtPlayerIds.indexOf(player.id) >= 0) { alert('Este jugador ya no est\u00e1 disponible'); document.getElementById('player-detail-modal').classList.remove('open'); return }
  const result = evaluarCesion(player)
  if (result.type === 'accepted') {
    var sn = state.seasonNumber || 1
    var loanUntil = '30/06/' + (2026 + sn + Math.ceil(seasons))
    if (seasons === 0.5) {
      var md = state.currentMatchday || 1
      loanUntil = md < 19 ? '15/01/' + (2026 + sn) : '30/06/' + (2026 + sn)
    }
    var gi = state.globalPlayers.findIndex(function(p) { return p.id === player.id })
    if (gi >= 0) state.globalPlayers.splice(gi, 1)
    var sourceTeam = getTeamObj(player.teamId)
    if (!sourceTeam || !sourceTeam.players) {
      sourceTeam = state.leagueTeams.find(function(t) { return t.teamId === player.teamId || t.id === player.teamId })
    }
    if (sourceTeam && sourceTeam.players) {
      var ti = sourceTeam.players.findIndex(function(p) { return p.id === player.id || (p.name === player.name && p.skill === player.skill) })
      if (ti >= 0) {
        sourceTeam.players[ti].onLoan = true
        sourceTeam.players[ti].loanTo = state.teamId
        sourceTeam.players[ti].loanUntil = loanUntil
      }
    }
    var newPlayer = { ...player, id: 'loan-' + Date.now(), energy: 100, matches: 0, goals: 0, assists: 0, yellowCards: 0, redCards: 0, mvp: 0, matchHistory: [], transferListed: false, transferPrice: 0, loanListed: false, enPista: false, minutosEnPista: 0, convocado: false, titular: false, injury: null, onLoan: true, loanFrom: player.teamId, loanUntil: loanUntil, loanTo: null, loanToName: null, loanToLogo: null }
    state.players.push(newPlayer)
    state.boughtPlayerIds.push(player.id)
    registrarTraspasoEnHistorial({
      playerName: player.name, playerSkill: player.skill,
      playerPosition: player.position, playerAge: player.age,
      playerAvatar: player.avatar || '',
      fromTeam: (team ? team.name : ''), fromTeamId: player.teamId,
      toTeam: state.team + ' (Tú)', toTeamId: state.teamId, toLogo: state.teamLogo || '',
      price: 'Cesión', isLoan: true, isUserRelated: true
    })
    rebuildGlobalPlayerPool()
    var duracionLabel = seasons === 0.5 ? 'media temporada' : seasons === 1 ? '1 temporada' : '2 temporadas'
    showTransferConfirmModal({
      type: 'Cesión',
      price: 0,
      player: newPlayer,
      fromTeam: team ? team.name : '',
      fromLogo: '',
      toTeam: state.team,
      toLogo: state.teamLogo || '',
      isLoan: true
    })
    document.getElementById('player-detail-modal').classList.remove('open')
    renderSquad(state.players)
  } else {
    resEl.innerHTML = '<div style="text-align:center;padding:8px;background:rgba(239,68,68,0.1);border-radius:8px;font-size:13px;font-weight:600;color:#EF4444">' + result.msg + '</div>'
  }
}

function procesarRetornoCesiones() {
  var sn = state.seasonNumber || 1
  var currentSeasonEnd = '30/06/' + (2026 + sn)
  var nextSeasonEnd = '30/06/' + (2026 + sn + 1)
  for (const team of state.leagueTeams) {
    const loans = team.players.filter(p => p.onLoan && p.loanFrom)
    for (const p of loans) {
      if (p.loanUntil !== currentSeasonEnd && p.loanUntil !== nextSeasonEnd) continue
      var shouldReturn = p.loanUntil === currentSeasonEnd || (p.loanUntil === nextSeasonEnd && sn % 1 === 0)
      if (!shouldReturn) continue
      p.onLoan = false
      p.loanFrom = null
      p.loanFromName = null
      p.loanFromLogo = null
      p.loanUntil = null
      p.loanTo = null
    }
    /* Remove cloned loan players whose loan ended */
    var toRemove = []
    for (var ti = 0; ti < team.players.length; ti++) {
      var pl = team.players[ti]
      if (pl.id && pl.id.indexOf('-loan-') >= 0 && !pl.onLoan) {
        toRemove.push(ti)
      }
    }
    for (var ri = toRemove.length - 1; ri >= 0; ri--) {
      team.players.splice(toRemove[ri], 1)
    }
  }
  /* Also remove cloned loan players from user's team */
  var userToRemove = []
  for (var ui = 0; ui < state.players.length; ui++) {
    var upl = state.players[ui]
    if (upl.id && upl.id.indexOf('-loan-') >= 0 && !upl.onLoan) {
      userToRemove.push(ui)
    }
  }
  for (var uri = userToRemove.length - 1; uri >= 0; uri--) {
    state.players.splice(userToRemove[uri], 1)
  }
  const userLoans = state.players.filter(p => p.onLoan && p.loanFrom)
  for (const p of userLoans) {
    if (p.loanUntil === currentSeasonEnd || (p.loanUntil && p.loanUntil <= currentSeasonEnd)) {
      const originTeam = state.leagueTeams.find(t => t.teamId === p.loanFrom)
      if (originTeam) {
        var op = originTeam.players.find(function(pl) { return pl.onLoan && pl.loanTo === state.teamId && pl.name === p.name })
        if (op) {
          op.onLoan = false
          op.loanFrom = null
          op.loanUntil = null
          op.loanTo = null
        }
      }
      const idx = state.players.indexOf(p)
      if (idx >= 0) state.players.splice(idx, 1)
    }
  }
  const userLoanedOut = state.players.filter(p => p.onLoan && p.loanTo)
  for (const p of userLoanedOut) {
    if (!p.loanUntil || p.loanUntil <= currentSeasonEnd) {
      p.onLoan = false
      p.loanTo = null
      p.loanToName = null
      p.loanToLogo = null
      p.loanUntil = null
    }
  }
  rebuildGlobalPlayerPool()
}

function evaluarOfertaUsuario(player, price) {
  if (price >= Math.round(player.value * 1.15)) return { accepted: true }
  if (price >= Math.round(player.value * 0.75)) {
    const counter = Math.round(player.value * (0.95 + Math.random() * 0.35))
    return { accepted: false, counter: counter }
  }
  return { accepted: false, minimum: Math.round(player.value * 0.9) }
}

function mostrarOfertaTransferencia(player, team, offer) {
  const existing = document.getElementById('transfer-offer-modal')
  if (existing) existing.remove()
  const overlay = document.createElement('div')
  overlay.id = 'transfer-offer-modal'
  overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.4);display:flex;align-items:center;justify-content:center;z-index:9999'
  const valueStr = formatMoney(player.value)
  const offerStr = formatMoney(offer)

  function renderInitial() {
    var teamLogoUrl = team.logo || NOPHOTO
    var playerAvatarUrl = player.avatar || NOPHOTO
    var exchangeSvg = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="17 1 21 5 17 9"/><path d="M3 11V9a4 4 0 0 1 4-4h14"/><polyline points="7 23 3 19 7 15"/><path d="M21 13v2a4 4 0 0 1-4 4H3"/></svg>'
    var arrowSvg = '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>'
    var moneySvg = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M16 8h-6a2 2 0 1 0 0 4h4a2 2 0 1 1 0 4H8"/><path d="M12 18V6"/></svg>'
    var chartSvg = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>'
    var checkSvg = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>'
    var crossSvg = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>'
    var refreshSvg = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg>'
    var posKey = player.position
    var posInternal = SIGLA_TO_POS[posKey] || posKey
    var posAbbr = POS_ABBR[posInternal] || posKey
    var posFull = (POSITIONS[posInternal]?.label) || posKey.charAt(0).toUpperCase() + posKey.slice(1).replace(/_/g, ' ')
    var posColor = POSITIONS[posInternal]?.color || '#888'
    var skillBadgeCss = getPowerBadgeStyle(player.skill || 0)
    var secondaryBadgesHtml = ''
    if (player.otherPositions && player.otherPositions.length > 0) {
      secondaryBadgesHtml = player.otherPositions.map(function(o) {
        var oPos = normalizePosKey(o.pos)
        var oInternal = SIGLA_TO_POS[oPos] || oPos
        var abbr = POS_ABBR[oInternal] || oPos
        var color = POSITIONS[oInternal]?.color || '#888'
        return '<span style="background:' + color + ';color:#fff;padding:0 5px;border-radius:3px;font-weight:700;font-size:10px;line-height:1.6">' + abbr + '</span>'
      }).join('')
    }
    overlay.innerHTML = `
      <div style="background:var(--bg-surface);border-radius:14px;padding:28px;max-width:420px;width:90%;box-shadow:0 4px 24px rgba(0,0,0,0.15);color:var(--text);font-family:inherit;border:1px solid var(--text-muted)">
        <div style="text-align:center;margin-bottom:16px">
          <div style="font-size:22px;font-weight:700;color:var(--text);margin-bottom:4px">${exchangeSvg} Oferta de fichaje</div>
        </div>
        <div style="display:flex;align-items:center;justify-content:center;gap:16px;margin-bottom:16px">
          <div style="text-align:center;flex:1">
            <img src="${teamLogoUrl}" alt="" style="width:56px;height:56px;border-radius:50%;object-fit:cover;background:var(--bg-card);border:2px solid var(--text-muted);display:block;margin:0 auto 6px" onerror="this.src='${NOPHOTO}'">
            <div style="font-size:13px;font-weight:600;color:var(--text);line-height:1.2">${team.name}</div>
          </div>
          <div style="color:var(--text-muted)">${arrowSvg}</div>
          <div style="text-align:center;flex:1">
            <img src="${playerAvatarUrl}" alt="" style="width:56px;height:56px;border-radius:50%;object-fit:cover;background:var(--bg-card);border:2px solid var(--text-muted);display:block;margin:0 auto 6px" onerror="this.src='${NOPHOTO}'">
            <div style="font-size:13px;font-weight:600;color:var(--text);line-height:1.2">${player.name}</div>
            <div style="font-size:11px;color:var(--text-muted);margin-top:6px;display:flex;gap:4px;flex-wrap:wrap;justify-content:center;align-items:center">
              <span style="background:${posColor};color:#fff;padding:0 5px;border-radius:3px;font-weight:700;font-size:10px;line-height:1.6">${posAbbr}</span>
              ${secondaryBadgesHtml}
              <span>·</span>
            </div>
            <div style="font-size:11px;color:var(--text-muted);margin-top:4px;display:flex;gap:6px;justify-content:center;align-items:center">
              <span style="${skillBadgeCss};padding:0 5px;border-radius:3px;font-weight:700;font-size:10px;line-height:1.6">${player.skill}</span>
              <span>${player.age} a\u00f1os</span>
            </div>
          </div>
        </div>
        <div style="background:var(--bg);border-radius:10px;padding:16px;margin-bottom:16px">
          <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0">
            <span style="display:flex;align-items:center;gap:6px;font-size:14px;color:var(--text-secondary)">${moneySvg} Oferta</span>
            <span style="font-size:18px;font-weight:700;color:#2E7D32">${offerStr}</span>
          </div>
          <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-top:1px solid var(--text-muted)">
            <span style="display:flex;align-items:center;gap:6px;font-size:14px;color:var(--text-secondary)">${chartSvg} Valor de mercado</span>
            <span style="font-size:14px;color:var(--text)">${valueStr}</span>
          </div>
        </div>
        <div style="display:flex;gap:10px;margin-bottom:10px">
          <div onclick="aceptarOferta('${player.id}','${team.teamId}',${offer})" style="display:flex;align-items:center;justify-content:center;gap:6px;flex:1;padding:14px;background:#2E7D32;border-radius:10px;text-align:center;font-size:15px;font-weight:700;color:#fff;cursor:pointer;transition:background 0.2s" onmouseover="this.style.background='#388E3C'" onmouseout="this.style.background='#2E7D32'">${checkSvg} Aceptar</div>
          <div onclick="rechazarOferta('${player.id}')" style="display:flex;align-items:center;justify-content:center;gap:6px;flex:1;padding:14px;background:#c62828;border-radius:10px;text-align:center;font-size:15px;font-weight:700;color:#fff;cursor:pointer;transition:background 0.2s" onmouseover="this.style.background='#d32f2f'" onmouseout="this.style.background='#c62828'">${crossSvg} Rechazar</div>
        </div>
        <div onclick="window.renderContra()" style="display:flex;align-items:center;justify-content:center;gap:6px;padding:14px;background:var(--accent);border-radius:10px;text-align:center;font-size:15px;font-weight:700;color:#fff;cursor:pointer;transition:background 0.2s" onmouseover="this.style.background='#1E40AF'" onmouseout="this.style.background='var(--accent)'">${refreshSvg} Contraofertar</div>
      </div>`
  }
  window.renderInitial = renderInitial

  function renderContra() {
    overlay.innerHTML = `
      <div style="background:var(--bg-surface);border-radius:14px;padding:28px;max-width:420px;width:90%;box-shadow:0 4px 24px rgba(0,0,0,0.15);color:var(--text);font-family:inherit;border:1px solid var(--text-muted)">
        <div style="text-align:center;margin-bottom:20px">
          <div style="font-size:22px;font-weight:700;color:var(--text);margin-bottom:4px">Tu contraoferta</div>
          <div style="font-size:13px;color:var(--text-secondary)">Precio que quieres pedir a ${team.name}</div>
        </div>
        <div style="background:var(--bg);border-radius:10px;padding:16px;margin-bottom:10px">
          <div style="font-size:13px;color:var(--text-secondary);margin-bottom:6px">Precio (\u20AC)</div>
          <input id="co-price" type="text" inputmode="numeric" value="${player.value.toLocaleString('es-ES')}" style="width:100%;padding:12px;background:var(--bg-surface);border:1px solid var(--text-muted);border-radius:8px;color:var(--text);font-size:18px;font-weight:700;outline:none;box-sizing:border-box">
          <div style="font-size:13px;color:var(--text-secondary);margin-top:8px">Valor de mercado: ${valueStr}</div>
        </div>
        <div id="co-resultado" style="margin-bottom:10px"></div>
        <div onclick="enviarContraoferta('${player.id}','${team.teamId}')" style="padding:14px;background:var(--accent);border-radius:10px;text-align:center;font-size:15px;font-weight:700;color:#fff;cursor:pointer;transition:background 0.2s;margin-bottom:8px" onmouseover="this.style.background='#1E40AF'" onmouseout="this.style.background='var(--accent)'">Enviar contraoferta</div>
        <div onclick="window.renderInitial()" style="padding:10px;background:transparent;border:1px solid var(--text-muted);border-radius:10px;text-align:center;font-size:14px;color:var(--text-secondary);cursor:pointer">Volver</div>
      </div>`
    document.getElementById('co-price').addEventListener('input', function() {
      var n = this.value.replace(/[^\d]/g, '')
      this.value = n ? parseInt(n, 10).toLocaleString('es-ES') : ''
    })
  }
  window.renderContra = renderContra

  window.enviarContraoferta = function(pid, tid) {
    var raw = document.getElementById('co-price').value.replace(/\./g, '')
    var price = parseInt(raw)
    if (!price || price < 1) { document.getElementById('co-resultado').innerHTML = '<div style="padding:10px;background:#c62828;border-radius:8px;font-size:13px;color:#fff;text-align:center">Introduce un precio v\u00e1lido</div>'; return }
    var pl = state.players.find(function(p) { return p.id === pid })
    if (!pl) return
    var teamObj = state.leagueTeams.find(function(t) { return t.teamId === tid })
    if (!teamObj) return
    var budget = getTeamBudget(teamObj)
    if (price > budget * 0.4) { document.getElementById('co-resultado').innerHTML = '<div style="padding:10px;background:#c62828;border-radius:8px;font-size:13px;color:#fff;text-align:center">El club no puede pagar esa cantidad</div>'; return }
    var prob = 0
    if (price >= pl.value * 1.15) prob = 80
    else if (price >= pl.value) prob = 55
    else if (price >= pl.value * 0.8) prob = 30
    else prob = 10
    if (Math.random() * 100 < prob) {
      document.getElementById('co-resultado').innerHTML = '<div style="padding:10px;background:#2E7D32;border-radius:8px;font-size:13px;color:#fff;text-align:center">\u00a1El club acepta tu contraoferta por ' + formatMoney(price) + '!</div>'
      setTimeout(function() { window.aceptarOferta(pid, tid, price) }, 800)
    } else {
      document.getElementById('co-resultado').innerHTML = '<div style="padding:10px;background:#c62828;border-radius:8px;font-size:13px;color:#fff;text-align:center">El club rechaza la contraoferta</div>'
    }
  }

  renderInitial()
  document.body.appendChild(overlay)
}

function showTransferConfirmModal(data) {
  var modal = document.getElementById('transfer-confirm-modal')
  if (!modal) return
  var type = data.type || 'Fichaje'
  var isBuy = type === 'Fichaje' || type === 'Cesión'
  var priceColor = type === 'Cesión' ? 'var(--text-muted)' : 'var(--success,#10B981)'
  var priceLabel = type === 'Cesión' ? 'Cesión' : formatMoney(data.price)
  var player = data.player
  if (!player) return

  document.getElementById('tcm-type').textContent = type
  var priceEl = document.getElementById('tcm-price')
  priceEl.textContent = priceLabel
  priceEl.style.color = priceColor

  var avatar = document.getElementById('tcm-avatar')
  avatar.src = player.avatar || NOPHOTO
  avatar.onerror = function() { this.src = NOPHOTO }

  var posKey = SIGLA_TO_POS[player.position] || player.position
  var posName = POSITIONS[posKey] ? POSITIONS[posKey].label : player.position
  document.getElementById('tcm-name').textContent = player.name
  document.getElementById('tcm-detail').textContent = posName + ' · ' + (POS_ABBR[posKey] || player.position) + ' · ' + player.skill + ' MED · ' + (player.age || '-') + ' años'

  /* Positions */
  var posHtml = ''
  var mainAbbr = POS_ABBR[posKey] || player.position
  var mainColor = (POSITIONS[posKey] && POSITIONS[posKey].color) || '#6B7280'
  posHtml += '<span style="background:' + mainColor + ';color:#fff;padding:1px 6px;border-radius:3px;font-weight:700;font-size:10px;line-height:1.8">' + mainAbbr + ' ' + (player.mainPct != null ? player.mainPct + '%' : '99%') + '</span>'
  if (player.otherPositions && player.otherPositions.length > 0) {
    player.otherPositions.forEach(function(o) {
      var oPos = normalizePosKey(o.pos)
      var oKey = SIGLA_TO_POS[oPos] || oPos
      var oAbbr = POS_ABBR[oKey] || oPos
      var oColor = (POSITIONS[oKey] && POSITIONS[oKey].color) || '#888'
      posHtml += '<span style="background:' + oColor + ';color:#fff;padding:1px 5px;border-radius:3px;font-weight:700;font-size:10px;line-height:1.8">' + oAbbr + ' ' + o.pct + '%</span>'
    })
  }
  document.getElementById('tcm-positions').innerHTML = posHtml

  /* Stats from previous team */
  var statsHtml = ''
  if (data.teamStats) {
    statsHtml += '<span style="color:var(--text-muted)">PJ: ' + (data.teamStats.matches || 0) + '</span>'
    statsHtml += '<span style="color:var(--text-muted)">Goles: ' + (data.teamStats.goals || 0) + '</span>'
    statsHtml += '<span style="color:var(--text-muted)">Asistencias: ' + (data.teamStats.assists || 0) + '</span>'
  } else if (player.teamStats) {
    var tId = data.fromTeamId || data.player.fromTeamId || (player.teamId)
    var ts = tId && player.teamStats ? player.teamStats[tId] : null
    if (ts) {
      statsHtml += '<span style="color:var(--text-muted)">PJ: ' + (ts.matches || 0) + '</span>'
      statsHtml += '<span style="color:var(--text-muted)">Goles: ' + (ts.goals || 0) + '</span>'
      statsHtml += '<span style="color:var(--text-muted)">Asistencias: ' + (ts.assists || 0) + '</span>'
    }
  }
  if (player.nationality) statsHtml += '<span style="color:var(--text-muted)">' + player.nationality + '</span>'
  if (!statsHtml) statsHtml = '<span style="color:var(--text-muted)">Sin estadísticas disponibles</span>'
  document.getElementById('tcm-stats').innerHTML = statsHtml

  /* Clubs */
  var clubsHtml = ''
  var fLogo = data.fromLogo || ''
  var tLogo = data.toLogo || ''
  var arrowSvg = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>'
  clubsHtml += fLogo ? '<img src="' + fLogo + '" style="width:22px;height:22px;border-radius:50%;object-fit:contain" onerror="this.style.display=\'none\'">' : '<span style="color:var(--text-muted)">' + escHtml(data.fromTeam || '') + '</span>'
  clubsHtml += '<span style="color:var(--text-muted)">' + arrowSvg + '</span>'
  clubsHtml += tLogo ? '<img src="' + tLogo + '" style="width:22px;height:22px;border-radius:50%;object-fit:contain" onerror="this.style.display=\'none\'">' : '<span style="color:var(--text-muted)">' + escHtml(data.toTeam || '') + '</span>'
  document.getElementById('tcm-clubs').innerHTML = clubsHtml

  modal.style.display = 'flex'
  document.getElementById('tcm-btn-ok').onclick = function() { modal.style.display = 'none' }
  modal.querySelector('.modal-overlay')?.addEventListener('click', function(e) { if (e.target === modal) modal.style.display = 'none' })
}

window.aceptarOferta = function(playerId, teamId, offer) {
  try { var mod = document.getElementById('transfer-offer-modal'); if (mod) mod.remove() } catch(e) {}
  var found = findPlayerInPools(playerId)
  if (!found) return
  var player = found.pool[found.idx]
  var team = state.leagueTeams.find(t => t.teamId === teamId)
  if (!team) return
  if (team.players.length >= MAX_SQUAD) {
    addNotification('transfer', '⚠️ Oferta cancelada: ' + player.name, team.name + ' tiene la plantilla completa')
    return
  }
  state.finances.balance += offer
  var _posSell = POS_ABBR[player.position] || player.position || '?'
  state.finances.history.push({ reason: 'Traspaso: ' + player.name + ' (' + _posSell + ') · ' + formatMoney(offer) + ' · ' + team.name, amount: offer })
  var newP = { ...player, id: teamId + '-tr-' + Date.now(), transferListed: false, transferPrice: 0, loanListed: false, energy: randInt(70, 100), goals: 0, matches: 0, assists: 0, yellowCards: 0, redCards: 0, mvp: 0, matchHistory: [] }
  team.players.push(newP)
  found.pool.splice(found.idx, 1)
  var myFil = getFilialId(state.teamId)
  var myU18 = myFil ? getFilialId(myFil) : null
  var fromName = found.poolName === TEAM_CATEGORY.PRIMER_EQUIPO ? state.team + ' (Tú)' :
                 found.poolName === TEAM_CATEGORY.EQUIPO_B ? getTeamName(myFil) : getTeamName(myU18)
  registrarTraspasoEnHistorial({
    playerName: player.name, playerSkill: player.skill,
    playerPosition: player.position, playerAge: player.age,
    playerAvatar: player.avatar || '',
    fromTeam: fromName, fromTeamId: state.teamId, fromLogo: state.teamLogo || '',
    toTeam: team.name, toTeamId: team.teamId, toLogo: team.logo || '',
    price: offer, isLoan: false, isUserRelated: true
  })
  showTransferConfirmModal({
    type: 'Traspaso',
    price: offer,
    player: player,
    fromTeam: fromName,
    fromLogo: state.teamLogo || '',
    toTeam: team.name,
    toLogo: team.logo || '',
    isLoan: false
  })
  rebuildGlobalPlayerPool()
  renderClub()
  renderMarketContent()
}

window.rechazarOferta = function(playerId) {
  try { var mod = document.getElementById('transfer-offer-modal'); if (mod) mod.remove() } catch(e) {}
  var found = findPlayerInPools(playerId)
  if (found) addNotification('transfer', '❌ Oferta rechazada: ' + found.pool[found.idx].name, 'Has rechazado la oferta por ' + found.pool[found.idx].name)
}

window.contraOfertar = function(playerId, teamId, originalOffer) {
  const modal = document.getElementById('transfer-offer-modal')
  if (modal) modal.remove()
  var found = findPlayerInPools(playerId)
  if (!found) return
  var player = found.pool[found.idx]
  if (!player) return
  const counterPrice = Math.round(player.value * 1.1)
  const team = state.leagueTeams.find(t => t.teamId === teamId)
  if (!team) return
  const budget = getTeamBudget(team)
  if (counterPrice > budget * 0.4) {
    addNotification('transfer', `📊 Contraoferta rechazada`, `${team.name} no puede pagar ${formatMoney(counterPrice)} por ${player.name}`)
    return
  }
  addNotification('transfer', `📊 Contraoferta enviada`, `${formatMoney(counterPrice)} pedido a ${team.name} por ${player.name}`)
  if (Math.random() < 0.4) {
    addNotification('transfer', `✅ Contraoferta aceptada`, `${team.name} acepta pagar ${formatMoney(counterPrice)} por ${player.name}`)
    window.aceptarOferta(playerId, teamId, counterPrice)
  } else {
    addNotification('transfer', `❌ Contraoferta rechazada`, `${team.name} rechaza la contraoferta por ${player.name}`)
  }
}

function renderMovements() {
  const container = document.getElementById('movements-content')
  if (!container) return
  const data = state.lastSeasonMovements
  if (!data || !data.divisions || data.divisions.length === 0) {
    container.innerHTML = '<div class="empty-state" style="padding:40px;text-align:center;color:var(--text-muted)">No hay movimientos disponibles</div>'
    return
  }
  let html = '<div class="movements-wrap" style="padding:12px 14px">'
  html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">'
  html += '<h2 style="font-size:16px;font-weight:700;margin:0;color:var(--text)">Movimientos Temporada ' + data.seasonNumber + 'ª</h2>'
  html += '<button id="btn-back-from-movements" style="background:none;border:none;color:var(--accent);cursor:pointer;font-size:13px;font-weight:600;padding:4px 8px">\u2190 Volver</button>'
  html += '</div>'
  html += '<p style="font-size:12px;color:var(--text-muted);margin:0 0 16px">Ascensos y descensos en todas las categorías</p>'
  for (const div of data.divisions) {
    if (div.promoted.length === 0 && div.playoff.length === 0 && div.relegated.length === 0 && !div.crossPlayoff && !div.relegationPlayoff && !div.promotionPlayoff) continue
    var hasMovements = div.promoted.length > 0 || div.relegated.length > 0 || !!div.crossPlayoff || !!div.relegationPlayoff || !!div.promotionPlayoff
    if (!hasMovements && div.playoff.length === 0) continue
    html += '<div style="background:var(--bg-surface);border-radius:10px;padding:12px;margin-bottom:12px">'
    html += '<h3 style="font-size:14px;font-weight:700;margin:0 0 10px;color:var(--text)">' + div.name + '</h3>'
    if (div.promoted.length > 0) {
      html += '<div style="margin-bottom:8px">'
      html += '<div style="font-size:11px;font-weight:600;color:#22c55e;text-transform:uppercase;margin-bottom:4px">⬆ Ascienden</div>'
      for (const t of div.promoted) {
        var viaLabel = t.via === 'playoff' ? ' (promoción)' : ''
        html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(t.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + t.name + viaLabel + '</span></div>'
      }
      html += '</div>'
    }
    if (div.playoff.length > 0) {
      html += '<div style="margin-bottom:8px">'
      html += '<div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">🏆 Promoción</div>'
      for (const t of div.playoff) {
        html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(t.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + t.name + ' (' + t.pos + 'º)</span></div>'
      }
      html += '</div>'
    }
    if (div.relegated.length > 0) {
      html += '<div>'
      html += '<div style="font-size:11px;font-weight:600;color:#ef4444;text-transform:uppercase;margin-bottom:4px">⬇ Descienden</div>'
      for (const t of div.relegated) {
        html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(t.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + t.name + '</span></div>'
      }
      html += '</div>'
    }
    if (div.crossPlayoff) {
      var cp = div.crossPlayoff
      var isHigher = cp.verdict === 'saved' || cp.verdict === 'relegated'
      html += '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border)">'
      html += '<div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">' + (isHigher ? '⚔ Playoff permanencia' : '⚔ Playoff ascenso') + '</div>'
      html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(cp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + getTeamName(cp.teamId) + ' ' + cp.scoreTeam + ' - ' + cp.scoreOpponent + ' <img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(cp.opponentId) + '" onerror="this.style.display=\'none\'"> ' + cp.opponentName + '</span></div>'
      if (isHigher) {
        var savedText = cp.verdict === 'saved' ? '✅ Se salva y permanece en ' + div.name : '❌ Desciende a ' + cp.opponentLeagueName
        html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + savedText + '</div>'
        html += '<div style="font-size:12px;color:var(--text-muted);padding-left:24px">' + (cp.verdict !== 'saved' ? '✅ ' + cp.opponentName + ' asciende a ' + div.name : '❌ ' + cp.opponentName + ' sigue en ' + cp.opponentLeagueName) + '</div>'
      } else {
        var promotedText = cp.verdict === 'promoted' ? '✅ Asciende a ' + cp.opponentLeagueName : '❌ Sigue en ' + div.name
        html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + promotedText + '</div>'
      }
      html += '</div>'
    }
    if (div.relegationPlayoff && div.relegationPlayoff.length > 0) {
      html += '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border)">'
      html += '<div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">⚔ Promoción permanencia</div>'
      for (const rp of div.relegationPlayoff) {
        if (rp.opponentId) {
          html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(rp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + rp.name + ' (' + rp.pos + 'º) ' + rp.teamScore + ' - ' + rp.opponentScore + ' <img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(rp.opponentId) + '" onerror="this.style.display=\'none\'"> ' + rp.opponentName + '</span></div>'
          var rpVerdict = rp.verdict === 'saved' ? '✅ Se salva y permanece en ' + div.name : '❌ Desciende a ' + (rp.opponentLeague || 'división inferior')
          html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + rpVerdict + '</div>'
          html += '<div style="font-size:12px;color:var(--text-muted);padding-left:24px">' + (rp.verdict === 'saved' ? '❌ ' + rp.opponentName + ' no asciende' : '✅ ' + rp.opponentName + ' asciende a ' + div.name) + '</div>'
        } else {
          html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(rp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + rp.name + ' (' + rp.pos + 'º)</span></div>'
        }
      }
      html += '</div>'
    }
    if (div.promotionPlayoff) {
      var pp = div.promotionPlayoff
      html += '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border)">'
      html += '<div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">⚔ Promoción ascenso</div>'
      html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(pp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + pp.teamName
      if (pp.intergroup) {
        var ig = pp.intergroup
        html += ' ' + ig.teamScore + ' - ' + ig.opponentScore + ' <img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(ig.opponentId) + '" onerror="this.style.display=\'none\'"> ' + ig.opponentName + '</span></div>'
        html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + (ig.won ? '✅ Gana la semifinal intergrupos' : '❌ Pierde la semifinal intergrupos - sigue en ' + div.name) + '</div>'
        if (pp.crossFinal) {
          var cf = pp.crossFinal
          html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text);padding-left:24px"><span>Final vs ' + cf.opponentName + ': ' + pp.teamName + ' ' + cf.teamScore + ' - ' + cf.opponentScore + ' ' + cf.opponentName + '</span></div>'
          html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + (cf.verdict === 'promoted' ? '✅ Asciende a ' + cf.opponentLeague : '❌ Sigue en ' + div.name) + '</div>'
        }
      } else {
        html += '</span></div>'
      }
      html += '</div>'
    }
    html += '</div>'
  }
  html += '</div>'
  container.innerHTML = html
  document.getElementById('btn-back-from-movements')?.addEventListener('click', function () {
    renderTab('progression')
  })
}

function applySeasonMovements(movementsData, countryId) {
  if (!movementsData || !movementsData.divisions) return
  var leagues = window.DB[countryId].country.leagues
  if (!leagues) return

  var allTeams = {}
  for (var l = 0; l < leagues.length; l++) {
    for (var t = 0; t < leagues[l].teams.length; t++) {
      allTeams[leagues[l].teams[t].id] = leagues[l].teams[t]
    }
  }

  function addToLeague(leagueId, teamObjs) {
    var target = leagues.find(function(l) { return l.id === leagueId })
    if (!target || !teamObjs || teamObjs.length === 0) return
    for (var x = 0; x < teamObjs.length; x++) {
      if (!target.teams.some(function(e) { return e.id === teamObjs[x].id })) {
        target.teams.push(teamObjs[x])
      }
    }
  }

  /* Phase 1: Remove outgoing teams from current leagues */
  for (var i = 0; i < movementsData.divisions.length; i++) {
    var div = movementsData.divisions[i]
    var league = leagues.find(function(l) { return l.id === div.id })
    if (!league) continue
    var rules = getLeagueRules(div.id)
    if (!rules) continue

    var toRemove = []

    for (var p = 0; p < div.promoted.length; p++) {
      toRemove.push(div.promoted[p].teamId)
    }

    if (rules.relegatesTo) {
      for (var r = 0; r < div.relegated.length; r++) {
        toRemove.push(div.relegated[r].teamId)
      }
      if (div.relegationPlayoff) {
        for (var rp = 0; rp < div.relegationPlayoff.length; rp++) {
          if (div.relegationPlayoff[rp].verdict === 'relegated') {
            toRemove.push(div.relegationPlayoff[rp].teamId)
          }
        }
      }
    }

    if (div.crossPlayoff) {
      if (div.crossPlayoff.verdict === 'relegated' && rules.relegatesTo) {
        toRemove.push(div.crossPlayoff.teamId)
      } else if (div.crossPlayoff.verdict === 'promoted' && rules.promotesTo) {
        toRemove.push(div.crossPlayoff.teamId)
      }
    }

    if (div.promotionPlayoff && div.promotionPlayoff.crossFinal && div.promotionPlayoff.crossFinal.verdict === 'promoted') {
      toRemove.push(div.promotionPlayoff.teamId)
    }

    league.teams = league.teams.filter(function(t) { return toRemove.indexOf(t.id) === -1 })
  }

  /* Phase 2: Add incoming teams to target leagues */
  for (var i = 0; i < movementsData.divisions.length; i++) {
    var div = movementsData.divisions[i]
    var rules = getLeagueRules(div.id)
    if (!rules) continue

    /* Promotions */
    if (rules.promotesTo) {
      var targets = Array.isArray(rules.promotesTo) ? rules.promotesTo : [rules.promotesTo]
      var promoting = []
      for (var p = 0; p < div.promoted.length; p++) {
        var pt = allTeams[div.promoted[p].teamId]
        if (pt) promoting.push(pt)
      }
      if (div.crossPlayoff && div.crossPlayoff.verdict === 'promoted') {
        var cpt = allTeams[div.crossPlayoff.teamId]
        if (cpt) promoting.push(cpt)
      }
      if (div.promotionPlayoff && div.promotionPlayoff.crossFinal && div.promotionPlayoff.crossFinal.verdict === 'promoted') {
        var ppt = allTeams[div.promotionPlayoff.teamId]
        if (ppt) promoting.push(ppt)
      }
      if (targets.length === 1) {
        addToLeague(targets[0], promoting)
      } else {
        for (var j = 0; j < targets.length && promoting.length > 0; j++) {
          addToLeague(targets[j], [promoting.shift()])
        }
      }
    }

    /* Relegations */
    if (rules.relegatesTo) {
      var targets = Array.isArray(rules.relegatesTo) ? rules.relegatesTo : [rules.relegatesTo]
      var relegated = []
      for (var r = 0; r < div.relegated.length; r++) {
        var rt = allTeams[div.relegated[r].teamId]
        if (rt) relegated.push(rt)
      }
      if (div.crossPlayoff && div.crossPlayoff.verdict === 'relegated') {
        var crt = allTeams[div.crossPlayoff.teamId]
        if (crt) relegated.push(crt)
      }
      if (div.relegationPlayoff) {
        for (var rp = 0; rp < div.relegationPlayoff.length; rp++) {
          if (div.relegationPlayoff[rp].verdict === 'relegated') {
            var rpt = allTeams[div.relegationPlayoff[rp].teamId]
            if (rpt) relegated.push(rpt)
          }
        }
      }
      for (var j = 0; j < targets.length; j++) {
        var group = []
        for (var k = j; k < relegated.length; k += targets.length) {
          group.push(relegated[k])
        }
        addToLeague(targets[j], group)
      }
    }
  }
}

function iniciarNuevaTemporada() {
  var data = state.lastSeasonProgressionData
  if (!data) return
  var retirados = data.result.retirados || []
  var msg = data.msg || ''
  var skipStandings = data.skipStandings
  try {
    try { if (state.lastSeasonMovements) applySeasonMovements(state.lastSeasonMovements, state.countryId) } catch (e) { console.error('[SEASON] Error applying movements:', e) }
    state.players.forEach(function(p) { p.age = (p.age || 22) + 1; p.value = calcValue(p.skill, p.age, p.position) })
    state.leagueTeams.forEach(function(t) { t.players.forEach(function(p) { p.age = (p.age || 22) + 1; p.value = calcValue(p.skill, p.age, p.position) }) })
    retirados.forEach(function(p) { var idx = state.players.indexOf(p); if (idx >= 0) state.players.splice(idx, 1) })
    var league = getLeagueFromId(state.leagueId)
    if (!league) { console.error('[SEASON] League not found for', state.leagueId, '- retrying load'); loadCountryData(state.countryId).then(function() { league = getLeagueFromId(state.leagueId) }) }
    var allTeams = league ? league.teams : []
    var filteredTeams = allTeams.filter(function(t) { return t.id !== state.teamId })
    if (filteredTeams.length + 1 > allTeams.length) {
      filteredTeams.sort(function(a, b) { return (a.rating || 0) - (b.rating || 0) })
      filteredTeams.splice(0, filteredTeams.length + 1 - allTeams.length)
    }
    state.leagueTeams = filteredTeams.map(function(t) {
      var existing = state.leagueTeams.find(function(x) { return x.teamId === t.id })
      return {
        teamId: t.id, name: t.name, logo: t.logo || null, palmares: t.palmares || null,
        players: existing ? existing.players.map(function(p) { return Object.assign({}, p, { energy: 100, injury: null, goals: 0, matches: 0 }) })
          : (getRealSquad(t.id) || []).map(function(p) { var pp = Object.assign({}, p, { value: p.value || calcValue(p.skill, p.age, p.position), enPista: false, minutosEnPista: 0, convocado: false, titular: false, injury: null, energy: 100, goals: 0, matches: 0 }); if (pp.loanedFrom) { pp.onLoan = true; pp.loanFrom = pp.loanedFrom; pp.loanFromName = pp.loanedFromName; pp.loanFromLogo = pp.loanedFromLogo } if (pp.loanedTo) { pp.onLoan = true; pp.loanTo = pp.loanedTo; pp.loanToName = pp.loanedToName; pp.loanToLogo = pp.loanedToLogo } return pp }),
      }
    })
    var allTeamsL = state.leagueTeams.concat([{ teamId: state.teamId, players: state.players }])
    for (var si = 0; si < allTeamsL.length; si++) {
      var srcTeamL = allTeamsL[si]
      for (var pi = 0; pi < srcTeamL.players.length; pi++) {
        var pL = srcTeamL.players[pi]
        if (pL.onLoan && pL.loanTo) {
          var destTeamL = state.leagueTeams.find(function(t) { return t.teamId === pL.loanTo })
          if (!destTeamL && pL.loanTo === state.teamId) destTeamL = { players: state.players }
          if (destTeamL) {
            var dupCloneL = destTeamL.players.some(function(x) { return x.loanFrom === srcTeamL.teamId && x.name === pL.name })
            if (!dupCloneL) {
              var cloneL = Object.assign({}, pL, { id: pL.id + '-loan-' + Date.now(), onLoan: true, loanFrom: srcTeamL.teamId, loanTo: null, loanToName: null, loanToLogo: null, energy: 100 })
              destTeamL.players.push(cloneL)
            }
          }
        }
      }
    }
    state.fixtures = generateFixtures([state.teamId].concat(state.leagueTeams.map(function(t) { return t.teamId })))
    state.totalMatchdays = state.fixtures.length > 0 ? Math.max.apply(null, state.fixtures.map(function(f) { return f.matchday })) : 38
    if (isAustriaBundesliga(state.leagueId)) {
      /* Austria: la temporada regular son 22 jornadas; la fase 2 (grupos,
         J23-J32) se genera al terminar la jornada 22. */
      state.totalMatchdays = austriaBundesligaConfig.regularSeason.matchdays
      state.fase2Built = false
      state.leaguePhase = 'regular'
    }
    state.currentMatchday = 1
    state._popupShownMatchday = null
    state._popupSuppressed = false
    state.transferWindowOpen = true
    state.mercadoSimuladoSemana = 0
    state.allLeagueData = {}
    state.halvingApplied = false
    state.halvingAppliedLeague = null
    state.fase2Built = false
    state.leaguePhase = 'regular'
    state.conferencePlayoffWinner = null
    state.austriaPhaseData = null
    initAllLeagueData()
    state.stats = { wins: 0, draws: 0, losses: 0, goalsFor: 0, goalsAgainst: 0 }
    state.playoffs = null
    state.absoluteFinal = null
    state.lastSeasonMovements = null
    state.lastSeasonProgressionData = null
    state.seasonNumber++
    state.presupuestoInicial = Math.round(getDivisionBaseBudget(state.leagueId) * getCountryBudgetMult(state.countryId))
    try {
      if (state.countryId === 'spain' || state.countryId === 'portugal' || state.countryId === 'poland' || state.countryId === 'france' || state.countryId === 'italy' || state.countryId === 'germany' || state.countryId === 'england' || state.countryId === 'austria' || state.countryId === 'belgium' || state.countryId === 'netherlands') {
        state.cup = generarCopa()
        state.supercopa = generarSupercopa()
        if (state.countryId === 'austria') state.supercopa = null
        if (state.countryId === 'portugal') state.tacaDaLiga = generarTacaDaLiga()
        if (state.countryId === 'england') state.eflCup = generarEflCup()
      }
      else { state.cup = null; state.supercopa = null; state.tacaDaLiga = null; state.eflCup = null }
    } catch (cupErr) { console.error('[SEASON] Error generating cups:', cupErr); state.cup = null; state.supercopa = null; state.tacaDaLiga = null; state.eflCup = null }
    state.players.forEach(function(p) { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0 })
    /* Renovaciones de patrocinio al inicio de cada temporada:
       slots vacíos siempre ofertan; los contratos activos corren solos;
       los que expiran ofrecen renovación (y el Naming Rights se revierte). */
    try { generarOfertasPatrocinioRenovacion() } catch (e) { console.warn('[SPONSOR] Error renovacion:', e) }
    document.getElementById('league-results-wrap').classList.add('hidden')
    renderTab('home')
    actualizarIndicadorTemporada()
    saveGame()
    if (!skipStandings) {
      addNotification('general', msg, 'Nueva temporada en ' + divName(state.leagueId))
      setTimeout(function() { alert(msg) }, 100)
    }
  } catch (err) {
    console.error('[SEASON] Critical error in iniciarNuevaTemporada:', err)
    document.getElementById('league-results-wrap').classList.add('hidden')
    state.currentMatchday = 1
    renderTab('home')
    saveGame()
  }
}

function showTrofeoModal(title, subtitle, logoUrl, onContinue) {
  var modal = document.getElementById('trofeo-modal')
  if (!modal) return
  document.getElementById('tm-title').textContent = title
  document.getElementById('tm-subtitle').textContent = subtitle
  var logoEl = document.getElementById('tm-logo')
  if (logoUrl) { logoEl.src = logoUrl; logoEl.style.display = '' }
  else { logoEl.style.display = 'none' }
  document.getElementById('tm-btn').onclick = function() {
    modal.style.display = 'none'
    modal.classList.remove('open')
    if (onContinue) onContinue()
  }
  modal.style.display = ''
  modal.classList.add('open')
}

function showSeasonProgressionModal(result, msg, skipStandings, nuevosTrofeos, logros) {
  state.lastSeasonProgressionData = { result: result, msg: msg, skipStandings: skipStandings, nuevosTrofeos: nuevosTrofeos || [], logros: logros || [] }
  var modal = document.getElementById('season-progression-modal')
  var content = document.getElementById('spm-content')
  var subtitle = document.getElementById('spm-subtitle')
  if (!modal || !content) { showSeasonEndFallback(); return }
  subtitle.textContent = 'T' + (state.seasonNumber || 1) + ' \u2014 Resumen del curso'
  var changes = result.changes || []
  var retirados = result.retirados || []
  var valueChanges = result.valueChanges || []
  var activeTab = state._progTab || 'progresion'
  var movementsData = state.lastSeasonMovements
  var html = '<div style="display:flex;gap:8px;margin-bottom:12px;border-bottom:1px solid var(--border);padding-bottom:8px">'
  html += '<button class="sub-tab' + (activeTab === 'progresion' ? ' active' : '') + '" data-spm-tab="progresion">Progresi\u00f3n</button>'
  if (movementsData) html += '<button class="sub-tab' + (activeTab === 'movimientos' ? ' active' : '') + '" data-spm-tab="movimientos">Movimientos</button>'
  html += '<button class="sub-tab' + (activeTab === 'competiciones' ? ' active' : '') + '" data-spm-tab="competiciones">Competiciones</button>'
  html += '</div>'
  if (activeTab === 'progresion') {
    html += '<p class="progression-msg">' + msg.replace(/\n/g, '<br>') + '</p>'
    var nts = nuevosTrofeos || []
    if (nts.length > 0) {
      html += '<div style="margin-top:12px"><h3 style="font-size:14px;font-weight:700;margin:0 0 6px;color:var(--text)">\ud83c\udfc6 Trofeos</h3>'
      nts.forEach(function(t) { html += '<p style="padding:2px 0;font-size:13px;color:var(--text)">' + t.competition + ' <span style="color:var(--text-muted)">(Temp. ' + t.season + ')</span></p>' })
      html += '</div>'
    }
    var lgs = logros || []
    if (lgs.length > 0) {
      html += '<div style="margin-top:12px"><h4 style="font-size:13px;font-weight:700;margin:0 0 4px;color:var(--text)">\ud83d\udcca Logros</h4>'
      lgs.forEach(function(l) { html += '<p style="padding:2px 0;font-size:13px;color:var(--text)">' + l + '</p>' })
      html += '</div>'
    }
      if (changes.length > 0) {
      html += '<h3 style="font-size:14px;font-weight:700;margin:16px 0 6px;color:var(--text)">Cambios de Valoraci\u00f3n</h3><div>'
      changes.sort(function(a, b) { return Math.abs(b.change) - Math.abs(a.change) })
      changes.forEach(function(c) {
        var arrow = c.change > 0 ? '\u25b2' : '\u25bc'
        var cls = c.change > 0 ? 'color:#22c55e' : 'color:#ef4444'
        html += '<div style="display:flex;align-items:center;gap:8px;padding:3px 0;font-size:13px"><span style="font-weight:600;color:var(--text);flex:1">' + c.name + '</span><span style="' + cls + ';font-weight:700">' + arrow + (c.change > 0 ? '+' : '') + c.change + '</span><span style="color:var(--text-muted)">' + c.oldSkill + '\u2192' + c.newSkill + '</span></div>'
      })
      html += '</div>'
    }
    if (valueChanges.length > 0) {
      html += '<h3 style="font-size:14px;font-weight:700;margin:12px 0 6px;color:var(--text)">\ud83d\udcb0 Cambios de Valor de Mercado</h3><div>'
      valueChanges.sort(function(a, b) { return Math.abs(b.change) - Math.abs(a.change) })
      valueChanges.forEach(function(v) {
        var arrow = v.change > 0 ? '\u25b2' : '\u25bc'
        var cls = v.change > 0 ? 'color:#22c55e' : 'color:#ef4444'
        var diffStr = formatMoney(Math.abs(v.change))
        html += '<div style="display:flex;align-items:center;gap:8px;padding:3px 0;font-size:13px"><span style="font-weight:600;color:var(--text);flex:1">' + v.name + '</span><span style="' + cls + ';font-weight:700">' + arrow + ' ' + diffStr + '</span><span style="color:var(--text-muted)">' + formatMoney(v.oldValue) + ' \u2192 ' + formatMoney(v.newValue) + '</span></div>'
      })
      html += '</div>'
    }
    if (retirados.length > 0) {
      html += '<div style="margin-top:12px"><h4 style="font-size:13px;font-weight:700;margin:0 0 4px;color:var(--text)">\ud83d\ude91 Retiradas</h4>'
      retirados.forEach(function(p) { html += '<p style="padding:2px 0;font-size:13px;color:var(--text)">' + p.name + ' (' + p.age + ' a\u00f1os) se retira tras ' + (p.matches || 0) + ' partidos esta temporada</p>' })
      html += '</div>'
    }
  } else if (activeTab === 'competiciones') {
    html += '<p style="font-size:12px;color:var(--text-muted);margin:0 0 12px">Campeones de cada competici\u00f3n esta temporada</p>'
    var winners = getSeasonWinners()
    html += buildCompetitionsHtml(winners)
  } else {
    html += buildMovementsHtml(movementsData)
  }
  content.innerHTML = html
  content.querySelectorAll('[data-spm-tab]').forEach(function(btn) {
    btn.addEventListener('click', function() { state._progTab = this.dataset.spmTab; showSeasonProgressionModal(result, msg, skipStandings, nuevosTrofeos, logros) })
  })
  modal.style.display = ''
  modal.classList.remove('hidden')
  modal.classList.add('open')
  var startBtn = document.getElementById('spm-btn-start')
  if (startBtn) startBtn.onclick = function() { modal.style.display = 'none'; modal.classList.remove('open'); modal.classList.add('hidden'); iniciarNuevaTemporada() }
}

function getCompStats(competition, limit, leagueId) {
  var stats = {}
  var counted = {}
  function addStats(player, teamName, teamLogo) {
    if (!player || counted[player.id]) return
    counted[player.id] = true
    var k = player.id
    if (!stats[k]) stats[k] = { name: player.name, team: teamName, teamLogo: teamLogo || '', position: player.position, avatar: player.avatar || '', nationality: player.nationality || '', goals: 0, assists: 0 }
    if (!player.matchHistory) return
    player.matchHistory.forEach(function(m) {
      var _c = m.comp || 'league'
      if (_c === competition) {
        stats[k].goals += m.goals || 0
        stats[k].assists += m.assists || 0
      }
    })
  }
  /* When a specific leagueId is requested, only include players of that league.
     Otherwise scan active country. */
  var activeCountry = state.leagueViewCountry || state.countryId || 'spain'
  var scanUserLeague = (!leagueId || leagueId === state.leagueId) && (activeCountry === state.countryId)
  if (scanUserLeague) {
    state.players.forEach(function(p) { addStats(p, state.team, state.teamLogo) })
    state.leagueTeams.forEach(function(t) {
      (t.players || []).forEach(function(p) { addStats(p, t.name, t.logo || '') })
    })
  }
  /* Persistent CPU squads for leagues of the viewed country live in allLeagueData. */
  for (var ci in window.DB) {
    if (activeCountry && ci !== activeCountry && !leagueId) continue
    var cd = window.DB[ci]
    if (!cd || !cd.country || !cd.country.leagues) continue
    for (var li = 0; li < cd.country.leagues.length; li++) {
      var lg = cd.country.leagues[li]
      if (leagueId && lg.id !== leagueId) continue
      var data = state.allLeagueData && state.allLeagueData[lg.id]
      if (!data || !data.teams) continue
      data.teams.forEach(function(t) {
        (t.players || []).forEach(function(p) { addStats(p, t.name, t.logo || '') })
      })
    }
  }
  var goals = Object.values(stats).filter(function(s) { return s.goals > 0 }).sort(function(a, b) { return b.goals - a.goals || (b.assists - a.assists) }).slice(0, limit || 10)
  var assists = Object.values(stats).filter(function(s) { return s.assists > 0 }).sort(function(a, b) { return b.assists - a.assists || (b.goals - a.goals) }).slice(0, limit || 10)
  return { goals: goals, assists: assists }
}

function _compStatCardPlayerHtml(s, isGoals) {
  var _pk = SIGLA_TO_POS[s.position] || s.position
  var _pc = POSITIONS[_pk]?.color || '#888'
  var _pa = POS_ABBR[_pk] || s.position
  var _flag = natFlagHtml(s.nationality)
  var _avatarSrc = s.avatar || NOPHOTO
  var _teamLogoSrc = s.teamLogo || NOPHOTO
  var _total = isGoals ? s.goals : s.assists
  var _icon = isGoals ? '\u26bd' : '\ud83d\udc5f'
  return '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:6px"><img src="' + _teamLogoSrc + '" style="width:28px;height:28px;border-radius:50%;object-fit:cover;background:var(--bg-card);border:1px solid var(--text-muted)" onerror="this.src=\'' + NOPHOTO + '\'"><img src="' + _avatarSrc + '" style="width:38px;height:38px;border-radius:50%;object-fit:cover;background:var(--bg-card);border:1px solid var(--text-muted);margin:0 auto" onerror="this.src=\'' + NOPHOTO + '\'"><span style="font-size:17px;font-weight:700;color:var(--accent);display:inline-flex;align-items:center;gap:2px">' + _icon + _total + '</span></div><div style="display:grid;grid-template-columns:28px 1fr 28px;align-items:center;gap:6px"><span style="font-size:28px;line-height:28px;display:inline-block;vertical-align:middle;width:28px;height:28px;text-align:center">' + _flag + '</span><span style="font-size:14px;font-weight:600;color:var(--text);text-align:center">' + s.name + '</span><span></span></div>'
}

/* Builds the "máximo goleador / asistente" cards for a competition or league.
   Stores the active competition so the top-10 modal reads the same data. */
function buildCompStatsCardsHtml(competition, leagueId) {
  window._activeStatsComp = { competition: competition, leagueId: leagueId || null }
  var compStats = getCompStats(competition, 10, leagueId)
  var statsHtml = '<div class="comp-stats-row">'
  if (compStats.goals.length > 0) {
    statsHtml += '<div class="comp-stat-card" id="stat-card-goals"><div class="comp-stat-label">\u26bd M\u00e1ximo goleador</div>' + _compStatCardPlayerHtml(compStats.goals[0], true) + '<div style="margin-top:4px;text-align:right"><span style="color:var(--accent);cursor:pointer;font-size:12px;font-weight:600" onclick="showTopStatsModal(\'goals\')">Ver top 10 \u2192</span></div></div>'
  } else {
    statsHtml += '<div class="comp-stat-card"><div class="comp-stat-label">\u26bd M\u00e1ximo goleador</div><div class="comp-stat-main" style="color:var(--text-muted);font-weight:400;text-align:center;padding:16px 0">\u2014 Sin datos \u2014</div></div>'
  }
  if (compStats.assists.length > 0) {
    statsHtml += '<div class="comp-stat-card" id="stat-card-assists"><div class="comp-stat-label">\ud83d\udc5f M\u00e1ximo asistente</div>' + _compStatCardPlayerHtml(compStats.assists[0], false) + '<div style="margin-top:4px;text-align:right"><span style="color:var(--accent);cursor:pointer;font-size:12px;font-weight:600" onclick="showTopStatsModal(\'assists\')">Ver top 10 \u2192</span></div></div>'
  } else {
    statsHtml += '<div class="comp-stat-card"><div class="comp-stat-label">\ud83d\udc5f M\u00e1ximo asistente</div><div class="comp-stat-main" style="color:var(--text-muted);font-weight:400;text-align:center;padding:16px 0">\u2014 Sin datos \u2014</div></div>'
  }
  statsHtml += '</div>'
  return statsHtml
}

function getSeasonWinners() {
  var winners = []
  /* Continentales */
  winners.push({ type: 'continental', competition: 'Champions League', winner: '—', logo: null })
  winners.push({ type: 'continental', competition: 'Europa League', winner: '—', logo: null })
  winners.push({ type: 'continental', competition: 'Conference League', winner: '—', logo: null })
  /* Nacionales */
  if (!window.DB[state.countryId]) return winners
  var leagues = window.DB[state.countryId].country.leagues
  if (!leagues) return winners
  for (var li = 0; li < leagues.length; li++) {
    var league = leagues[li]
    var data = state.allLeagueData[league.id]
    if (!data || !data.fixtures) continue
    var teamIds = league.teams.map(function(t) { return t.id })
    var standings = computeStandings(data.fixtures, teamIds)
    if (!standings || standings.length === 0) continue
    var champId = standings[0].teamId
    winners.push({ type: 'national', competition: getCanonicalLeagueName(league.id, league.name), winner: getTeamName(champId) || '—', logo: getTeamLogo(champId) })
  }
  /* Copa del Rey / Taça de Portugal */
  if (state.cupChampion) {
    var cupName = getCupCompName(state.countryId)
    winners.push({ type: 'national', competition: cupName, winner: getTeamName(state.cupChampion) || '—', logo: getTeamLogo(state.cupChampion) })
  }
  /* Supercopa */
  if (state.supercopa && state.supercopa.winner) {
    var scName = getSupercopaCompName(state.countryId)
    winners.push({ type: 'national', competition: scName, winner: getTeamName(state.supercopa.winner) || '—', logo: getTeamLogo(state.supercopa.winner) })
  }
  /* Taca da Liga (solo Portugal) */
  if (state.tacaDaLigaChampion) {
    winners.push({ type: 'national', competition: getTacaDaLigaCompName(), winner: getTeamName(state.tacaDaLigaChampion) || '—', logo: getTeamLogo(state.tacaDaLigaChampion) })
  }
  return winners
}

function buildCompetitionsHtml(winners) {
  if (!winners || winners.length === 0) return '<p style="font-size:12px;color:var(--text-muted)">Sin datos de competiciones</p>'
  var html = ''
  var conts = winners.filter(function(w) { return w.type === 'continental' })
  var nats = winners.filter(function(w) { return w.type === 'national' })
  if (conts.length > 0) {
    html += '<h3 style="font-size:13px;font-weight:700;margin:12px 0 6px;color:var(--text)">\ud83c\udf0d Continentales</h3>'
    conts.forEach(function(w) {
      html += '<div style="display:flex;align-items:center;gap:8px;padding:4px 0;font-size:13px;color:var(--text)"><span style="flex:1">' + w.competition + '</span><span style="font-weight:600">' + w.winner + '</span></div>'
    })
  }
  if (nats.length > 0) {
    var flag = ''
    if (window.DB[state.countryId]) flag = window.DB[state.countryId].country.flag || ''
    html += '<h3 style="font-size:13px;font-weight:700;margin:12px 0 6px;color:var(--text)">' + flag + ' Nacionales</h3>'
    nats.forEach(function(w) {
      html += '<div style="display:flex;align-items:center;gap:8px;padding:4px 0;font-size:13px;color:var(--text)"><span style="flex:1">' + w.competition + '</span>'
      if (w.logo) html += '<img src="' + w.logo + '" style="width:18px;height:18px;border-radius:50%;object-fit:contain" onerror="this.style.display=\'none\'">'
      html += '<span style="font-weight:600">' + w.winner + '</span></div>'
    })
  }
  return html
}

function buildMovementsHtml(movementsData) {
  if (!movementsData || !movementsData.divisions || !movementsData.divisions.length) return ''
  var html = '<p style="font-size:12px;color:var(--text-muted);margin:0 0 16px">Ascensos y descensos en todas las categor\u00edas</p>'
  for (var di = 0; di < movementsData.divisions.length; di++) {
    var div = movementsData.divisions[di]
    if (div.promoted.length === 0 && div.playoff.length === 0 && div.relegated.length === 0 && !div.crossPlayoff && !div.relegationPlayoff && !div.promotionPlayoff) continue
    var hasMovements = div.promoted.length > 0 || div.relegated.length > 0 || !!div.crossPlayoff || !!div.relegationPlayoff || !!div.promotionPlayoff
    if (!hasMovements && div.playoff.length === 0) continue
    html += '<div style="background:var(--bg-surface);border-radius:10px;padding:12px;margin-bottom:12px"><h3 style="font-size:14px;font-weight:700;margin:0 0 10px;color:var(--text)">' + div.name + '</h3>'
    if (div.promoted.length > 0) {
      html += '<div style="margin-bottom:8px"><div style="font-size:11px;font-weight:600;color:#22c55e;text-transform:uppercase;margin-bottom:4px">\u2b06 Ascienden</div>'
      for (var pi = 0; pi < div.promoted.length; pi++) {
        var t = div.promoted[pi]
        var viaLabel = t.via === 'playoff' ? ' (promoci\u00f3n)' : ''
        html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(t.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + t.name + viaLabel + '</span></div>'
      }
      html += '</div>'
    }
    if (div.playoff.length > 0) {
      html += '<div style="margin-bottom:8px"><div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">\ud83c\udfc6 Promoci\u00f3n</div>'
      for (var qi = 0; qi < div.playoff.length; qi++) {
        var q = div.playoff[qi]
        html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(q.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + q.name + ' (' + q.pos + '\u00ba)</span></div>'
      }
      html += '</div>'
    }
    if (div.relegated.length > 0) {
      html += '<div><div style="font-size:11px;font-weight:600;color:#ef4444;text-transform:uppercase;margin-bottom:4px">\u2b07 Descienden</div>'
      for (var ri = 0; ri < div.relegated.length; ri++) {
        var r = div.relegated[ri]
        html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(r.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + r.name + '</span></div>'
      }
      html += '</div>'
    }
    if (div.crossPlayoff) {
      var cp = div.crossPlayoff
      var isHigher = cp.verdict === 'saved' || cp.verdict === 'relegated'
      html += '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border)"><div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">' + (isHigher ? '\u2694 Playoff permanencia' : '\u2694 Playoff ascenso') + '</div>'
      html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(cp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + getTeamName(cp.teamId) + ' ' + cp.scoreTeam + ' - ' + cp.scoreOpponent + ' <img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(cp.opponentId) + '" onerror="this.style.display=\'none\'"> ' + cp.opponentName + '</span></div>'
      if (isHigher) {
        html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + (cp.verdict === 'saved' ? '\u2705 Se salva y permanece en ' + div.name : '\u274c Desciende a ' + cp.opponentLeagueName) + '</div>'
        html += '<div style="font-size:12px;color:var(--text-muted);padding-left:24px">' + (cp.verdict !== 'saved' ? '\u2705 ' + cp.opponentName + ' asciende a ' + div.name : '\u274c ' + cp.opponentName + ' sigue en ' + cp.opponentLeagueName) + '</div>'
      } else {
        html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + (cp.verdict === 'promoted' ? '\u2705 Asciende a ' + cp.opponentLeagueName : '\u274c Sigue en ' + div.name) + '</div>'
      }
      html += '</div>'
    }
    if (div.relegationPlayoff && div.relegationPlayoff.length > 0) {
      html += '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border)"><div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">\u2694 Promoci\u00f3n permanencia</div>'
      for (var rpi = 0; rpi < div.relegationPlayoff.length; rpi++) {
        var rp = div.relegationPlayoff[rpi]
        if (rp.opponentId) {
          html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(rp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + rp.name + ' (' + rp.pos + '\u00ba) ' + rp.teamScore + ' - ' + rp.opponentScore + ' <img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(rp.opponentId) + '" onerror="this.style.display=\'none\'"> ' + rp.opponentName + '</span></div>'
          html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + (rp.verdict === 'saved' ? '\u2705 Se salva y permanece en ' + div.name : '\u274c Desciende a ' + (rp.opponentLeague || 'divisi\u00f3n inferior')) + '</div>'
          html += '<div style="font-size:12px;color:var(--text-muted);padding-left:24px">' + (rp.verdict === 'saved' ? '\u274c ' + rp.opponentName + ' no asciende' : '\u2705 ' + rp.opponentName + ' asciende a ' + div.name) + '</div>'
        } else {
          html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(rp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + rp.name + ' (' + rp.pos + '\u00ba)</span></div>'
        }
      }
      html += '</div>'
    }
    if (div.promotionPlayoff) {
      var pp = div.promotionPlayoff
      html += '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border)"><div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">\u2694 Promoci\u00f3n ascenso</div>'
      html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(pp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + pp.teamName
      if (pp.intergroup) {
        var ig = pp.intergroup
        html += ' ' + ig.teamScore + ' - ' + ig.opponentScore + ' <img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(ig.opponentId) + '" onerror="this.style.display=\'none\'"> ' + ig.opponentName + '</span></div>'
        html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + (ig.won ? '\u2705 Gana la semifinal intergrupos' : '\u274c Pierde la semifinal intergrupos - sigue en ' + div.name) + '</div>'
        if (pp.crossFinal) {
          var cf = pp.crossFinal
          html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text);padding-left:24px"><span>Final vs ' + cf.opponentName + ': ' + pp.teamName + ' ' + cf.teamScore + ' - ' + cf.opponentScore + ' ' + cf.opponentName + '</span></div>'
          html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + (cf.verdict === 'promoted' ? '\u2705 Asciende a ' + cf.opponentLeague : '\u274c Sigue en ' + div.name) + '</div>'
        }
      } else {
        html += '</span></div>'
      }
      html += '</div>'
    }
    html += '</div>'
  }
  return html
}

function showSeasonEndFallback() {
  var modal = document.getElementById('season-end-modal')
  if (!modal) return
  modal.style.display = ''
  modal.classList.remove('hidden')
  modal.classList.add('open')
  var summaryBtn = document.getElementById('sem-btn-summary')
  var advanceBtn = document.getElementById('sem-btn-advance')
  if (summaryBtn) summaryBtn.onclick = function() {
    modal.style.display = 'none'
    modal.classList.remove('open')
    modal.classList.add('hidden')
    if (state.lastSeasonProgressionData) {
      var d = state.lastSeasonProgressionData
      showSeasonProgressionModal(d.result, d.msg, d.skipStandings, d.nuevosTrofeos, d.logros)
    } else {
      showSeasonProgressionModal({ changes: [], retirados: [] }, 'Temporada finalizada', true, [], [])
    }
  }
  if (advanceBtn) advanceBtn.onclick = function() {
    modal.style.display = 'none'
    modal.classList.remove('open')
    modal.classList.add('hidden')
    if (state.lastSeasonProgressionData) {
      iniciarNuevaTemporada()
    } else {
      state.lastSeasonProgressionData = { result: { changes: [], retirados: [] }, msg: 'Nueva temporada', skipStandings: true, nuevosTrofeos: [], logros: [] }
      iniciarNuevaTemporada()
    }
  }
}

function renderProgression() {
  var container = document.getElementById('progression-content')
  if (!container) return
  var data = state.lastSeasonProgressionData
  if (!data) { container.innerHTML = ''; return }

  var changes = data.result.changes || []
  var retirados = data.result.retirados || []
  var nuevosTrofeos = data.nuevosTrofeos || []
  var logros = data.logros || []
  var msg = data.msg
  var skipStandings = data.skipStandings
  var movementsData = state.lastSeasonMovements
  var activeTab = state._progTab || 'progresion'

  var html = '<div style="padding:12px 14px">'
  html += '<h2 style="font-size:16px;font-weight:700;margin:0 0 8px;color:var(--text)">Fin de Temporada</h2>'

  /* Sub-tab navigation */
  html += '<div style="display:flex;gap:8px;margin-bottom:12px;border-bottom:1px solid var(--border);padding-bottom:8px">'
  html += '<button class="sub-tab' + (activeTab === 'progresion' ? ' active' : '') + '" data-prog-tab="progresion">Progresi\u00f3n</button>'
  if (movementsData) {
    html += '<button class="sub-tab' + (activeTab === 'movimientos' ? ' active' : '') + '" data-prog-tab="movimientos">Movimientos</button>'
  }
  html += '</div>'

  if (activeTab === 'progresion') {
    html += '<p class="progression-msg">' + msg.replace(/\n/g, '<br>') + '</p>'

    if (nuevosTrofeos.length > 0) {
      html += '<div style="margin-top:12px">'
      html += '<h3 style="font-size:14px;font-weight:700;margin:0 0 6px;color:var(--text)">\ud83c\udfc6 Trofeos</h3>'
      nuevosTrofeos.forEach(function(t) {
        html += '<p style="padding:2px 0;font-size:13px;color:var(--text)">' + t.competition + ' <span style="color:var(--text-muted)">(Temp. ' + t.season + ')</span></p>'
      })
      html += '</div>'
    }

    if (logros.length > 0) {
      html += '<div style="margin-top:12px">'
      html += '<h4 style="font-size:13px;font-weight:700;margin:0 0 4px;color:var(--text)">\ud83d\udcca Logros</h4>'
      logros.forEach(function(l) {
        html += '<p style="padding:2px 0;font-size:13px;color:var(--text)">' + l + '</p>'
      })
      html += '</div>'
    }

    if (changes.length > 0) {
      html += '<h3 style="font-size:14px;font-weight:700;margin:16px 0 6px;color:var(--text)">Cambios de Valoraci\u00f3n</h3>'
      html += '<div>'
      changes.sort(function(a, b) { return Math.abs(b.change) - Math.abs(a.change) })
      changes.forEach(function(c) {
        var arrow = c.change > 0 ? '\u25b2' : '\u25bc'
        var cls = c.change > 0 ? 'color:#22c55e' : 'color:#ef4444'
        html += '<div style="display:flex;align-items:center;gap:8px;padding:3px 0;font-size:13px">'
        html += '<span style="font-weight:600;color:var(--text);flex:1">' + c.name + '</span>'
        html += '<span style="' + cls + ';font-weight:700">' + arrow + (c.change > 0 ? '+' : '') + c.change + '</span>'
        html += '<span style="color:var(--text-muted)">' + c.oldSkill + '\u2192' + c.newSkill + '</span>'
        html += '</div>'
      })
      html += '</div>'
    }

    if (retirados.length > 0) {
      html += '<div style="margin-top:12px">'
      html += '<h4 style="font-size:13px;font-weight:700;margin:0 0 4px;color:var(--text)">\ud83d\ude91 Retiradas</h4>'
      retirados.forEach(function(p) {
        html += '<p style="padding:2px 0;font-size:13px;color:var(--text)">' + p.name + ' (' + p.age + ' a\u00f1os) se retira tras ' + (p.matches || 0) + ' partidos esta temporada</p>'
      })
      html += '</div>'
    }
  } else {
    /* MOVIMIENTOS TAB */
    if (movementsData && movementsData.divisions && movementsData.divisions.length > 0) {
      html += '<p style="font-size:12px;color:var(--text-muted);margin:0 0 16px">Ascensos y descensos en todas las categor\u00edas</p>'
      for (var di = 0; di < movementsData.divisions.length; di++) {
        var div = movementsData.divisions[di]
        if (div.promoted.length === 0 && div.playoff.length === 0 && div.relegated.length === 0 && !div.crossPlayoff && !div.relegationPlayoff && !div.promotionPlayoff) continue
        var hasMovements = div.promoted.length > 0 || div.relegated.length > 0 || !!div.crossPlayoff || !!div.relegationPlayoff || !!div.promotionPlayoff
        if (!hasMovements && div.playoff.length === 0) continue
        html += '<div style="background:var(--bg-surface);border-radius:10px;padding:12px;margin-bottom:12px">'
        html += '<h3 style="font-size:14px;font-weight:700;margin:0 0 10px;color:var(--text)">' + div.name + '</h3>'
        if (div.promoted.length > 0) {
          html += '<div style="margin-bottom:8px">'
          html += '<div style="font-size:11px;font-weight:600;color:#22c55e;text-transform:uppercase;margin-bottom:4px">\u2b06 Ascienden</div>'
          for (var pi = 0; pi < div.promoted.length; pi++) {
            var t = div.promoted[pi]
            var viaLabel = t.via === 'playoff' ? ' (promoci\u00f3n)' : ''
            html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(t.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + t.name + viaLabel + '</span></div>'
          }
          html += '</div>'
        }
        if (div.playoff.length > 0) {
          html += '<div style="margin-bottom:8px">'
          html += '<div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">\ud83c\udfc6 Promoci\u00f3n</div>'
          for (var qi = 0; qi < div.playoff.length; qi++) {
            var q = div.playoff[qi]
            html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(q.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + q.name + ' (' + q.pos + '\u00ba)</span></div>'
          }
          html += '</div>'
        }
        if (div.relegated.length > 0) {
          html += '<div>'
          html += '<div style="font-size:11px;font-weight:600;color:#ef4444;text-transform:uppercase;margin-bottom:4px">\u2b07 Descienden</div>'
          for (var ri = 0; ri < div.relegated.length; ri++) {
            var r = div.relegated[ri]
            html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(r.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + r.name + '</span></div>'
          }
          html += '</div>'
        }
        if (div.crossPlayoff) {
          var cp = div.crossPlayoff
          var isHigher = cp.verdict === 'saved' || cp.verdict === 'relegated'
          html += '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border)">'
          html += '<div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">' + (isHigher ? '\u2694 Playoff permanencia' : '\u2694 Playoff ascenso') + '</div>'
          html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(cp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + getTeamName(cp.teamId) + ' ' + cp.scoreTeam + ' - ' + cp.scoreOpponent + ' <img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(cp.opponentId) + '" onerror="this.style.display=\'none\'"> ' + cp.opponentName + '</span></div>'
          if (isHigher) {
            var savedText = cp.verdict === 'saved' ? '\u2705 Se salva y permanece en ' + div.name : '\u274c Desciende a ' + cp.opponentLeagueName
            html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + savedText + '</div>'
            html += '<div style="font-size:12px;color:var(--text-muted);padding-left:24px">' + (cp.verdict !== 'saved' ? '\u2705 ' + cp.opponentName + ' asciende a ' + div.name : '\u274c ' + cp.opponentName + ' sigue en ' + cp.opponentLeagueName) + '</div>'
          } else {
            var promotedText = cp.verdict === 'promoted' ? '\u2705 Asciende a ' + cp.opponentLeagueName : '\u274c Sigue en ' + div.name
            html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + promotedText + '</div>'
          }
          html += '</div>'
        }
        if (div.relegationPlayoff && div.relegationPlayoff.length > 0) {
          html += '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border)">'
          html += '<div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">\u2694 Promoci\u00f3n permanencia</div>'
          for (var rpi = 0; rpi < div.relegationPlayoff.length; rpi++) {
            var rp = div.relegationPlayoff[rpi]
            if (rp.opponentId) {
              html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(rp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + rp.name + ' (' + rp.pos + '\u00ba) ' + rp.teamScore + ' - ' + rp.opponentScore + ' <img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(rp.opponentId) + '" onerror="this.style.display=\'none\'"> ' + rp.opponentName + '</span></div>'
              var rpVerdict = rp.verdict === 'saved' ? '\u2705 Se salva y permanece en ' + div.name : '\u274c Desciende a ' + (rp.opponentLeague || 'divisi\u00f3n inferior')
              html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + rpVerdict + '</div>'
              html += '<div style="font-size:12px;color:var(--text-muted);padding-left:24px">' + (rp.verdict === 'saved' ? '\u274c ' + rp.opponentName + ' no asciende' : '\u2705 ' + rp.opponentName + ' asciende a ' + div.name) + '</div>'
    } else if (displayLid === 'sb') {
      if (i < 2) barClass = 'bar-promotion'
      else if (i < 8) barClass = 'bar-promotion-playoff'
      else if (i >= totalTeams - 5 && i < totalTeams - 3) barClass = 'bar-relegation-playoff'
      else if (i >= totalTeams - 3) barClass = 'bar-descenso'
    } else {
              html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(rp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + rp.name + ' (' + rp.pos + '\u00ba)</span></div>'
            }
          }
          html += '</div>'
        }
        if (div.promotionPlayoff) {
          var pp = div.promotionPlayoff
          html += '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border)">'
          html += '<div style="font-size:11px;font-weight:600;color:#f59e0b;text-transform:uppercase;margin-bottom:4px">\u2694 Promoci\u00f3n ascenso</div>'
          html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text)"><img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(pp.teamId) + '" onerror="this.style.display=\'none\'"> <span>' + pp.teamName
          if (pp.intergroup) {
            var ig = pp.intergroup
            html += ' ' + ig.teamScore + ' - ' + ig.opponentScore + ' <img style="width:18px;height:18px;border-radius:50%;object-fit:contain" src="' + getTeamLogo(ig.opponentId) + '" onerror="this.style.display=\'none\'"> ' + ig.opponentName + '</span></div>'
            html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + (ig.won ? '\u2705 Gana la semifinal intergrupos' : '\u274c Pierde la semifinal intergrupos - sigue en ' + div.name) + '</div>'
            if (pp.crossFinal) {
              var cf = pp.crossFinal
              html += '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;font-size:13px;color:var(--text);padding-left:24px"><span>Final vs ' + cf.opponentName + ': ' + pp.teamName + ' ' + cf.teamScore + ' - ' + cf.opponentScore + ' ' + cf.opponentName + '</span></div>'
              html += '<div style="font-size:12px;color:var(--text-muted);margin-top:2px;padding-left:24px">' + (cf.verdict === 'promoted' ? '\u2705 Asciende a ' + cf.opponentLeague : '\u274c Sigue en ' + div.name) + '</div>'
            }
          } else {
            html += '</span></div>'
          }
          html += '</div>'
        }
        html += '</div>'
      }
    }
  }

  html += '<button id="btn-next-season" class="btn-primary" style="margin-top:16px;width:100%">COMENZAR SIGUIENTE TEMPORADA</button>'
  html += '</div>'
  container.innerHTML = html

  /* Sub-tab switching */
  container.querySelectorAll('[data-prog-tab]').forEach(function(btn) {
    btn.addEventListener('click', function() {
      state._progTab = this.dataset.progTab
      renderProgression()
    })
  })

  document.getElementById('btn-next-season').addEventListener('click', function() {
    iniciarNuevaTemporada()
  })
}

function divName(leagueId) {
  if (leagueId.startsWith('l3c')) return '3a Divisió Catalana'
  if (leagueId.startsWith('l2c')) return '2a Divisió Catalana'
  if (leagueId.startsWith('lc')) return '1a Divisió Catalana'
  if (leagueId.startsWith('lhc')) return 'Divisió d\'Honor Catalana'
  if (leagueId.startsWith('l3g')) return '3ª División Nacional'
  if (leagueId.startsWith('l2b')) return '2ª División B'
  if (leagueId === 'lnfs2') return 'Segunda División'
  if (leagueId === 'lnfs1') return 'Primera División'
  if (leagueId === 'lpl') return 'Liga Polaca'
  if (leagueId === 'lpl2') return 'Segunda Polaca'
  if (leagueId === 'lpl3') return 'Tercera Polaca'
  if (leagueId.startsWith('lpl4g')) return 'Cuarta Polaca'
  if (leagueId.startsWith('l3sg')) return 'Primera Federaci\u00f3n'
  return 'la categoría'
}

function procesarFinTemporada(skipAging, skipStandings, extraMsg) {
  state.lastFinalStandings = updateLeagueStandings()
  /* Bonus de patrocinios por objetivos cumplidos (Top 8, Europa, Copa...). */
  try { procesarBonusPatrocinioFinTemporada() } catch (e) { console.warn('[SPONSOR] Error bonus fin temporada:', e) }
  /* Auto-simulate remaining cup/taca rounds if user eliminated */
  try {
    if (state.cup && state.cup.roundIdx >= 0) {
      var userInCup = state.cup.allFixtures && state.cup.allFixtures.some(function(f) { return !f.played && (f.home === state.teamId || f.away === state.teamId) })
      if (!userInCup) autoSimularCopaRestante()
    }
  } catch(e) { console.warn('[SEASON] autoSimularCopaRestante error:', e) }
  try {
    if (state.tacaDaLiga && !state.tacaDaLigaChampion) {
      var userInTaca = state.tacaDaLiga.fixtures && state.tacaDaLiga.fixtures.some(function(f) { return !f.played && (f.home === state.teamId || f.away === state.teamId) })
      if (!userInTaca) autoSimularTacaDaLigaRestante()
    }
  } catch(e) { console.warn('[SEASON] autoSimularTacaDaLigaRestante error:', e) }
  if (!skipAging) var agingResult = envejecerYProgresar()
  let cambioDivision = false
  let pos = 0
  let esPrimera = false, esSegunda = false, esSegundaB = false, esTercera = false, esHonor = false, esPrimeraCat = false, esSegonaCat = false, esTerceraCat = false
  let esPolaca1 = false, esPolaca2 = false, esPolaca3 = false, esPolaca4 = false
  let esPrimeraPortugal = false, esSegundaPortugal = false
  let esBundesliga = false, esBundesliga2 = false
  let esBundesligaA = false, esSegundaAustria = false
  let esAscensoFilialBloqueado = false, esDescensoRegional = false
  let esPlayoffTercera = false, esPlayoffPolaca2 = false, esPlayoffPolaca3 = false, esPlayoffDescensoLP3 = false, esPlayoffAscensoLP4 = false
  let esPlayoffSegundaSpain = false
  let esPlayoffTerceraRFEF = false
  let esPlayoffAscensoPortugal = false, esPlayoffDescensoPortugal = false
  let msg = ''

  if (!skipStandings) {
    const standings = updateLeagueStandings()
    pos = standings.findIndex(s => s.teamId === state.teamId) + 1
    state.oldLeagueId = state.leagueId
    esPrimera = state.leagueId === 'lnfs1'
    esPrimeraSpain = state.leagueId === 'l1s'
    esSegunda = state.leagueId === 'lnfs2'
    esSegundaB = state.leagueId && state.leagueId.startsWith('l2b')
    esTercera = state.leagueId && state.leagueId.startsWith('l3g')
    esHonor = state.leagueId && state.leagueId.startsWith('lhc')
    esPrimeraCat = state.leagueId && state.leagueId.startsWith('lc')
    esSegonaCat = state.leagueId && state.leagueId.startsWith('l2c')
    esTerceraCat = state.leagueId && state.leagueId.startsWith('l3c')
    esPolaca1 = state.leagueId === 'lpl'
    esPolaca2 = state.leagueId === 'lpl2'
    esPolaca3 = state.leagueId === 'lpl3'
    esPolaca4 = state.leagueId && state.leagueId.startsWith('lpl4g')
    var esTerceraRFEF = state.leagueId && state.leagueId.startsWith('l3sg')
    esPrimeraSpain = state.leagueId === 'l1s'
    esPrimeraPortugal = state.leagueId === 'l1p'
    esSegundaPortugal = state.leagueId === 'l2p'
    esSegundaSpain = state.leagueId === 'l2s'
    esPrimeraFrance = state.leagueId === 'l1fr'
    esSegundaFrance = state.leagueId === 'l2fr'
    esSerieAItaly = state.leagueId === 'sa'
    esSerieBItaly = state.leagueId === 'sb'
    esBundesliga = state.leagueId === 'bl'
    esBundesliga2 = state.leagueId === 'bl2'
    esBundesligaA = state.leagueId === 'bl1'
    esSegundaAustria = state.leagueId === 'bl2a'

    const esTerceraCatalana = state.leagueId === 'l3g1' || state.leagueId === 'l3g2'
    const totalTeams = standings.length

    if (esPrimeraSpain && pos >= 18) {
      var filialId = findBTeamOf(state.teamId)
      var filialInL2s = filialId && getLeagueTeams('l2s').some(function(t) { return t.id === filialId })
      if (filialInL2s) state._filialRelegue = filialId
      state.leagueId = 'l2s'
      cambioDivision = true
    } else if (esBundesligaA && pos >= 12) {
      /* Bundesliga austriaca (12 equipos): el 12º desciende a 2ª */
      var _filialA = findBTeamOf(state.teamId)
      var filialInBl2 = _filialA && getLeagueTeams('bl2a').some(function(t) { return t.id === _filialA })
      if (filialInBl2) state._filialRelegue = _filialA
      state.leagueId = 'bl2a'
      cambioDivision = true
    } else if (esSegundaAustria && pos === 1) {
      /* 2ª austriaca: el 1º asciende salvo que sea filial cuyo padre juega en 1ª */
      var _parentA = getBTeamParent(state.teamId)
      if (_parentA && getLeagueTeams('bl1').some(function(t) { return t.id === _parentA })) {
        esAscensoFilialBloqueado = true
      } else {
        state.leagueId = 'bl1'
        cambioDivision = true
      }
    } else if (esSegundaAustria && pos >= 15) {
      /* 15º y 16º descenderían a Liga Regional, que aún no existe:
         de momento permanecen en 2ª */
      esDescensoRegional = true
    } else if (esBundesliga && pos >= 17) {
      if (getLeagueTeams('bl2')) {
        state.leagueId = 'bl2'
        cambioDivision = true
      }
    } else if (esBundesliga2 && pos <= 2) {
      state.leagueId = 'bl'
      cambioDivision = true
    } else if (esPrimeraFrance && pos >= 17) {
      if (getLeagueTeams('l2fr')) {
        state.leagueId = 'l2fr'
        cambioDivision = true
      }
    } else if (esSerieAItaly && pos >= 18) {
      if (getLeagueTeams('sb')) {
        state.leagueId = 'sb'
        cambioDivision = true
      }
    } else if (esSerieBItaly && pos <= 2) {
      state.leagueId = 'sa'
      cambioDivision = true
    } else if (esPrimera && pos >= 15) {
      state.leagueId = 'lnfs2'
      cambioDivision = true
    } else if (esSegunda && pos <= 2) {
      state.leagueId = 'lnfs1'
      cambioDivision = true
    } else if (esSegunda && pos >= 15) {
      const gruposB = ['l2b1','l2b2','l2b3','l2b4','l2b5','l2b6']
      state.leagueId = pickRandom(gruposB)
      cambioDivision = true
    } else if (esSegundaB && pos <= 2) {
      state.leagueId = 'lnfs2'
      cambioDivision = true
    } else if (esSegundaB && pos >= 15) {
      const gruposT = getTerceraGroupIds()
      state.leagueId = pickRandom(gruposT)
      cambioDivision = true
    } else if (esTercera && pos === 1) {
      esPlayoffTercera = true
    } else if (esTercera && esTerceraCatalana && pos >= totalTeams - 2) {
      const gruposH = ['lhc1','lhc2','lhc3']
      state.leagueId = pickRandom(gruposH)
      cambioDivision = true
    } else if (esHonor && pos <= 2) {
      state.leagueId = Math.random() < 0.5 ? 'l3g1' : 'l3g2'
      cambioDivision = true
    } else if (esHonor && pos >= totalTeams - 1) {
      const grupos1a = ['lc1','lc2','lc3','lc4','lc5','lc6','lc7']
      state.leagueId = pickRandom(grupos1a)
      cambioDivision = true
    } else if (esPrimeraCat && pos <= 2) {
      state.leagueId = pickRandom(['lhc1','lhc2','lhc3'])
      cambioDivision = true
    } else if (esPrimeraCat && pos >= totalTeams - 1) {
      const grupos2a = ['l2c1','l2c2','l2c3','l2c4','l2c5','l2c6','l2c7','l2c9','l2c11','l2c12','l2c13','l2c14']
      state.leagueId = pickRandom(grupos2a)
      cambioDivision = true
    } else if (esSegonaCat && pos <= 2) {
      state.leagueId = pickRandom(['lc1','lc2','lc3','lc4','lc5','lc6','lc7'])
      cambioDivision = true
    } else if (esSegonaCat && pos >= totalTeams - 1) {
      const grupos3a = ['l3c1','l3c2','l3c3','l3c4','l3c5','l3c6','l3c7','l3c8','l3c9','l3c10',
                        'l3c11','l3c12','l3c13','l3c14','l3c15','l3c16','l3c17','l3c18','l3c19','l3c20']
      state.leagueId = pickRandom(grupos3a)
      cambioDivision = true
    } else if (esTerceraCat && pos <= 2) {
      const grupos2a = ['l2c1','l2c2','l2c3','l2c4','l2c5','l2c6','l2c7','l2c9','l2c11','l2c12','l2c13','l2c14']
      state.leagueId = pickRandom(grupos2a)
      cambioDivision = true
    } else if (esPolaca1 && pos >= 15) {
      var _filialId = findBTeamOf(state.teamId)
      var filialInLpl2 = _filialId && getLeagueTeams('lpl2').some(function(t) { return t.id === _filialId })
      if (filialInLpl2) state._filialRelegue = _filialId
      state.leagueId = 'lpl2'
      cambioDivision = true
    } else if (esPolaca2 && pos <= 2) {
      var _parentId = getBTeamParent(state.teamId)
      if (_parentId && getLeagueTeams('lpl').some(function(t) { return t.id === _parentId })) {
        msg = '\uD83C\uDFF4 El filial no puede ascender. El primer equipo ya est\u00e1 en Liga Polaca.'
      } else {
        state.leagueId = 'lpl'
        cambioDivision = true
      }
    } else if (esPolaca2 && pos >= 3 && pos <= 6) {
      esPlayoffPolaca2 = true
    } else if (esPolaca2 && pos >= 16) {
      state.leagueId = 'lpl3'
      cambioDivision = true
    } else if (esPolaca3 && pos <= 2) {
      state.leagueId = 'lpl2'
      cambioDivision = true
    } else if (esPolaca3 && pos >= 3 && pos <= 6) {
      esPlayoffPolaca3 = true
    } else if (esPolaca3 && pos >= 13 && pos <= 14) {
      esPlayoffDescensoLP3 = true
    } else if (esPolaca3 && pos >= 16) {
      const grupos4 = ['lpl4g1','lpl4g2','lpl4g3','lpl4g4']
      state.leagueId = pickRandom(grupos4)
      cambioDivision = true
    } else if (esPolaca4 && pos === 1) {
      state.leagueId = 'lpl3'
      cambioDivision = true
    } else if (esPolaca4 && pos === 2) {
      esPlayoffAscensoLP4 = true
    } else if (esSegundaSpain && pos <= 2) {
      var _p = getBTeamParent(state.teamId)
      if (_p && getLeagueTeams('l1s').some(function(t) { return t.id === _p })) {
        msg = '\uD83C\uDFF4 El filial no puede ascender a LaLiga. El primer equipo ya est\u00e1 en Primera.'
      } else {
        state.leagueId = 'l1s'
        cambioDivision = true
      }
    } else if (esSegundaSpain && pos >= 3 && pos <= 6) {
      esPlayoffSegundaSpain = true
    } else if (esSegundaSpain && pos >= 19) {
      state.leagueId = 'l2b1'
      cambioDivision = true
    } else if (esPrimeraPortugal && pos >= 17) {
      var _f = findBTeamOf(state.teamId)
      if (_f && getLeagueTeams('l2p').some(function(t) { return t.id === _f })) state._filialRelegue = _f
      state.leagueId = 'l2p'
      cambioDivision = true
    } else if (esPrimeraPortugal && pos === 16) {
      esPlayoffDescensoPortugal = true
    } else if (esSegundaPortugal && pos <= 2) {
      var _p2 = getBTeamParent(state.teamId)
      if (_p2 && getLeagueTeams('l1p').some(function(t) { return t.id === _p2 })) {
        msg = '\uD83C\uDFF4 El filial no puede ascender. El primer equipo ya est\u00e1 en Primeira Liga.'
      } else {
        state.leagueId = 'l1p'
        cambioDivision = true
      }
    } else if (esSegundaPortugal && pos === 3) {
      esPlayoffAscensoPortugal = true
    } else if (esSegundaFrance && pos <= 2) {
      if (getLeagueTeams('l1fr')) {
        state.leagueId = 'l1fr'
        cambioDivision = true
      }
    } else if (esTerceraRFEF && pos === 1) {
      state.leagueId = 'l2s'
      cambioDivision = true
    } else if (esTerceraRFEF && pos >= 2 && pos <= 5) {
      esPlayoffTerceraRFEF = true
    } else if (esTerceraRFEF && pos >= 17) {
      if (leagueExists('l2b1')) {
        state.leagueId = 'l2b1'
        cambioDivision = true
      }
    }

    var noLowerDivision = false
    if (cambioDivision && state.leagueId && !leagueExists(state.leagueId)) {
      cambioDivision = false
      state.leagueId = state.oldLeagueId || state.leagueId
      noLowerDivision = true
    }

    msg = `📊 Temporada finalizada. Posición: ${pos}º`
    var divName = getTeamLeagueName(state.teamId) || state.leagueId
    registrarPosicionTemporada(pos, divName)
    if (esPlayoffSegundaSpain) msg += '\n🏆 Accedes a la Fase de Ascenso a LaLiga'
    else if (cambioDivision && esSegundaSpain && pos <= 2) msg += '\n🎉 ¡ASCENSO a LaLiga!'
    else if (cambioDivision && esSegundaSpain) msg += '\n⚠️ DESCENSO a Primera Federación'
    else if (cambioDivision && esPrimera) msg += '\n⚠️ DESCENSO a Segunda División'
    else if (cambioDivision && esSegunda && pos >= 15) msg += '\n⚠️ DESCENSO a 2ª División B'
    else if (cambioDivision && esSegunda) msg += '\n🎉 ¡ASCENSO a Primera División!'
    else if (cambioDivision && esSegundaB && pos <= 2) msg += '\n🎉 ¡ASCENSO a Segunda División!'
    else if (cambioDivision && esSegundaB) msg += '\n⚠️ DESCENSO a 3ª División Nacional'
    else if (esPlayoffTercera) msg += '\n🏆 ¡CAMPEÓN DE GRUPO! Accedes a la Fase de Ascenso'
    else if (cambioDivision && esTercera) msg += '\n⚠️ DESCENSO a Divisió d\'Honor Catalana'
    else if (cambioDivision && esHonor && pos <= 2) msg += '\n🎉 ¡ASCENSO a 3ª División Nacional!'
    else if (cambioDivision && esHonor) msg += '\n⚠️ DESCENSO a 1a Divisió Catalana'
    else if (cambioDivision && esPrimeraCat && pos <= 2) msg += '\n🎉 ¡ASCENSO a Divisió d\'Honor Catalana!'
    else if (cambioDivision && esPrimeraCat) msg += '\n⚠️ DESCENSO a 2a Divisió Catalana'
    else if (cambioDivision && esSegonaCat && pos <= 2) msg += '\n🎉 ¡ASCENSO a 1a Divisió Catalana!'
    else if (cambioDivision && esSegonaCat) msg += '\n⚠️ DESCENSO a 3a Divisió Catalana'
    else if (cambioDivision && esTerceraCat) msg += '\n🎉 ¡ASCENSO a 2a Divisió Catalana!'
    else if (cambioDivision && esPolaca1) {
      msg += '\n⚠️ DESCENSO a Segunda Polaca'
      if (state._filialRelegue) msg += '\n⚠️ Tu filial desciende automáticamente a Tercera Polaca.'
    }
    else if (cambioDivision && esPolaca2 && pos <= 2) msg += '\n🎉 ¡ASCENSO a Liga Polaca!'
    else if (cambioDivision && esPolaca2) msg += '\n⚠️ DESCENSO a Tercera Polaca'
    else if (esPlayoffPolaca2) msg += '\n🏆 Accedes a la Fase de Ascenso a Liga Polaca'
    else if (cambioDivision && esPolaca3 && pos <= 2) msg += '\n🎉 ¡ASCENSO a Segunda Polaca!'
    else if (cambioDivision && esPolaca3) msg += '\n⚠️ DESCENSO a Cuarta Polaca'
    else if (esPlayoffPolaca3) msg += '\n🏆 Accedes a la Fase de Ascenso a Segunda Polaca'
    else if (esPlayoffDescensoLP3) msg += '\n⚠️ Playoff de Descenso — te la juegas por la permanencia'
    else if (cambioDivision && esPolaca4) msg += '\n🎉 ¡ASCENSO a Tercera Polaca!'
    else if (esPlayoffAscensoLP4) msg += '\n🏆 Accedes a la Fase de Ascenso a Tercera Polaca'
    else if (cambioDivision && esPrimeraPortugal) {
      msg += '\n⚠️ DESCENSO a Segunda Liga Portugal'
      if (state._filialRelegue) msg += '\n⚠️ Tu filial desciende automáticamente a la siguiente categoría.'
    }
    else if (esSegundaPortugal && pos <= 2 && !cambioDivision && getBTeamParent(state.teamId) && getLeagueTeams('l1p').some(t => t.id === getBTeamParent(state.teamId))) {
      /* promotion blocked — msg already set */
    } else if (cambioDivision && esSegundaPortugal) msg += '\n🎉 ¡ASCENSO a Liga Portugal Betclic!'
    else if (esPlayoffAscensoPortugal) msg += '\n🏆 Accedes al Playoff de Ascenso a Primeira Liga'
    else if (esPlayoffDescensoPortugal) msg += '\n⚠️ Playoff de Descenso — te la juegas por la permanencia en Primeira Liga'
    else if (esTercera) msg += '\nPermanencia en 3ª División Nacional'
    else if (esSegundaB) msg += '\nPermanencia en 2ª División B'
    else if (esHonor) msg += '\nPermanencia en Divisió d\'Honor Catalana'
    else if (esPrimeraCat) msg += '\nPermanencia en 1a Divisió Catalana'
    else if (esSegonaCat) msg += '\nPermanencia en 2a Divisió Catalana'
    else if (esTerceraCat) msg += '\nPermanencia en 3a Divisió Catalana'
    else if (esPolaca1) msg += '\nPermanencia en Liga Polaca'
    else if (esPolaca2) msg += '\nPermanencia en Segunda Polaca'
    else if (esPolaca3) msg += '\nPermanencia en Tercera Polaca'
    else if (esPolaca4) msg += '\nPermanencia en Cuarta Polaca'
    else if (esPrimeraPortugal) msg += '\nPermanencia en Primeira Liga'
    else if (esSegundaPortugal) msg += '\nPermanencia en Segunda Liga Portugal'
    else if (esPrimeraSpain && pos === 1) msg += '\n🏆 ¡CAMPEÓN DE LA LIGA!'
    else if (esPrimeraSpain && pos <= 4) msg += '\n✅ Clasificado a Champions League'
    else if (esPrimeraSpain && pos === 5) msg += '\n✅ Clasificado a Europa League'
    else if (esPrimeraSpain && pos === 6) msg += '\n✅ Clasificado a Conference League'
    else if (esPrimeraSpain && pos >= 18) {
      msg += '\n⚠️ DESCENSO a Segunda División'
      if (state._filialRelegue) msg += '\n⚠️ Tu filial desciende automáticamente a 1ª Federación.'
    }
    else if (esPrimeraSpain) msg += '\nPermanencia en Primera División'
    else if (esPrimeraFrance && pos === 1) msg += '\n🏆 ¡CAMPEÓN DE LA LIGUE 1!'
    else if (esPrimeraFrance && pos <= 4) msg += '\n✅ Clasificado a Champions League'
    else if (esPrimeraFrance && pos === 5) msg += '\n✅ Clasificado a Europa League'
    else if (esPrimeraFrance && pos === 6) msg += '\n✅ Clasificado a Conference League'
    else if (esPrimeraFrance && pos >= 17) msg += '\n⚠️ DESCENSO a Ligue 2'
    else if (esPrimeraFrance && pos === 16) msg += '\n⚠️ Playoff de descenso'
    else if (esPrimeraFrance) msg += '\nPermanencia en Ligue 1'
    else if (esSegundaFrance && cambioDivision && pos <= 2) msg += '\n🎉 ¡ASCENSO a Ligue 1!'
    else if (esSegundaFrance && pos <= 5 && pos >= 3) msg += '\n🏆 Accedes a la Fase de Ascenso a Ligue 1'
    else if (esSegundaFrance) msg += '\nPermanencia en Ligue 2'
    else if (esSerieAItaly && pos === 1) msg += '\n🏆 ¡CAMPEÓN DE LA SERIE A!'
    else if (esSerieAItaly && pos <= 4) msg += '\n✅ Clasificado a Champions League'
    else if (esSerieAItaly && pos === 5) msg += '\n✅ Clasificado a Europa League'
    else if (esSerieAItaly && pos === 6) msg += '\n✅ Clasificado a Conference League'
    else if (esSerieAItaly && pos >= 18) msg += '\n⚠️ DESCENSO a Serie B'
    else if (esSerieAItaly) msg += '\nPermanencia en Serie A'
    else if (esSerieBItaly && cambioDivision && pos <= 2) msg += '\n🎉 ¡ASCENSO a Serie A!'
    else if (esSerieBItaly) msg += '\nPermanencia en Serie B'
    else if (esBundesliga && pos >= 17) msg += '\n⚠️ DESCENSO a 2. Bundesliga'
    else if (esBundesliga && pos === 16) msg += '\n⚠️ Playoff de descenso a 2. Bundesliga'
    else if (esBundesliga) msg += '\nPermanencia en Bundesliga'
    else if (esBundesliga2 && cambioDivision && pos <= 2) msg += '\n🎉 ¡ASCENSO a Bundesliga!'
    else if (esBundesliga2 && pos === 3) msg += '\n🏆 Playoff de Ascenso a Bundesliga'
    else if (esBundesliga2) msg += '\nPermanencia en 2. Bundesliga'
    else if (esBundesligaA && cambioDivision) {
      msg += '\n⚠️ DESCENSO a 2. Bundesliga (Austria)'
      if (state._filialRelegue) msg += '\n⚠️ Tu filial desciende autom\u00e1ticamente a la siguiente categor\u00eda.'
    }
    else if (esBundesligaA) msg += '\nPermanencia en Bundesliga de Austria'
    else if (esAscensoFilialBloqueado) msg += '\n🚫 El filial no puede ascender. El primer equipo ya est\u00e1 en la Bundesliga de Austria.'
    else if (esSegundaAustria && cambioDivision) msg += '\n🏆 ¡CAMPEÓN DE LA 2.ª!\n🎉 ¡ASCENSO a la Bundesliga de Austria!'
    else if (esDescensoRegional) msg += '\n⚠️ Descenso a Liga Regional no disponible (sin categor\u00eda inferior): permaneces en 2\u00aa.'
    else if (esSegundaAustria) msg += '\nPermanencia en 2. Bundesliga'
    else if (esTerceraRFEF && cambioDivision && pos === 1) msg += '\n🎉 ¡ASCENSO a Segunda División!'
    else if (esTerceraRFEF && cambioDivision) msg += '\n⚠️ DESCENSO a 2ª División B'
    else if (esTerceraRFEF && esPlayoffTerceraRFEF) msg += '\n🏆 Accedes a la Fase de Ascenso a Segunda División'
    else if (esTerceraRFEF) msg += '\nPermanencia en Primera Federaci\u00f3n'
    else if (noLowerDivision) msg += '\n⚠️ No hay divisiones inferiores. El equipo permanece en la categoría.'
    else msg += '\nPermanencia en la categoría'
  }

  if (esPlayoffTercera) {
    /* Tercera champion — enter playoff for promotion to Segunda B */
    state.players.forEach(p => { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0 })
    document.getElementById('league-results-wrap').classList.add('hidden')
    renderLeague()
    saveGame()
    addNotification('match', `🏆 ${msg}`, 'Fase de Ascenso a Segunda División B')
    setTimeout(() => { alert(msg); iniciarPlayoffTercera() }, 100)
    return
  }

  if (esPlayoffPolaca2) {
    /* lpl2 positions 3-6 — enter promotion playoff to lpl */
    state.players.forEach(p => { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0 })
    document.getElementById('league-results-wrap').classList.add('hidden')
    renderLeague()
    saveGame()
    addNotification('match', `🏆 ${msg}`, 'Playoff de Ascenso a Liga Polaca')
    setTimeout(() => { alert(msg); iniciarPlayoffPolaca2() }, 100)
    return
  }

  if (esPlayoffPolaca3) {
    /* lpl3 positions 3-6 — enter promotion playoff to lpl2 */
    state.players.forEach(p => { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0 })
    document.getElementById('league-results-wrap').classList.add('hidden')
    renderLeague()
    saveGame()
    addNotification('match', `🏆 ${msg}`, 'Playoff de Ascenso a Segunda Polaca')
    setTimeout(() => { alert(msg); iniciarPlayoffPolaca3() }, 100)
    return
  }

  if (esPlayoffDescensoLP3) {
    /* lpl3 positions 13-14 — relegation playoff */
    state.players.forEach(p => { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0 })
    document.getElementById('league-results-wrap').classList.add('hidden')
    renderLeague()
    saveGame()
    addNotification('match', `⚠️ ${msg}`, 'Playoff de Descenso en Tercera Polaca')
    setTimeout(() => { alert(msg); iniciarPlayoffDescensoLP3() }, 100)
    return
  }

  if (esPlayoffAscensoLP4) {
    /* lpl4 position 2 — enter promotion playoff to lpl3 */
    state.players.forEach(p => { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0 })
    document.getElementById('league-results-wrap').classList.add('hidden')
    renderLeague()
    saveGame()
    addNotification('match', `🏆 ${msg}`, 'Playoff de Ascenso a Tercera Polaca')
    setTimeout(() => { alert(msg); iniciarPlayoffAscensoLP4() }, 100)
    return
  }

  if (esPlayoffAscensoPortugal) {
    /* l2p position 3 — promotion playoff vs l1p position 16 */
    state.players.forEach(p => { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0 })
    document.getElementById('league-results-wrap').classList.add('hidden')
    renderLeague()
    saveGame()
    addNotification('match', `🏆 ${msg}`, 'Playoff de Ascenso a Primeira Liga')
    setTimeout(() => { alert(msg); iniciarPlayoffAscensoPortugal() }, 100)
    return
  }

  if (esPlayoffDescensoPortugal) {
    /* l1p position 16 — relegation playoff vs l2p position 3 */
    state.players.forEach(p => { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0 })
    document.getElementById('league-results-wrap').classList.add('hidden')
    renderLeague()
    saveGame()
    addNotification('match', `⚠️ ${msg}`, 'Playoff de Descenso en Primeira Liga')
    setTimeout(() => { alert(msg); iniciarPlayoffDescensoPortugal() }, 100)
    return
  }

  /* Compute season movements for all leagues in the country */
  if (!skipStandings) {
    state.lastSeasonMovements = computeSeasonMovements(state.countryId)
    recordAllTeamsSeasonHistory()
    recordSeasonTrophyWinners()
    if (state.countryId === 'spain') {
      var l1sLeague = window.DB['spain']?.country?.leagues?.find(function(l) { return l.id === 'l1s' })
      if (l1sLeague && state.allLeagueData && state.allLeagueData['l1s']) {
        var l1sIds = l1sLeague.teams.map(function(t) { return t.id })
        state.lastL1sStandings = computeStandings(state.allLeagueData['l1s'].fixtures, l1sIds)
      }
    } else if (state.countryId === 'portugal') {
      var l1pLeague = window.DB['portugal']?.country?.leagues?.find(function(l) { return l.id === 'l1p' })
      if (l1pLeague && state.allLeagueData && state.allLeagueData['l1p']) {
        var l1pIds = l1pLeague.teams.map(function(t) { return t.id })
        state.lastL1pStandings = computeStandings(state.allLeagueData['l1p'].fixtures, l1pIds)
      }
    } else if (state.countryId === 'italy') {
      var saLeague = window.DB['italy']?.country?.leagues?.find(function(l) { return l.id === 'sa' })
      if (saLeague && state.allLeagueData && state.allLeagueData['sa']) {
        var saIds = saLeague.teams.map(function(t) { return t.id })
        state.lastSaStandings = computeStandings(state.allLeagueData['sa'].fixtures, saIds)
      }
    }
  }

  if (esPlayoffSegundaSpain) {
    state.players.forEach(p => { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0 })
    document.getElementById('league-results-wrap').classList.add('hidden')
    renderLeague()
    saveGame()
    addNotification('match', `🏆 ${msg}`, 'Playoff de Ascenso a LaLiga')
    setTimeout(() => { alert(msg); iniciarPlayoffSegundaSpain() }, 100)
    return
  }

  if (esPlayoffTerceraRFEF) {
    state.players.forEach(p => { p.energy = 100; p.injury = null; p.goals = 0; p.matches = 0 })
    document.getElementById('league-results-wrap').classList.add('hidden')
    renderLeague()
    saveGame()
    addNotification('match', `🏆 ${msg}`, 'Playoff de Ascenso a Segunda División')
    setTimeout(() => { alert(msg); iniciarPlayoffTerceraRFEF() }, 100)
    return
  }

  /* Normal season end — detect trophies & logros, show progression modal */
  if (!skipStandings) {
    var nuevosTrofeos = []
    var logros = []
    if (pos === 2) {
      state.leagueRunnerUp = state.teamId
    }
    if (cambioDivision && pos <= 2) {
      logros.push('Ascenso directo de categoría')
    }
    if (pos === 1) {
      var _league2 = getLeagueFromId(state.leagueId)
      var trofeo2 = { competition: 'Campeón de ' + (_league2 ? _league2.name : state.leagueId), season: state.seasonNumber }
      if (!hasTrophy(state.trophies, trofeo2.competition, state.seasonNumber)) state.trophies.push(trofeo2)
      nuevosTrofeos.push(trofeo2)
      state.leagueChampion = state.teamId
      var lSeason = getSeasonLabel()
      var leagueTrofeoUrl = getLeagueTrofeo(_league2)
      addNotification('trophy', '\ud83c\udfc6 \u00a1Campe\u00f3n de ' + (_league2 ? _league2.name : state.leagueId) + '!', 'Temporada ' + lSeason, { logo: leagueTrofeoUrl })
      showTrofeoModal('¡Campeón de ' + (_league2 ? _league2.name : state.leagueId) + '!', 'Temporada ' + lSeason, leagueTrofeoUrl, function() {
        showSeasonProgressionModal(agingResult || { changes: [], retirados: [] }, msg, skipStandings, nuevosTrofeos, logros)
      })
    } else {
      showSeasonProgressionModal(agingResult || { changes: [], retirados: [] }, msg, skipStandings, nuevosTrofeos, logros)
    }
    return
  }

  /* Post-playoff path — compute aging, show progression modal */
  try {
    var postAging = envejecerYProgresar()
    state.lastSeasonMovements = computeSeasonMovements(state.countryId)
    recordAllTeamsSeasonHistory()
    recordSeasonTrophyWinners()
    if (state.countryId === 'spain') {
      var l1sLeague2 = window.DB['spain']?.country?.leagues?.find(function(l) { return l.id === 'l1s' })
      if (l1sLeague2 && state.allLeagueData && state.allLeagueData['l1s']) {
        var l1sIds2 = l1sLeague2.teams.map(function(t) { return t.id })
        state.lastL1sStandings = computeStandings(state.allLeagueData['l1s'].fixtures, l1sIds2)
      }
    } else if (state.countryId === 'portugal') {
      var l1pLeague2 = window.DB['portugal']?.country?.leagues?.find(function(l) { return l.id === 'l1p' })
      if (l1pLeague2 && state.allLeagueData && state.allLeagueData['l1p']) {
        var l1pIds2 = l1pLeague2.teams.map(function(t) { return t.id })
        state.lastL1pStandings = computeStandings(state.allLeagueData['l1p'].fixtures, l1pIds2)
      }
    }
    showSeasonProgressionModal(postAging, extraMsg || '', skipStandings, [], [])
  } catch (err) {
    console.error('[SEASON-POST] Error in post-playoff modal:', err)
    showSeasonProgressionModal({ changes: [], retirados: [] }, extraMsg || '', skipStandings, [], [])
  }
}

function getTerceraGroupIds() {
  return ['l3g1','l3g2','l3g3','l3g4','l3g5','l3g6','l3g7','l3g8','l3g9','l3g10',
          'l3g11','l3g12','l3g13','l3g14','l3g15','l3g16','l3g17','l3g18','l3g19',
          'l3g20','l3g21','l3g23','l3g24']
}

function iniciarPlayoffs(teamIds) {
  state.playoffs = {
    round: 'QF',
    fixtures: [
      { round: 'QF', home: teamIds[0], away: teamIds[7], homeScore: null, awayScore: null, played: false },
      { round: 'QF', home: teamIds[3], away: teamIds[4], homeScore: null, awayScore: null, played: false },
      { round: 'QF', home: teamIds[1], away: teamIds[6], homeScore: null, awayScore: null, played: false },
      { round: 'QF', home: teamIds[2], away: teamIds[5], homeScore: null, awayScore: null, played: false },
    ],
  }
  const msg = `🏆 ¡CLASIFICADO al Playoff! Posición: ${teamIds.indexOf(state.teamId) + 1}º\nRonda: Cuartos de final`
  addNotification('match', msg, 'Eliminatorias por el título')
  document.getElementById('league-results-wrap').classList.add('hidden')
  renderLeague()
  saveGame()
  setTimeout(() => alert(msg), 100)
}

function avanzarRondaPlayoff() {
  const pf = state.playoffs
  if (!pf) return
  /* Playoff Europeo de Austria (Conference): cualquier partida de la ronda
     actual que no implique al usuario se resuelve por CPU para poder avanzar. */
  if (pf.esConferenceAustria) {
    pf.fixtures.forEach(function(f) {
      if (!f.played) {
        var cr = simularPartidoPorRating(f.home, f.away, 'europa')
        f.homeScore = cr.homeScore; f.awayScore = cr.awayScore; f.played = true
      }
    })
  }
  if (pf.esConferenceNed) {
    pf.fixtures.forEach(function(f) {
      if (!f.played) {
        var cne = simularPartidoPorRating(f.home, f.away, 'europa')
        f.homeScore = cne.homeScore; f.awayScore = cne.awayScore; f.played = true
      }
    })
  }
  const allPlayed = pf.fixtures.every(f => f.played)
  if (!allPlayed) return

  const winners = pf.fixtures.map(f => (f.homeScore > f.awayScore ? f.home : f.away))

  if (pf.esConferenceNed) {
    if (pf.round === 'SF') {
      pf.round = 'F'
      pf.fixtures = [
        { round: 'F', home: winners[0], away: winners[1], homeScore: null, awayScore: null, played: false },
      ]
      saveGame()
      return
    }
    if (pf.round === 'F') {
      const ganador = winners[0]
      const esUser = ganador === state.teamId
      addNotification('general', '\ud83c\udf0d ' + getTeamName(ganador) + ' jugar\u00e1 la Fase Previa de la Conference League', 'Playoff Europeo de la Eredivisie')
      state.playoffs = null
      state.conferencePlayoffWinner = ganador
      if (esUser) {
        var trofeoConfNed = { competition: 'Playoff Europeo (Conference League)', season: state.seasonNumber }
        if (!hasTrophy(state.trophies, trofeoConfNed.competition, state.seasonNumber)) state.trophies.push(trofeoConfNed)
        addNotification('trophy', '\ud83c\udfc6 \u00a1Clasificado a la Conference League!', 'Playoff Europeo de la Eredivisie', { logo: getLeagueTrofeo(getLeagueFromId(state.leagueId)) })
      }
      setTimeout(function() { procesarFinTemporada() }, 250)
      return
    }
    return
  }
  if (pf.esConferenceAustria) {
    if (pf.round === 'SF') {
      const sfWinner = winners[0]
      pf.round = 'F'
      pf.fixtures = [
        { round: 'F', home: pf.fifth, away: sfWinner, homeScore: null, awayScore: null, played: false },
      ]
      saveGame()
      return
    }
    if (pf.round === 'F') {
      const ganador = winners[0]
      const esUser = ganador === state.teamId
      const slot = (window.AustriaLiga && window.AustriaLiga.config.playoffEuropeo.prize) || 'Fase Previa de la Conference League'
      addNotification('general', '\ud83c\udf0d ' + getTeamName(ganador) + ' jugar\u00e1 la Fase Previa de la Conference League', 'Playoff Europeo de Austria')
      state.playoffs = null
      state.conferencePlayoffWinner = ganador
      if (esUser) {
        var trofeoConf = { competition: 'Playoff Europeo (Conference League)', season: state.seasonNumber }
        if (!hasTrophy(state.trophies, trofeoConf.competition, state.seasonNumber)) state.trophies.push(trofeoConf)
        addNotification('trophy', '\ud83c\udfc6 \u00a1Clasificado a la Conference League!', 'Playoff Europeo de Austria', { logo: getLeagueTrofeo(getLeagueFromId(state.leagueId)) })
      }
      setTimeout(function() { procesarFinTemporada() }, 250)
      return
    }
    return
  }

  if (pf.esPolaca3 && pf.round === 'SF') {
    /* Polish 3rd div: SF done → check promotion, then F */
    const userFixture = pf.fixtures.find(f => f.home === state.teamId || f.away === state.teamId)
    if (userFixture) {
      const userScore = userFixture.home === state.teamId ? userFixture.homeScore : userFixture.awayScore
      const rivalScore = userFixture.home === state.teamId ? userFixture.awayScore : userFixture.homeScore
      pf.promoted = userScore > rivalScore
    }
    pf.round = 'F'
    pf.fixtures = [
      { round: 'F', home: winners[0], away: winners[1], homeScore: null, awayScore: null, played: false },
    ]
    if (pf.promoted) {
      addNotification('match', '🎉 ¡ASCENSO a Segunda Polaca!', 'Ganaste la semifinal del Playoff de Ascenso')
      setTimeout(() => alert('🎉 ¡ASCENSO a Segunda Polaca!\n\nGanaste la semifinal y consigues el ascenso de categoría.'), 200)
    }
  } else if (pf.esPolaca2 && pf.round === 'SF') {
    /* Polish 2nd div: SF done → check promotion, then F */
    const userFixture = pf.fixtures.find(f => f.home === state.teamId || f.away === state.teamId)
    if (userFixture) {
      const userScore = userFixture.home === state.teamId ? userFixture.homeScore : userFixture.awayScore
      const rivalScore = userFixture.home === state.teamId ? userFixture.awayScore : userFixture.homeScore
      pf.promoted = userScore > rivalScore
    }
    pf.round = 'F'
    pf.fixtures = [
      { round: 'F', home: winners[0], away: winners[1], homeScore: null, awayScore: null, played: false },
    ]
    if (pf.promoted) {
      addNotification('match', '🎉 ¡ASCENSO a Liga Polaca!', 'Ganaste la semifinal del Playoff de Ascenso')
      setTimeout(() => alert('🎉 ¡ASCENSO a Liga Polaca!\n\nGanaste la semifinal y consigues el ascenso de categoría.'), 200)
    }
  } else if (pf.esPlayoffSegundaSpain && pf.round === 'SF') {
    const userFixture = pf.fixtures.find(f => f.home === state.teamId || f.away === state.teamId)
    if (userFixture) {
      const userScore = userFixture.home === state.teamId ? userFixture.homeScore : userFixture.awayScore
      const rivalScore = userFixture.home === state.teamId ? userFixture.awayScore : userFixture.homeScore
      pf.promoted = userScore > rivalScore
    }
    pf.round = 'F'
    pf.fixtures = [
      { round: 'F', home: winners[0], away: winners[1], homeScore: null, awayScore: null, played: false },
    ]
    if (pf.promoted) {
      addNotification('match', '🎉 ¡ASCENSO a LaLiga!', 'Ganaste la semifinal del Playoff de Ascenso')
      setTimeout(() => alert('🎉 ¡ASCENSO a LaLiga!\n\nGanaste la semifinal y consigues el ascenso de categoría.'), 200)
    }
  } else if (pf.esPlayoffTerceraRFEF && pf.round === 'SF') {
    const userFixture = pf.fixtures.find(f => f.home === state.teamId || f.away === state.teamId)
    if (userFixture) {
      const userScore = userFixture.home === state.teamId ? userFixture.homeScore : userFixture.awayScore
      const rivalScore = userFixture.home === state.teamId ? userFixture.awayScore : userFixture.homeScore
      pf.promoted = userScore > rivalScore
    }
    pf.round = 'F'
    pf.fixtures = [
      { round: 'F', home: winners[0], away: winners[1], homeScore: null, awayScore: null, played: false },
    ]
    if (pf.promoted) {
      addNotification('match', '🎉 ¡A la Final!', 'Ganaste la semifinal del Playoff de Ascenso a Segunda')
      setTimeout(() => alert('🎉 ¡A la final!\n\nGanaste la semifinal. Ahora te juegas el ascenso a Segunda División.'), 200)
    }
  } else if (pf.esTercera && pf.round === 'SF') {
    /* Tercera: SF done → check promotion, then F */
    const userFixture = pf.fixtures.find(f => f.home === state.teamId || f.away === state.teamId)
    if (userFixture) {
      const userScore = userFixture.home === state.teamId ? userFixture.homeScore : userFixture.awayScore
      const rivalScore = userFixture.home === state.teamId ? userFixture.awayScore : userFixture.homeScore
      pf.promoted = userScore > rivalScore
    }
    pf.round = 'F'
    pf.fixtures = [
      { round: 'F', home: winners[0], away: winners[1], homeScore: null, awayScore: null, played: false },
    ]
    if (pf.promoted) {
      addNotification('match', '🎉 ¡ASCENSO a 2ª División B!', 'Ganaste la semifinal de la Fase de Ascenso')
      setTimeout(() => alert('🎉 ¡ASCENSO a 2ª División B!\n\nGanaste la semifinal y consigues el ascenso de categoría.'), 200)
    }
  } else if (pf.esAscensoLP4 && pf.round === 'SF') {
    const userFixture = pf.fixtures.find(f => f.home === state.teamId || f.away === state.teamId)
    const userWon = userFixture && (
      (userFixture.home === state.teamId && userFixture.homeScore > userFixture.awayScore) ||
      (userFixture.away === state.teamId && userFixture.awayScore > userFixture.homeScore)
    )
    if (userWon) {
      pf.promoted = true
      pf.round = 'F'
      pf.fixtures = [
        { round: 'F', home: winners[0], away: winners[1], homeScore: null, awayScore: null, played: false },
      ]
      addNotification('match', '🎉 ¡A la Final!', 'Ganaste la semifinal del Playoff de Ascenso')
      setTimeout(() => alert('🎉 ¡A la final!\n\nGanaste la semifinal. Ahora te juegas el ascenso en la final.'), 200)
      saveGame()
    } else {
      const msg = '❌ Eliminado en semifinales.\n\nNo lograste el ascenso. Una temporada más en Cuarta Polaca.'
      addNotification('match', '❌ Eliminado', 'No lograste superar la semifinal del Playoff de Ascenso')
      state.playoffs = null
      setTimeout(() => { procesarFinTemporada(true, true, msg) }, 200)
    }
    return
  } else if (pf.esAscensoLP4 && pf.round === 'F') {
    const ganador = winners[0]
    const esGanador = ganador === state.teamId
    state.playoffs = null
    if (esGanador) {
      state.leagueId = 'lpl3'
      setTimeout(() => {
        procesarFinTemporada(true, true, '🎉 ¡ASCENSO a Tercera Polaca!\n\nGanaste el playoff de ascenso desde Cuarta Polaca.')
      }, 300)
    } else {
      setTimeout(() => {
        procesarFinTemporada(true, true, '❌ Perdiste la final.\n\nNo lograste el ascenso. Una temporada más en Cuarta Polaca.')
      }, 300)
    }
    return
  } else if (pf.round === 'QF') {
    pf.round = 'SF'
    pf.fixtures = [
      { round: 'SF', home: winners[0], away: winners[3], homeScore: null, awayScore: null, played: false },
      { round: 'SF', home: winners[1], away: winners[2], homeScore: null, awayScore: null, played: false },
    ]
  } else if (pf.round === 'SF' && !pf.esTercera) {
    pf.round = 'F'
    pf.fixtures = [
      { round: 'F', home: winners[0], away: winners[1], homeScore: null, awayScore: null, played: false },
    ]
  } else if (pf.round === 'F') {
    const campeon = winners[0]
    const subcampeon = winners[0] === pf.fixtures[0].home ? pf.fixtures[0].away : pf.fixtures[0].home
    const esCampeon = campeon === state.teamId
    const esTercera = pf.esTercera
    const esPolaca2 = pf.esPolaca2
    const esPolaca3 = pf.esPolaca3
    const esPlayoffSegundaSpain = pf.esPlayoffSegundaSpain
    const esPlayoffTerceraRFEF = pf.esPlayoffTerceraRFEF
    const promovio = pf.promoted
    const msg = `🏆 ${esCampeon ? '¡CAMPEÓN!' : 'Subcampeón'} — ${esCampeon ? 'Ganaste el título' : 'El campeón es ' + getTeamName(campeon)}`
    addNotification('match', msg, 'Playoff finalizado')
    state.playoffs = null
    if (esPlayoffSegundaSpain) {
      if (promovio) {
        var desdeCategoriasPrevias = state.leagueId && (state.leagueId.startsWith('l3sg') || state.leagueId.startsWith('l2b'))
        state.leagueId = desdeCategoriasPrevias ? 'l2s' : 'l1s'
        var targetName = desdeCategoriasPrevias ? 'Segunda División' : 'LaLiga'
        setTimeout(() => {
          procesarFinTemporada(true, true, `${msg}\n\n${esCampeon ? '¡Ascenso a ' + targetName + ' y título!' : 'Ascenso a ' + targetName + ' conseguido'}`)
        }, 300)
      } else {
        setTimeout(() => {
          const divName2 = state.leagueId && state.leagueId.startsWith('l3sg') ? 'Primera Federaci\u00f3n' : 'Segunda División'
          procesarFinTemporada(true, true, `${msg}\n\nNo lograste el ascenso. Una temporada más en ${divName2}.`)
        }, 300)
      }
    } else if (esPlayoffTerceraRFEF) {
      if (esCampeon) {
        state.leagueId = 'l2s'
        setTimeout(() => {
          procesarFinTemporada(true, true, `${msg}\n\n${esCampeon ? '¡Ascenso a Segunda División y título!' : 'Ascenso a Segunda División conseguido'}`)
        }, 300)
      } else {
        setTimeout(() => {
          procesarFinTemporada(true, true, `${msg}\n\nNo lograste el ascenso. Una temporada más en Primera Federación.`)
        }, 300)
      }
    } else if (esPolaca3) {
      if (promovio) {
        state.leagueId = 'lpl2'
        setTimeout(() => {
          procesarFinTemporada(true, true, `${msg}\n\n${esCampeon ? '¡Ascenso a Segunda Polaca y título!' : 'Ascenso a Segunda Polaca conseguido'}`)
        }, 300)
      } else {
        setTimeout(() => {
          procesarFinTemporada(true, true, `${msg}\n\nNo lograste el ascenso. Una temporada más en Tercera Polaca.`)
        }, 300)
      }
    } else if (esPolaca2) {
      if (promovio) {
        state.leagueId = 'lpl'
        setTimeout(() => {
          procesarFinTemporada(true, true, `${msg}\n\n${esCampeon ? '¡Ascenso a Liga Polaca y título!' : 'Ascenso a Liga Polaca conseguido'}`)
        }, 300)
      } else {
        setTimeout(() => {
          procesarFinTemporada(true, true, `${msg}\n\nNo lograste el ascenso. Una temporada más en Segunda Polaca.`)
        }, 300)
      }
    } else if (esTercera) {
      /* Tercera playoff complete */
      if (promovio) {
        const gruposB = ['l2b1','l2b2','l2b3','l2b4','l2b5','l2b6']
        state.leagueId = pickRandom(gruposB)
        setTimeout(() => {
          procesarFinTemporada(true, true, `${msg}\n\n${esCampeon ? '¡Ascenso y título!' : 'Ascenso conseguido'}`)
        }, 300)
      } else {
        setTimeout(() => {
          procesarFinTemporada(true, true, `${msg}\n\nNo lograste el ascenso. Una temporada más en 3ª División.`)
        }, 300)
      }
    } else if (pf.esDescensoLP3) {
      const ganador = winners[0]
      const perdedor = ganador === pf.fixtures[0].home ? pf.fixtures[0].away : pf.fixtures[0].home
      const salvado = ganador === state.teamId
      const msgD = `⚔️ Playoff Descenso — ${salvado ? '¡PERMANENCIA!' : 'DESCENSO'}`
      addNotification('match', msgD, salvado ? 'Te quedas en Tercera Polaca' : 'Bajas a Cuarta Polaca')
      if (salvado) {
        setTimeout(() => {
          procesarFinTemporada(true, true, '✅ ¡PERMANENCIA!\n\nGanaste el playoff de descenso. Una temporada más en Tercera Polaca.')
        }, 300)
      } else {
        const grupos4 = ['lpl4g1','lpl4g2','lpl4g3','lpl4g4']
        state.leagueId = pickRandom(grupos4)
        setTimeout(() => {
          procesarFinTemporada(true, true, '❌ DESCENSO a Cuarta Polaca.\n\nPerdiste el playoff de descenso.')
        }, 300)
      }
    } else if (pf.esPlayoffPortugal) {
      const ganador = winners[0]
      const ganadorUser = ganador === state.teamId
      if (pf.esAscenso) {
        /* User was l2p P3, playing to ascend */
        if (ganadorUser) {
          state.leagueId = 'l1p'
          setTimeout(() => {
            procesarFinTemporada(true, true, '🎉 ¡ASCENSO a Primeira Liga!\n\nGanaste el playoff de ascenso desde Segunda Liga Portugal.')
          }, 300)
        } else {
          setTimeout(() => {
            procesarFinTemporada(true, true, '❌ No lograste el ascenso.\n\nUna temporada más en Segunda Liga Portugal.')
          }, 300)
        }
      } else {
        /* User was l1p P16, playing to stay */
        if (ganadorUser) {
          setTimeout(() => {
            procesarFinTemporada(true, true, '✅ ¡PERMANENCIA!\n\nGanaste el playoff de descenso. Una temporada más en Primeira Liga.')
          }, 300)
        } else {
          state.leagueId = 'l2p'
          setTimeout(() => {
            procesarFinTemporada(true, true, '❌ DESCENSO a Segunda Liga Portugal.\n\nPerdiste el playoff de descenso.')
          }, 300)
        }
      }
    } else {
      /* LNFS or other championship playoff */
      if (esCampeon) {
        var league = getLeagueFromId(state.leagueId)
        var playoffTrofeo = { competition: 'Campeón de ' + (league ? league.name : state.leagueId), season: state.seasonNumber }
        if (!hasTrophy(state.trophies, playoffTrofeo.competition, state.seasonNumber)) state.trophies.push(playoffTrofeo)
        addNotification('trophy', '\ud83c\udfc6 \u00a1Campe\u00f3n de ' + (league ? league.name : state.leagueId) + '!', 'Temporada ' + getSeasonLabel(), { logo: getLeagueTrofeo(league) })
      }
      setTimeout(() => { procesarFinTemporada() }, 100)
    }
    return
  }
  saveGame()
}

function iniciarPlayoffTercera() {
  const gruposT = getTerceraGroupIds()
  const otherChampions = []
  for (const gid of gruposT) {
    if (gid === state.leagueId) continue
    const league = getLeagueFromId(gid)
    if (!league || !league.teams) continue
    otherChampions.push(pickRandom(league.teams).id)
  }
  otherChampions.sort(() => Math.random() - 0.5)
  const selectedOthers = otherChampions.slice(0, 3)

  state.playoffs = {
    round: 'SF',
    fixtures: [
      { round: 'SF', home: state.teamId, away: selectedOthers[0], homeScore: null, awayScore: null, played: false },
      { round: 'SF', home: selectedOthers[1], away: selectedOthers[2], homeScore: null, awayScore: null, played: false },
    ],
    esTercera: true,
    promoted: false,
  }
  const rivalName = getTeamName(selectedOthers[0])
  addNotification('match', '🏆 Fase de Ascenso — Semifinal', `Te enfrentas a ${rivalName} por el ascenso a 2ª División B`)
  saveGame()
}

